import subprocess, tempfile, os, re
def css(hue=220,sat=100,gamma=80):
    d=tempfile.mkdtemp()
    open(os.path.join(d,"cfg"),"w").write(f"HTML_COLORSTYLE_HUE={hue}\nHTML_COLORSTYLE_SAT={sat}\nHTML_COLORSTYLE_GAMMA={gamma}\n")
    subprocess.run(["/workspace/executable","-w","html","h","f","s","cfg"],cwd=d,capture_output=True)
