    m2=re.search(r"--header-separator-color: ([^;]+);",txt)
    m3=re.search(r"--index-odd-item-bg-color: ([^;]+);",txt)
    return m.group(1),m2.group(1),m3.group(1)
for sat in [0,50,100,150,200,255]:
    print("sat",sat,css(sat=sat))
for gamma in [40,80,100,150,240]:
    print("gamma",gamma,css(gamma=gamma))
for hue in [0,60,120,220,300]:
    print("hue",hue,css(hue=hue))
