import re, colorsys, subprocess, tempfile, os
def getcss(cfg):
    d=tempfile.mkdtemp(); open(os.path.join(d,"cfg"),"w").write(cfg)
    subprocess.run(["/workspace/executable","-w","html","h","f","s","cfg"],cwd=d,capture_output=True)
    return open(os.path.join(d,"s")).read()
default=getcss("")
sat0=getcss("HTML_COLORSTYLE_SAT=0\n")
# align line by line
dl=default.splitlines(); sl=sat0.splitlines()
changed={}
unchanged=set()
for a,b in zip(dl,sl):
    ca=re.findall(r"#[0-9A-Fa-f]{6}\b|#[0-9A-Fa-f]{3}\b",a)
    cb=re.findall(r"#[0-9A-Fa-f]{6}\b|#[0-9A-Fa-f]{3}\b",b)
    if ca!=cb:
        for x,y in zip(ca,cb): changed[x.upper()]=y.upper()
    else:
        for x in ca: unchanged.add(x.upper())
print("changed distinct",len(changed),"unchanged distinct",len(unchanged))
# distribution of HLS S for changed
from collections import Counter
cnt=Counter()
for hx in changed:
    if len(hx)==4: continue
    r,g,b=[int(hx[i:i+2],16)/255 for i in (1,3,5)]
    h,l,s=colorsys.rgb_to_hls(r,g,b)
    cnt[round(s*255)]+=1
print("S*255 distribution changed",sorted(cnt.items())[:30], "... total keys",len(cnt))
print("examples changed",list(changed.items())[:20])
print("unchanged examples",sorted(unchanged)[:40])
PY"}

