import re, colorsys, subprocess, tempfile, os
def getcss(cfg):
    d=tempfile.mkdtemp(); open(os.path.join(d,"cfg"),"w").write(cfg)
    subprocess.run(["/workspace/executable","-w","html","h","f","s","cfg"],cwd=d,capture_output=True)
    return open(os.path.join(d,"s")).read()
def hls(hx):
    hx=hx.lstrip('#')
    if len(hx)==3: hx=''.join(c*2 for c in hx)
    r,g,b=[int(hx[i:i+2],16)/255 for i in (0,2,4)]
    h,l,s=colorsys.rgb_to_hls(r,g,b); return f"H{h*360:.0f} L{l*255:.1f} S{s*255:.1f}"
def line(css,var):
    m=re.search(rf"{re.escape(var)}: ([^;]+);",css); return m.group(1) if m else None
cssd=getcss("")
# find vars whose color S far from 100
vars=[]
for m in re.finditer(r"(--[\w-]+):\s*(#[0-9A-Fa-f]{6});",cssd):
    vars.append((m.group(1),m.group(2)))
for sat in [0,50,100,200]:
    css=getcss(f"HTML_COLORSTYLE_SAT={sat}\n")
    print("sat",sat)
    for var,col in vars[:8]:
        c=line(css,var); print(" ",var,c,hls(c) if c.startswith("#") else "")
    # print a low-S one
    print()
# find low S vars in default
lows=[]
for var,col in vars:
    hx=col[1:]; r,g,b=[int(hx[i:i+2],16)/255 for i in (0,2,4)]; h,l,s=colorsys.rgb_to_hls(r,g,b)
    if s*255<95 and abs(h*360-220)<10: lows.append((var,col,round(s*255,1)))
print("lows",lows[:20])
# gamma effect on L: for page-link, L at gamma G: observed L 160@40,100.5@80,79.5@100,44.5@150,15@240
# try formula L_out = 255 * (L_base/255)^(G/100) ??? solve L_base from gamma100 => L_base=79.5? then gamma80: 255*(79.5/255)^0.8=100.5? compute
for G in [40,80,100,150,240]:
    print(G, 255*(79.5/255)**(G/100), 255*(80/255)**(G/100))
PY"}

