import subprocess,tempfile,os,hashlib
def sig(cfg):
    d=tempfile.mkdtemp(); open(os.path.join(d,"cfg"),"w").write(cfg)
    p=subprocess.run(["/workspace/executable","-w","html","h","f","s","cfg"],cwd=d,capture_output=True,text=True)
    out={}
    for fn in ["h","f","s"]:
        fp=os.path.join(d,fn); out[fn]=hashlib.md5(open(fp,'rb').read()).hexdigest()[:8] if os.path.exists(fp) else None
    print(repr(cfg[:80]),p.returncode,out,repr(p.stderr[:200]))
for v in ["LIGHT","DARK","AUTO_LIGHT","AUTO_DARK","TOGGLE","BOGUS"]:
    sig(f"HTML_COLORSTYLE={v}\n")
sig("HTML_TIMESTAMP=YES\n")
sig("PROJECT_NAME=Foo\nPROJECT_NUMBER=1.0\n")
sig("HTML_HEADER=foo\n")
sig("DISABLE_INDEX=YES\nGENERATE_TREEVIEW=YES\nSEARCHENGINE=YES\n")
# latex variants
def sigL(cfg):
    d=tempfile.mkdtemp(); open(os.path.join(d,"cfg"),"w").write(cfg)
    p=subprocess.run(["/workspace/executable","-w","latex","h","f","s","cfg"],cwd=d,capture_output=True,text=True)
    out={fn:(hashlib.md5(open(os.path.join(d,fn),'rb').read()).hexdigest()[:8] if os.path.exists(os.path.join(d,fn)) else None) for fn in ["h","f","s"]}
    print("latex",repr(cfg[:80]),p.returncode,out,repr(p.stderr[:200]))
for v in ["PAPER_TYPE=a4\n","PAPER_TYPE=letter\n","LATEX_BATCHMODE=YES\n","PDF_HYPERLINKS=NO\n","COMPACT_LATEX=YES\n","LATEX_BIB_STYLE=plain\n"]:
    sigL(v)
PY"}

