    m=re.match(r'^([A-Z0-9_]+)\s*=',l)
    if m and m.group(1) in enums:
        j=idx-1; comments=[]
        while j>=0 and (full[j].startswith('#') or full[j]==''):
            comments.append(full[j][2:] if full[j].startswith('# ') else full[j][1:] if full[j].startswith('#') else '')
            j-=1
        text=' '.join(c.strip() for c in comments[::-1])
        mm=re.search(r'Possible values are: (.+?)\. The default value is',text)
        segments[m.group(1)]= mm.group(1) if mm else ""
        print(m.group(1),"=>",segments[m.group(1)][:200])

