"""Doxyfile parsing, validation and writing.

The reference tool keeps configuration values internally as strings and
interprets them on demand.  That is observable, for instance, in the way
``-u`` writes back the exact spelling a user used for a boolean
(``GENERATE_HTML = no``) while ``-x`` only reports the option when its
interpreted value differs from the default.  This module mirrors that
model: every scalar option is stored as the (unquoted) string that was
read, list options as a list of such strings, and typed interpretation
happens in the getters / the validation pass.
"""

import os
import re
import sys

from . import resources
from .config_meta import ENUM_VALUES, INT_RANGES, LIST_TAGS

VERSION = "1.17.0"
VERSION_FULL = "1.17.0 (e5ae56451b5cdb692a5f8fd7f914488e85b33721)"

_ENV_RE = re.compile(r"\$\(([A-Za-z_][A-Za-z0-9_.\-]*)\)")
_IDENT_RE = re.compile(r"[A-Za-z0-9_]+")
_INT_RE = re.compile(r"^[+-]?[0-9]+$")

TRUE_WORDS = {"yes", "true", "1"}
FALSE_WORDS = {"no", "false", "0"}

# Tags that were reported by the reference executable as belonging to an
# option that was not enabled at compile time.
DISABLED_TAGS = {
    "CLANG_ASSISTED_PARSING",
    "CLANG_DATABASE_PATH",
    "CLANG_OPTIONS",
}

# Obsolete tags.  Most are simply dropped; the ones with a conversion are
# handled in Config._convert_obsolete().
OBSOLETE_TAGS = {
    "HTML_TIMESTAMP",
    "LATEX_TIMESTAMP",
    "USE_WINDOWS_ENCODING",
    "DETAILS_AT_TOP",
    "QTHELP_FILE",
    "QTHELP_CONFIG",
    "SYMBOL_CACHE_SIZE",
    "XML_SCHEMA",
    "XML_DTD",
    "COLS_IN_ALPHA_INDEX",
    "SHOW_DIRECTORIES",
    "MSCGEN_PATH",
    "DOT_TRANSPARENT",
    "DOT_FONTNAME",
    "DOT_FONTSIZE",
    "CLASS_DIAGRAMS",
    "DOCBOOK_PROGRAMLISTING",
    "FORMULA_TRANSPARENT",
    "MAX_DOT_GRAPH_WIDTH",
    "MAX_DOT_GRAPH_HEIGHT",
}


class ConfigError(Exception):
    """Fatal configuration error; message is printed to stderr."""


def expand_env(text):
    return _ENV_RE.sub(lambda m: os.environ.get(m.group(1), ""), text)


def quote_if_needed(value):
    """Format a value the way the reference writes it in a Doxyfile."""
    if value == "":
        return ""
    if any(c in value for c in (' ', '\t', '#', ',')):
        return '"' + value.replace('"', '\\"') + '"'
    return value


def _format_assignment(tag, formatted_items):
    """formatted_items: list of already quoted strings (may be empty)."""
    prefix = tag.ljust(23) + "="
    if not formatted_items:
        return prefix
    lines = []
    for i, item in enumerate(formatted_items):
        if i == 0:
            line = prefix + " " + item
        else:
            line = " " * 25 + item
        if i != len(formatted_items) - 1:
            line += " \\"
        lines.append(line)
    return "\n".join(lines)


def _unescape_quoted(text):
    # Inside double quotes a backslash only escapes a double quote.
    return text.replace('\\"', '"')


def _drop_one_trailing_space(value):
    # The reference drops exactly one trailing space from the contents of
    # a quoted value when storing it (observable with -u).
    if value.endswith(" "):
        return value[:-1]
    return value


def parse_scalar_value(raw, tag, line, filename, warnings):
    """Parse the right hand side for a non-list option.

    Returns the stored string.  ``warnings`` is a callable taking a
    message string (already terminated with a newline).
    """
    text = raw.strip(" \t")
    if '"' not in text:
        return text
    # Properly quoted: a single quoted string spanning the whole value.
    if text.startswith('"'):
        i = 1
        n = len(text)
        while i < n:
            c = text[i]
            if c == "\\" and i + 1 < n and text[i + 1] == '"':
                i += 2
                continue
            if c == '"':
                break
            i += 1
        if i == n - 1 and text[i] == '"':
            return _drop_one_trailing_space(_unescape_quoted(text[1:i]))
    warnings(
        f"warning: Invalid value for '{tag}' tag at line {line}, file {filename}: "
        f"Value '{text}' is not properly quoted\n"
    )
    # Remove all unescaped quote characters, unescape \" afterwards.
    out = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == "\\" and i + 1 < len(text) and text[i + 1] == '"':
            out.append('"')
            i += 2
        elif c == '"':
            i += 1
        else:
            out.append(c)
            i += 1
    return "".join(out)


def parse_list_value(raw, tag, line, filename, warnings):
    """Parse the right hand side for a list option into a list of strings."""
    text = raw.strip(" \t")
    items = []
    cur = []
    has_cur = False
    in_quote = False
    not_separated = False
    not_quoted = False
    i = 0
    n = len(text)

    def flush():
        nonlocal cur, has_cur
        if has_cur:
            items.append("".join(cur))
        cur = []
        has_cur = False

    while i < n:
        c = text[i]
        if in_quote:
            if c == "\\" and i + 1 < n and text[i + 1] == '"':
                cur.append('"')
                i += 2
                continue
            if c == '"':
                in_quote = False
                # A quoted item ends here; if the next character is not a
                # separator the values are not properly separated.
                # Trailing space inside the quotes: one is dropped.
                joined = _drop_one_trailing_space("".join(cur))
                cur = [joined] if joined else ([] if not "".join(cur) else [joined])
                if i + 1 < n and text[i + 1] not in " \t,":
                    not_separated = True
                    flush()
                i += 1
                continue
            cur.append(c)
            has_cur = True
            i += 1
            continue
        else:
            if c in " \t,":
                flush()
                i += 1
                continue
            if c == '"':
                if has_cur:
                    not_separated = True
                in_quote = True
                has_cur = True
                i += 1
                continue
            cur.append(c)
            has_cur = True
            i += 1
            continue
    if in_quote:
        not_quoted = True
    flush()
    # Empty quoted items are dropped (e.g. INPUT = "" is an empty list).
    items = [it for it in items if it != ""]
    if not_separated:
        warnings(
            f"warning: Invalid value for '{tag}' tag at line {line}, file {filename}: "
            f"Values in list '{text}' are not properly space or comma separated\n"
        )
    if not_quoted:
        warnings(
            f"warning: Invalid value for '{tag}' tag at line {line}, file {filename}: "
            f"Values in list '{text}' are not properly quoted\n"
        )
    return items


class _Template:
    """Parses the short template to get option order and defaults."""

    def __init__(self):
        self.order = []
        self.defaults_raw = {}
        text = resources.get_text("doxyfile_short.txt")
        logical = []
        buf = ""
        for ln in text.splitlines():
            buf = buf + "\n" + ln if buf else ln
            if ln.rstrip().endswith("\\"):
                continue
            logical.append(buf)
            buf = ""
        if buf:
            logical.append(buf)
        for ln in logical:
            m = re.match(r"^([A-Z0-9_]+)\s*=\s?(.*)$", ln, re.S)
            if m:
                tag = m.group(1)
                self.order.append(tag)
                # Collapse continuation line breaks into a space, the same
                # way config values are read.
                raw = m.group(2).replace("\\\n", " ")
                raw = re.sub(r"\n\s*", " ", raw)
                self.defaults_raw[tag] = raw

    def tag_type(self, tag):
        if tag in LIST_TAGS:
            return "list"
        if tag in INT_RANGES:
            return "int"
        if tag in ENUM_VALUES:
            return "enum"
        raw = self.defaults_raw.get(tag, "")
        if raw in ("YES", "NO"):
            return "bool"
        return "string"

    def default_value(self, tag):
        typ = self.tag_type(tag)
        raw = self.defaults_raw.get(tag, "")
        if typ == "list":
            return parse_list_value(raw, tag, 1, "<template>", lambda m: None)
        return parse_scalar_value(raw, tag, 1, "<template>", lambda m: None)


_TEMPLATE = None


def get_template():
    global _TEMPLATE
    if _TEMPLATE is None:
        _TEMPLATE = _Template()
    return _TEMPLATE


class Config:
    def __init__(self):
        self._tpl = get_template()
        self.order = list(self._tpl.order)
        # tag -> stored value: str for scalars, list[str] for lists.
        self._values = {}
        self._user_set = set()
        self._defaults = {t: self._tpl.default_value(t) for t in self.order}
        for t in self.order:
            default = self._defaults[t]
            self._values[t] = list(default) if isinstance(default, list) else default
        # Obsolete values collected during parsing (tag -> string value).
        self._obsolete = {}
        self._class_diagrams_seen = None  # raw value of CLASS_DIAGRAMS

    # -- metadata -------------------------------------------------------
    def tag_type(self, tag):
        return self._tpl.tag_type(tag)

    def known(self, tag):
        return tag in self._values

    def default(self, tag):
        return self._defaults[tag]

    def user_set(self, tag):
        return tag in self._user_set

    def set_value(self, tag, value, user=True):
        self._values[tag] = value
        if user:
            self._user_set.add(tag)

    def raw(self, tag):
        return self._values[tag]

    # -- typed getters (checked semantics) -------------------------------
    def get_string(self, tag):
        v = self._values[tag]
        assert isinstance(v, str)
        return v.strip(" \t")

    def get_bool(self, tag):
        v = self._values[tag].strip(" \t") if isinstance(self._values[tag], str) else ""
        if v == "":
            return self._defaults[tag] in ("YES",) or _bool_of(self._defaults[tag])
        low = v.lower()
        if low in TRUE_WORDS:
            return True
        if low in FALSE_WORDS:
            return False
        return _bool_of(self._defaults[tag])

    def get_int(self, tag):
        v = self._values[tag].strip(" \t") if isinstance(self._values[tag], str) else "0"
        if v == "" or not _INT_RE.match(v):
            try:
                return int(self._defaults[tag])
            except Exception:
                return 0
        val = int(v)
        lo, hi = INT_RANGES.get(tag, (val, val))
        if val < lo or val > hi:
            return int(self._defaults[tag])
        return val

    def get_enum(self, tag):
        v = self._values[tag].strip(" \t") if isinstance(self._values[tag], str) else ""
        if v == "":
            return self._defaults[tag]
        for canon in ENUM_VALUES.get(tag, []):
            if canon.lower() == v.lower():
                return canon
        return self._defaults[tag]

    def get_list(self, tag):
        v = self._values[tag]
        assert isinstance(v, list)
        return [item.strip(" \t") for item in v]

    def get(self, tag):
        typ = self.tag_type(tag)
        if typ == "bool":
            return self.get_bool(tag)
        if typ == "int":
            return self.get_int(tag)
        if typ == "enum":
            return self.get_enum(tag)
        if typ == "list":
            return self.get_list(tag)
        return self.get_string(tag)

    # -- validation ------------------------------------------------------
    def validate(self, warn):
        """Emit messages for invalid bool/int/enum values and reset them
        to their defaults, and strip string values.  Iterates options in
        template order (which is the order the reference uses)."""
        for tag in self.order:
            typ = self.tag_type(tag)
            if typ == "list":
                continue
            raw = self._values[tag]
            stripped = raw.strip(" \t")
            if typ == "string":
                self._values[tag] = stripped
            elif typ == "bool":
                if stripped == "":
                    continue
                low = stripped.lower()
                if low not in TRUE_WORDS and low not in FALSE_WORDS:
                    warn(
                        f"warning: argument '{stripped}' for option {tag} is not a "
                        f"valid boolean value\nUsing the default: {self._defaults[tag]}!\n"
                    )
                    self._values[tag] = self._defaults[tag]
            elif typ == "int":
                if stripped == "":
                    continue
                lo, hi = INT_RANGES[tag]
                ok = bool(_INT_RE.match(stripped)) and lo <= int(stripped) <= hi
                if not ok:
                    warn(
                        f"warning: argument '{stripped}' for option {tag} is not a "
                        f"valid number in the range [{lo}..{hi}]!\n"
                        f"Using the default: {self._defaults[tag]}!\n"
                    )
                    self._values[tag] = self._defaults[tag]
            elif typ == "enum":
                if stripped == "":
                    continue
                canon = None
                for c in ENUM_VALUES[tag]:
                    if c.lower() == stripped.lower():
                        canon = c
                        break
                if canon is None:
                    warn(
                        f"warning: argument '{stripped}' for option {tag} is not a "
                        f"valid enum value\nUsing the default: {self._defaults[tag]}!\n"
                    )
                    self._values[tag] = self._defaults[tag]
                else:
                    self._values[tag] = canon

    # Equality of the checked value against the default (for -x).
    def differs_from_default(self, tag):
        typ = self.tag_type(tag)
        if typ == "bool":
            return self.get_bool(tag) != _bool_of(self._defaults[tag])
        if typ == "int":
            return self.get_int(tag) != int(self._defaults[tag])
        if typ == "enum":
            return self.get_enum(tag) != self._defaults[tag]
        if typ == "list":
            return self.get_list(tag) != list(self._defaults[tag])
        return self.get_string(tag) != self._defaults[tag].strip(" \t")

    # -- writing ---------------------------------------------------------
    def format_value(self, tag, checked):
        """Return the formatted assignment line(s) for an option."""
        typ = self.tag_type(tag)
        if typ == "list":
            items = self.get_list(tag) if checked else list(self._values[tag])
            return _format_assignment(tag, [quote_if_needed(i) for i in items])
        if checked:
            if typ == "enum":
                return _format_assignment(tag, [quote_if_needed(self.get_enum(tag))])
            # bool/int/string in checked mode: the stored (stripped) string.
            return _format_assignment(tag, [quote_if_needed(self._values[tag].strip(" \t"))] if self._values[tag].strip(" \t") != "" else [])
        else:
            raw = self._values[tag]
            return _format_assignment(tag, [quote_if_needed(raw)] if raw != "" else [])

    def write_template(self, short, checked=False):
        """Render a full Doxyfile with this config's values filled in."""
        template = resources.get_text(
            "doxyfile_short.txt" if short else "doxyfile_full.txt"
        )
        out_lines = []
        lines = template.split("\n")
        i = 0
        n = len(lines)
        while i < n:
            line = lines[i]
            m = re.match(r"^([A-Z0-9_]+)\s*=", line)
            if m and m.group(1) in self._values:
                tag = m.group(1)
                # Skip continuation lines belonging to this assignment.
                j = i
                while lines[j].rstrip().endswith("\\") and j + 1 < n:
                    j += 1
                out_lines.append(self.format_value(tag, checked))
                i = j + 1
            else:
                out_lines.append(line)
                i += 1
        return "\n".join(out_lines)

    def write_difference(self):
        out = [
            f"# Difference with default Doxyfile {VERSION_FULL}\n",
        ]
        for tag in self.order:
            if self.differs_from_default(tag):
                out.append(self.format_value(tag, checked=True) + "\n")
        return "".join(out)

    # -- obsolete conversions ---------------------------------------------
    def _convert_obsolete(self, warn):
        obs = self._obsolete
        # HTML_TIMESTAMP / LATEX_TIMESTAMP -> TIMESTAMP = YES when true.
        for old in ("HTML_TIMESTAMP", "LATEX_TIMESTAMP"):
            if old in obs and obs[old].strip(" \t").lower() in TRUE_WORDS:
                self._values["TIMESTAMP"] = "YES"
                self._user_set.add("TIMESTAMP")
        # CLASS_DIAGRAMS = NO -> CLASS_GRAPH = TEXT (unless CLASS_GRAPH set)
        if self._class_diagrams_seen is not None:
            val = self._class_diagrams_seen.strip(" \t").lower()
            if val in FALSE_WORDS and "CLASS_GRAPH" not in self._user_set:
                warn(
                    "warning: Changing CLASS_GRAPH option to TEXT because "
                    "obsolete option CLASS_DIAGRAM was found and set to NO.\n"
                )
                self._values["CLASS_GRAPH"] = "TEXT"
                self._user_set.add("CLASS_GRAPH")
        # DOT_FONTNAME / DOT_FONTSIZE rewrite the graph attribute strings.
        if "DOT_FONTNAME" in obs or "DOT_FONTSIZE" in obs:
            self._values["DOT_COMMON_ATTR"] = _rewrite_dot_attr(
                self._values["DOT_COMMON_ATTR"],
                fontname_key="fontname",
                fontsize_key="fontsize",
                fontname=obs.get("DOT_FONTNAME"),
                fontsize=obs.get("DOT_FONTSIZE"),
            )
            self._values["DOT_EDGE_ATTR"] = _rewrite_dot_attr(
                self._values["DOT_EDGE_ATTR"],
                fontname_key="labelfontname",
                fontsize_key="labelfontsize",
                fontname=obs.get("DOT_FONTNAME"),
                fontsize=obs.get("DOT_FONTSIZE"),
            )

    # -- Doxyfile.xml (XML output) ---------------------------------------
    def write_doxyfile_xml(self, lang="en-US"):
        out = []
        out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
        out.append(
            f'<doxyfile xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" '
            f'xsi:noNamespaceSchemaLocation="doxyfile.xsd" version="{VERSION}" xml:lang="{lang}">\n'
        )
        for tag in self.order:
            typ = self.tag_type(tag)
            is_default = "yes" if not self.differs_from_default(tag) else "no"
            if typ == "bool":
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='bool'>"
                    f"<value>{'YES' if self.get_bool(tag) else 'NO'}</value></option>\n"
                )
            elif typ == "int":
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='int'>"
                    f"<value>{self.get_int(tag)}</value></option>\n"
                )
            elif typ == "list":
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='stringlist'>\n"
                )
                for item in self.get_list(tag):
                    q = quote_if_needed(item)
                    out.append(f"    <value><![CDATA[{q}]]></value>\n")
                out.append("  </option>\n")
            else:
                value = self.get_enum(tag) if typ == "enum" else self.get_string(tag)
                q = quote_if_needed(value)
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='string'>"
                    f"<value><![CDATA[{q}]]></value></option>\n"
                )
        out.append("</doxyfile>\n")
        return "".join(out)


def _bool_of(raw):
    return str(raw).strip(" \t").lower() in TRUE_WORDS


def _rewrite_dot_attr(attr, fontname_key, fontsize_key, fontname, fontsize):
    attr = attr.strip(" \t")
    parts = [p for p in attr.split(",")] if attr else []
    def set_key(key, value):
        if value is None:
            return
        value = value.strip(" \t")
        for idx, part in enumerate(parts):
            if part.split("=")[0] == key:
                parts[idx] = f"{key}={value}"
                return
        parts.append(f"{key}={value}")
    set_key(fontsize_key, fontsize)
    set_key(fontname_key, fontname)
    return ",".join(parts)


class _Parser:
    def __init__(self, config, warn, update_mode=False, noenv=False):
        self.cfg = config
        self.warn = warn
        self.update_mode = update_mode
        self.noenv = noenv
        self.include_paths = []

    # expand env for a normal value
    def _expand(self, text, force=False):
        if force or not (self.noenv or self.update_mode):
            return expand_env(text)
        return text

    def parse_file(self, path, display_name, depth=0):
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as fh:
                data = fh.read()
        text = data.decode("utf-8", errors="surrogateescape")
        self._parse_text(text, display_name, depth)

    def _parse_text(self, text, filename, depth):
        pos = 0
        line = 1
        n = len(text)

        def read_value():
            """Read a value up to the end of its logical line starting at
            the current position; returns (raw_value, new_pos, new_line)."""
            nonlocal pos, line
            raw_chars = []
            in_quote = False
            while pos < n:
                ch = text[pos]
                if ch == "\n":
                    # Continuation if the last non-blank character is a
                    # backslash and we are not inside a quoted string.
                    stripped = "".join(raw_chars).rstrip(" \t")
                    if stripped.endswith("\\") and not in_quote:
                        raw_chars = list(stripped[:-1])
                        raw_chars.append(" ")
                        pos += 1
                        line += 1
                        continue
                    pos += 1
                    line += 1
                    break
                if ch == "#" and not in_quote:
                    prev = raw_chars[-1] if raw_chars else ""
                    if prev != "\\":
                        # Comment: skip to end of line.
                        while pos < n and text[pos] != "\n":
                            pos += 1
                        if pos < n:
                            pos += 1
                            line += 1
                        break
                if ch == '"':
                    # A quote escaped with a backslash does not toggle.
                    backslashes = 0
                    k = len(raw_chars) - 1
                    while k >= 0 and raw_chars[k] == "\\":
                        backslashes += 1
                        k -= 1
                    if backslashes % 2 == 0:
                        in_quote = not in_quote
                raw_chars.append(ch)
                pos += 1
            return "".join(raw_chars)

        while pos < n:
            ch = text[pos]
            if ch == "\n":
                line += 1
                pos += 1
                continue
            if ch in " \t\r":
                pos += 1
                continue
            if ch == "\x00":
                pos += 1
                continue
            if ch == "#":
                while pos < n and text[pos] != "\n":
                    pos += 1
                continue
            if ch == "@":
                m = _IDENT_RE.match(text, pos + 1)
                handled = False
                if m and m.group(0) in ("INCLUDE", "INCLUDE_PATH"):
                    # Only a directive when followed (after blanks) by '='.
                    j = m.end()
                    while j < n and text[j] in " \t":
                        j += 1
                    if j < n and text[j] == "=":
                        name = m.group(0)
                        start_line = line
                        pos = j + 1
                        raw = read_value()
                        self._handle_include_directive(
                            name, raw, filename, start_line, depth
                        )
                        handled = True
                if handled:
                    continue
                self.warn(
                    f"warning: ignoring unknown character '@' at line {line}, file {filename}\n"
                )
                pos += 1
                continue
            m = _IDENT_RE.match(text, pos)
            if m:
                tag = m.group(0)
                tag_line = line
                j = m.end()
                k = j
                while k < n and text[k] in " \t":
                    k += 1
                op = None
                op_end = None
                if k < n and text[k] == "=":
                    op = "="
                    op_end = k + 1
                elif k + 1 < n and text[k] == "+" and text[k + 1] == "=":
                    op = "+="
                    op_end = k + 2
                if op is None:
                    self.warn(
                        f"warning: ignoring unknown tag '{tag}' at line {tag_line}, file {filename}\n"
                    )
                    pos = j
                    continue
                pos = op_end
                raw = read_value()
                self._handle_assignment(tag, op, raw, filename, tag_line)
                continue
            # Any other stray character.
            self.warn(
                f"warning: ignoring unknown character '{ch}' at line {line}, file {filename}\n"
            )
            pos += 1

    def _handle_include_directive(self, name, raw, filename, line, depth):
        raw_trimmed = raw.strip(" \t")
        if name == "INCLUDE_PATH":
            if raw_trimmed == "":
                self.include_paths = []
                return
            expanded = expand_env(raw)
            dirs = parse_list_value(
                expanded, "@INCLUDE_PATH", line, filename, lambda m: None
            )
            self.include_paths = [d.strip(" \t") for d in dirs]
            return
        # @INCLUDE
        if raw_trimmed == "":
            return
        expanded = expand_env(raw)
        inc_name = parse_scalar_value(
            expanded, "@INCLUDE", line, filename, lambda m: None
        ).strip(" \t")
        if depth + 1 > 10:
            raise ConfigError(
                f"error: maximum include depth (10) reached, {inc_name} is not "
                f"included. Aborting...\nExiting...\n"
            )
        found = None
        search = []
        for base in self.include_paths:
            search.append(os.path.join(base, inc_name))
        search.append(inc_name)
        for candidate in search:
            if os.path.isfile(candidate):
                found = candidate
                break
        if found is None:
            raise ConfigError(
                f"error: @INCLUDE = {inc_name}: not found!\nExiting...\n"
            )
        try:
            with open(found, "rb") as fh:
                data = fh.read()
        except OSError:
            raise ConfigError(
                f"error: @INCLUDE = {inc_name}: not found!\nExiting...\n"
            )
        text = data.decode("utf-8", errors="surrogateescape")
        self._parse_text(text, inc_name, depth + 1)

    def _handle_assignment(self, tag, op, raw, filename, line):
        cfg = self.cfg
        if tag in OBSOLETE_TAGS or tag in DISABLED_TAGS:
            if tag in DISABLED_TAGS:
                first = (
                    f"warning: Tag '{tag}' at line {line} of file '{filename}' "
                    "belongs to an option that was not enabled at compile time.\n"
                )
                if self.update_mode:
                    second = "         This tag has been removed.\n"
                else:
                    second = (
                        "         To avoid this warning please remove this line "
                        "from your configuration file or upgrade it using "
                        '"doxygen -u", or recompile doxygen with this feature '
                        "enabled.\n"
                    )
            else:
                first = (
                    f"warning: Tag '{tag}' at line {line} of file '{filename}' "
                    "has become obsolete.\n"
                )
                if self.update_mode:
                    second = "         This tag has been removed.\n"
                else:
                    second = (
                        "         To avoid this warning please remove this line "
                        "from your configuration file or upgrade it using "
                        '"doxygen -u"\n'
                    )
            self.warn(first + second)
            value = parse_scalar_value(
                self._expand(raw), tag, line, filename, lambda m: None
            )
            cfg._obsolete[tag] = value
            if tag == "CLASS_DIAGRAMS":
                cfg._class_diagrams_seen = value
            return
        if not cfg.known(tag):
            self.warn(
                f"warning: ignoring unsupported tag '{tag}' at line {line}, file {filename}\n"
            )
            return
        typ = cfg.tag_type(tag)
        expanded = self._expand(raw)
        if op == "+=" and typ != "list":
            self.warn(
                f"warning: operator += not supported for '{tag} +='. Ignoring "
                f"line at line {line}, file {filename}\n"
            )
            return
        if typ == "list":
            items = parse_list_value(expanded, tag, line, filename, self.warn)
            if op == "+=":
                if tag not in cfg._user_set:
                    # += as the first mention appends to the *default* list?
                    # Observed: INPUT += a.h on its own yields just a.h
                    # (INPUT's default is empty).  For ABBREVIATE_BRIEF the
                    # reference appends to the default list, which treating
                    # the current value (initialised to the default) does.
                    pass
                cfg._values[tag] = list(cfg._values[tag]) + items
            else:
                cfg._values[tag] = items
            cfg._user_set.add(tag)
        else:
            value = parse_scalar_value(expanded, tag, line, filename, self.warn)
            cfg._values[tag] = value
            cfg._user_set.add(tag)

    def finish(self):
        # Additional warnings produced by obsolete conversions are emitted
        # after parsing (still in file order relative to other configs?)
        self.cfg._convert_obsolete(self.warn)


