class _Template:
    """Parses the short template to get option order and defaults."""

    def __init__(self):
        self.order = []
        self.defaults_raw = {}
        text = resources.get_text("doxyfile_short.txt")
        logical = []
        buf = ""
        for ln in text.splitlines():
            buf = buf + "\n" + ln if buf else ln
            if ln.rstrip().endswith("\\"):
                continue
            logical.append(buf)
            buf = ""
        if buf:
            logical.append(buf)
        for ln in logical:
            m = re.match(r"^([A-Z0-9_]+)\s*=\s?(.*)$", ln, re.S)
