        if tag in LIST_TAGS:
            return "list"
        if tag in INT_RANGES:
            return "int"
        if tag in ENUM_VALUES:
            return "enum"
        raw = self.defaults_raw.get(tag, "")
        if raw in ("YES", "NO"):
            return "bool"
        return "string"

    def default_value(self, tag):
        typ = self.tag_type(tag)
        raw = self.defaults_raw.get(tag, "")
        if typ == "list":
            return parse_list_value(raw, tag, 1, "<template>", lambda m: None)
        return parse_scalar_value(raw, tag, 1, "<template>", lambda m: None)


