                ok = bool(_INT_RE.match(stripped)) and lo <= int(stripped) <= hi
                if not ok:
                    warn(
                        f"warning: argument '{stripped}' for option {tag} is not a "
                        f"valid number in the range [{lo}..{hi}]!\n"
                        f"Using the default: {self._defaults[tag]}!\n"
                    )
                    self._values[tag] = self._defaults[tag]
            elif typ == "enum":
                if stripped == "":
                    continue
