        lines = template.split("\n")
        i = 0
        n = len(lines)
        while i < n:
            line = lines[i]
            m = re.match(r"^([A-Z0-9_]+)\s*=", line)
            if m and m.group(1) in self._values:
                tag = m.group(1)
