    # -- obsolete conversions ---------------------------------------------
    def _convert_obsolete(self, warn):
        obs = self._obsolete
        # HTML_TIMESTAMP / LATEX_TIMESTAMP -> TIMESTAMP = YES when true.
        for old in ("HTML_TIMESTAMP", "LATEX_TIMESTAMP"):
            if old in obs and obs[old].strip(" \t").lower() in TRUE_WORDS:
                self._values["TIMESTAMP"] = "YES"
                self._user_set.add("TIMESTAMP")
        # CLASS_DIAGRAMS = NO -> CLASS_GRAPH = TEXT (unless CLASS_GRAPH set)
        if self._class_diagrams_seen is not None:
            val = self._class_diagrams_seen.strip(" \t").lower()
            if val in FALSE_WORDS and "CLASS_GRAPH" not in self._user_set:
                warn(
                    "warning: Changing CLASS_GRAPH option to TEXT because "
                    "obsolete option CLASS_DIAGRAM was found and set to NO.\n"
                )
                self._values["CLASS_GRAPH"] = "TEXT"
                self._user_set.add("CLASS_GRAPH")
