        if "DOT_FONTNAME" in obs or "DOT_FONTSIZE" in obs:
            self._values["DOT_COMMON_ATTR"] = _rewrite_dot_attr(
                self._values["DOT_COMMON_ATTR"],
                fontname_key="fontname",
                fontsize_key="fontsize",
                fontname=obs.get("DOT_FONTNAME"),
                fontsize=obs.get("DOT_FONTSIZE"),
            )
            self._values["DOT_EDGE_ATTR"] = _rewrite_dot_attr(
                self._values["DOT_EDGE_ATTR"],
                fontname_key="labelfontname",
                fontsize_key="labelfontsize",
                fontname=obs.get("DOT_FONTNAME"),
                fontsize=obs.get("DOT_FONTSIZE"),
            )

    # -- Doxyfile.xml (XML output) ---------------------------------------
    def write_doxyfile_xml(self, lang="en-US"):
        out = []
        out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
        out.append(
            f'<doxyfile xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" '
            f'xsi:noNamespaceSchemaLocation="doxyfile.xsd" version="{VERSION}" xml:lang="{lang}">\n'
        )
        for tag in self.order:
            typ = self.tag_type(tag)
            is_default = "yes" if not self.differs_from_default(tag) else "no"
            if typ == "bool":
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='bool'>"
                    f"<value>{'YES' if self.get_bool(tag) else 'NO'}</value></option>\n"
                )
            elif typ == "int":
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='int'>"
                    f"<value>{self.get_int(tag)}</value></option>\n"
                )
            elif typ == "list":
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='stringlist'>\n"
                )
                for item in self.get_list(tag):
                    q = quote_if_needed(item)
                    out.append(f"    <value><![CDATA[{q}]]></value>\n")
                out.append("  </option>\n")
            else:
                value = self.get_enum(tag) if typ == "enum" else self.get_string(tag)
                q = quote_if_needed(value)
                out.append(
                    f"  <option  id='{tag}' default='{is_default}' type='string'>"
                    f"<value><![CDATA[{q}]]></value></option>\n"
                )
        out.append("</doxyfile>\n")
        return "".join(out)


def _bool_of(raw):
    return str(raw).strip(" \t").lower() in TRUE_WORDS


def _rewrite_dot_attr(attr, fontname_key, fontsize_key, fontname, fontsize):
    attr = attr.strip(" \t")
    parts = [p for p in attr.split(",")] if attr else []
    def set_key(key, value):
        if value is None:
            return
        value = value.strip(" \t")
        for idx, part in enumerate(parts):
            if part.split("=")[0] == key:
                parts[idx] = f"{key}={value}"
                return
        parts.append(f"{key}={value}")
    set_key(fontsize_key, fontsize)
    set_key(fontname_key, fontname)
    return ",".join(parts)


class _Parser:
    def __init__(self, config, warn, update_mode=False, noenv=False):
        self.cfg = config
