                pos = op_end
                raw = read_value()
                self._handle_assignment(tag, op, raw, filename, tag_line)
                continue
            # Any other stray character.
            self.warn(
                f"warning: ignoring unknown character '{ch}' at line {line}, file {filename}\n"
            )
            pos += 1

    def _handle_include_directive(self, name, raw, filename, line, depth):
        raw_trimmed = raw.strip(" \t")
        if name == "INCLUDE_PATH":
            if raw_trimmed == "":
                self.include_paths = []
                return
            expanded = expand_env(raw)
            dirs = parse_list_value(
                expanded, "@INCLUDE_PATH", line, filename, lambda m: None
            )
            self.include_paths = [d.strip(" \t") for d in dirs]
            return
        # @INCLUDE
        if raw_trimmed == "":
            return
        expanded = expand_env(raw)
        inc_name = parse_scalar_value(
            expanded, "@INCLUDE", line, filename, lambda m: None
        ).strip(" \t")
        if depth + 1 > 10:
            raise ConfigError(
                f"error: maximum include depth (10) reached, {inc_name} is not "
                f"included. Aborting...\nExiting...\n"
            )
        found = None
        search = []
        for base in self.include_paths:
            search.append(os.path.join(base, inc_name))
        search.append(inc_name)
        for candidate in search:
            if os.path.isfile(candidate):
                found = candidate
                break
        if found is None:
            raise ConfigError(
                f"error: @INCLUDE = {inc_name}: not found!\nExiting...\n"
            )
        try:
            with open(found, "rb") as fh:
                data = fh.read()
        except OSError:
            raise ConfigError(
                f"error: @INCLUDE = {inc_name}: not found!\nExiting...\n"
            )
        text = data.decode("utf-8", errors="surrogateescape")
        self._parse_text(text, inc_name, depth + 1)

    def _handle_assignment(self, tag, op, raw, filename, line):
        cfg = self.cfg
        if tag in OBSOLETE_TAGS or tag in DISABLED_TAGS:
            if tag in DISABLED_TAGS:
                first = (
                    f"warning: Tag '{tag}' at line {line} of file '{filename}' "
                    "belongs to an option that was not enabled at compile time.\n"
                )
                if self.update_mode:
                    second = "         This tag has been removed.\n"
                else:
                    second = (
                        "         To avoid this warning please remove this line "
                        "from your configuration file or upgrade it using "
                        '"doxygen -u", or recompile doxygen with this feature '
                        "enabled.\n"
                    )
            else:
                first = (
                    f"warning: Tag '{tag}' at line {line} of file '{filename}' "
                    "has become obsolete.\n"
                )
                if self.update_mode:
                    second = "         This tag has been removed.\n"
                else:
                    second = (
                        "         To avoid this warning please remove this line "
                        "from your configuration file or upgrade it using "
                        '"doxygen -u"\n'
                    )
            self.warn(first + second)
            value = parse_scalar_value(
                self._expand(raw), tag, line, filename, lambda m: None
            )
            cfg._obsolete[tag] = value
            if tag == "CLASS_DIAGRAMS":
                cfg._class_diagrams_seen = value
            return
        if not cfg.known(tag):
            self.warn(
                f"warning: ignoring unsupported tag '{tag}' at line {line}, file {filename}\n"
            )
            return
        typ = cfg.tag_type(tag)
        expanded = self._expand(raw)
        if op == "+=" and typ != "list":
            self.warn(
                f"warning: operator += not supported for '{tag} +='. Ignoring "
                f"line at line {line}, file {filename}\n"
            )
            return
        if typ == "list":
            items = parse_list_value(expanded, tag, line, filename, self.warn)
            if op == "+=":
                if tag not in cfg._user_set:
                    # += as the first mention appends to the *default* list?
                    # Observed: INPUT += a.h on its own yields just a.h
                    # (INPUT's default is empty).  For ABBREVIATE_BRIEF the
                    # reference appends to the default list, which treating
                    # the current value (initialised to the default) does.
                    pass
                cfg._values[tag] = list(cfg._values[tag]) + items
            else:
                cfg._values[tag] = items
            cfg._user_set.add(tag)
        else:
            value = parse_scalar_value(expanded, tag, line, filename, self.warn)
            cfg._values[tag] = value
            cfg._user_set.add(tag)

    def finish(self):
        # Additional warnings produced by obsolete conversions are emitted
        # after parsing (still in file order relative to other configs?)
        self.cfg._convert_obsolete(self.warn)


def load_config(path, display_name, warn, update_mode=False, noenv=False):
    """Load a config file; ``warn`` receives message strings."""
    cfg = Config()
    parser = _Parser(cfg, warn, update_mode=update_mode, noenv=noenv)
    parser.parse_file(path, display_name)
    parser.finish()
    return cfg
