MAIN_FORMAT_TAGS = (
    "GENERATE_HTML",
    "GENERATE_LATEX",
    "GENERATE_RTF",
    "GENERATE_MAN",
    "GENERATE_XML",
    "GENERATE_DOCBOOK",
    "GENERATE_AUTOGEN_DEF",
    "GENERATE_PERLMOD",
)


def check_config(cfg, warn):
    """The validation/adjustment pass run for a documentation run and
    for ``-w html|latex`` with a configuration file.  Option validation
    itself is in :meth:`Config.validate`; this performs the cross-option
    checks in the order their messages were observed to appear."""

    # WARN_FORMAT placeholders.
    warn_format = cfg.get_string("WARN_FORMAT")
    if warn_format:
        for placeholder in ("$file", "$line", "$text"):
            if placeholder not in warn_format:
                warn(f"warning: warning format does not contain a {placeholder} tag!\n")

    # INCLUDE_PATH entries must exist.
    for path in cfg.get_list("INCLUDE_PATH"):
        if not os.path.exists(path):
            warn(f"warning: tag INCLUDE_PATH: include path '{path}' does not exist\n")

    # Options taking "name=value" items.
    for tag, label in (
        ("EXTENSION_MAPPING", "EXTENSION_MAPPING"),
        ("FILTER_PATTERNS", "FILTER_PATTERNS"),
        ("INPUT_FILE_ENCODING", "INPUT_FILE_ENCODING"),
        ("EXTRA_SEARCH_MAPPINGS", "EXTRA_SEARCH_MAPPING"),
    ):
        for item in cfg.get_list(tag):
            if "=" not in item:
                warn(
                    f"error: Illegal format for option {label}, no equal sign "
                    f"('=') specified for item '{item}'\n"
                )
            elif item.startswith("="):
                warn(
                    f"error: Illegal format for option {label}, no name "
                    f"specified for item '{item}'\n"
                )
            elif item.endswith("="):
                warn(
                    f"error: Illegal format for option {label}, no value "
                    f"specified for item '{item}'\n"
                )

    # GENERATE_HTMLHELP forces a number of HTML options off.
    if cfg.get_bool("GENERATE_HTMLHELP"):
        for opt in (
            "GENERATE_TREEVIEW",
            "SEARCHENGINE",
            "HTML_DYNAMIC_MENUS",
            "HTML_COPY_CLIPBOARD",
            "HTML_CODE_FOLDING",
        ):
            if cfg.get_bool(opt):
                warn(
                    f"error: When enabling GENERATE_HTMLHELP the {opt} option "
                    f"should be disabled. I'll adjust it for you.\n"
                )
                cfg.set_value(opt, "NO", user=False)
        colorstyle = cfg.get_enum("HTML_COLORSTYLE")
        if colorstyle not in ("LIGHT", "DARK"):
            target = "DARK" if colorstyle == "AUTO_DARK" else "LIGHT"
            warn(
                "error: When enabling 'GENERATE_HTMLHELP' the 'HTML_COLORSTYLE' "
                f"option should be either 'LIGHT' or 'DARK' but has value "
                f"'{colorstyle}'. I'll adjust it for you to '{target}'.\n"
            )
            cfg.set_value("HTML_COLORSTYLE", target, user=False)

    # PLANTUML_JAR_PATH must be a jar file or a directory containing one.
    plantuml = cfg.get_string("PLANTUML_JAR_PATH")
    if plantuml:
        if os.path.isdir(plantuml):
            if not os.path.isfile(os.path.join(plantuml, "plantuml.jar")):
                warn(
                    "error: Jar file 'plantuml.jar' not found at location "
                    f"specified via PLANTUML_JAR_PATH: '{plantuml}'\n"
                )
        elif not os.path.isfile(plantuml):
            warn(
                "error: PLANTUML_JAR_PATH is not a directory with a "
                f"'plantuml.jar' file or is not an existing file: {plantuml}\n"
            )

    # DIA_PATH: the reference reports dia as not found for any value we
    # probed (including existing executables), unless a real dia is
    # installed.
    dia_path = cfg.get_string("DIA_PATH")
    if dia_path:
        warn(f"warning: dia could not be found at {dia_path}\n")

    # INPUT entries must exist.
    for path in cfg.get_list("INPUT"):
        if not os.path.exists(path):
            warn(f"warning: tag INPUT: input source '{path}' does not exist\n")

    # OPTIMIZE_OUTPUT_VHDL forces several options.
    if cfg.get_bool("OPTIMIZE_OUTPUT_VHDL"):
        for opt, desired in (
            ("INHERIT_DOCS", False),
            ("HIDE_SCOPE_NAMES", True),
            ("EXTRACT_PRIVATE", True),
            ("ENABLE_PREPROCESSING", False),
            ("EXTRACT_PACKAGE", True),
        ):
            if cfg.get_bool(opt) != desired:
                verb = "enabled" if desired else "disabled"
                warn(
                    f"error: When enabling OPTIMIZE_OUTPUT_VHDL the {opt} option "
                    f"should be {verb}. I'll adjust it for you.\n"
                )
                cfg.set_value(opt, "YES" if desired else "NO", user=False)

    if not any(cfg.get_bool(t) for t in MAIN_FORMAT_TAGS):
        warn(
            "warning: No output formats selected! Set at least one of the "
            "main GENERATE_* options to YES.\n"
        )
    if cfg.get_bool("GENERATE_HTMLHELP") and not cfg.get_bool("GENERATE_HTML"):
        warn("warning: GENERATE_HTMLHELP=YES requires GENERATE_HTML=YES.\n")
    if cfg.get_bool("GENERATE_QHP") and not cfg.get_bool("GENERATE_HTML"):
        warn("warning: GENERATE_QHP=YES requires GENERATE_HTML=YES.\n")
