"""Generation of the HTML style sheet (doxygen.css).

The default style sheet is shipped in five variants for the five
HTML_COLORSTYLE modes.  Within those variants a fixed palette of
colours is derived from the HTML_COLORSTYLE_HUE/SAT/GAMMA options:
each palette colour is the HSL colour with the configured hue and
saturation and a gamma-corrected lightness
(``L' = 255 * (L/255)**(gamma/100)``), converted to RGB with each
channel truncated.  The table below gives the pre-gamma lightness of
every palette colour, identified by its default (hue 220, saturation
100, gamma 80) RGB value.
"""

import colorsys
import math
import re
import time

from . import resources

_PALETTE_LIGHTNESS = {
$(cat /tmp/color_dict.py)
}

_HEX_RE = re.compile(r"#[0-9A-Fa-f]{6}\b")
_VAR_RE = re.compile(r"var\((--[A-Za-z0-9_-]+)\)")
_VAR_DEF_RE = re.compile(r"(--[A-Za-z0-9_-]+):\s*([^;]+);")


def _palette_color(lightness, hue, sat, gamma):
    lf = 255 * (lightness / 255) ** (gamma / 100) if lightness > 0 else 0.0
    r, g, b = colorsys.hls_to_rgb(hue / 360, lf / 255, sat / 255)
    return "#%02X%02X%02X" % (
        int(math.floor(r * 255)),
        int(math.floor(g * 255)),
        int(math.floor(b * 255)),
    )


def apply_colorstyle(text, hue, sat, gamma):
    if (hue, sat, gamma) == (220, 100, 80):
        # Still run the transform would be a no-op for palette colours;
        # keep the text untouched to preserve any other colours exactly.
        return text

    def repl(m):
        token = m.group(0)
        lightness = _PALETTE_LIGHTNESS.get(token.upper())
        if lightness is None:
            return token
        return _palette_color(lightness, hue, sat, gamma)

    return _HEX_RE.sub(repl, text)


def _variable_maps():
    """Return (light_map, dark_map) of CSS variable definitions."""
    text = resources.get_text("css_AUTO_LIGHT.css")
    light = {}
    dark = {}
    for name, value in _VAR_DEF_RE.findall(text):
        value = value.strip()
        if name not in light:
            light[name] = value
        elif name not in dark:
            dark[name] = value
    return light, dark


def resolve_variables(text, mode):
    """For the fixed LIGHT/DARK modes, replace var(--x) by its value."""
    if mode not in ("LIGHT", "DARK"):
        return text
    light, dark = _variable_maps()
    mapping = light if mode == "LIGHT" else dark

    def repl(m):
        return mapping.get(m.group(1), m.group(0))

    return _VAR_RE.sub(repl, text)


_WEEKDAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
_MONTHS = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
]


def format_timestamp(kind, now=None):
    """kind is 'DATE' or 'DATETIME'."""
    if now is None:
        now = time.localtime()
    base = "%s %s %d %d" % (
        _WEEKDAYS[now.tm_wday],
        _MONTHS[now.tm_mon - 1],
        now.tm_mday,
        now.tm_year,
    )
    if kind == "DATE":
        return base
    return "%s %02d:%02d:%02d" % (base, now.tm_hour, now.tm_min, now.tm_sec)


def generate_css(cfg):
    mode = cfg.get_enum("HTML_COLORSTYLE")
    text = resources.get_text(f"css_{mode}.css")

    inserted = ""
    if cfg.get_bool("FULL_SIDEBAR"):
        snippet = (
            "\n#titlearea {\n"
            "  border-bottom: none;\n"
            "  background-color: var(--nav-background-color);\n"
            "  border-right: 1px solid var(--nav-border-color);\n"
            "}\n"
        )
        inserted += resolve_variables(snippet, mode)
    timestamp = cfg.get_enum("TIMESTAMP")
    if timestamp != "NO":
        kind = "DATE" if timestamp == "DATE" else "DATETIME"
        inserted += (
            "\nhtml {\n"
            f"--timestamp: '{format_timestamp(kind)}';\n"
            "}\n"
            "span.timestamp { content: ' '; }\n"
            "span.timestamp:before { content: var(--timestamp); }\n"
            "\n"
        )

    marker = ":root {\n    scrollbar-width:"
    idx = text.find(marker)
    if idx >= 0:
        if cfg.get_list("HTML_EXTRA_STYLESHEET"):
            text = text[:idx] + inserted
        else:
            text = text[:idx] + inserted + text[idx:]

    return apply_colorstyle(
        text,
        cfg.get_int("HTML_COLORSTYLE_HUE"),
        cfg.get_int("HTML_COLORSTYLE_SAT"),
        cfg.get_int("HTML_COLORSTYLE_GAMMA"),
    )
