"""Command line interface: argument parsing and the template/config
oriented modes.  Documentation generation lives in
:mod:`app.generate`.
"""

import os
import sys

from . import config as config_mod
from . import resources
from . import cssgen
from .config import CheckFatal, ConfigError, VERSION_FULL, check_config, load_config
from .fileutil import write_template_file

_PROG = None


def _out(text):
    sys.stdout.write(text)


def _err(text):
    sys.stderr.write(text)


def usage_text():
