    lines += ["\t" + level for level in DEBUG_LEVELS]
    return "\n".join(lines) + "\n"


# --------------------------------------------------------------------------
# Configuration loading helpers


def _ensure_config_exists(name, explicit):
    """Implements the "configuration file not found" pre-check."""
    if name == "-" or os.path.exists(name):
        return True
    _out(usage_text())
    if explicit:
        _err(f"error: configuration file {name} not found!\n")
    else:
        _err("error: Doxyfile not found and no input file specified!\n")
    return False


def _load(name, update_mode=False, noenv=False, validate=False,
          full_check=False, create=False):
    """Load a config, writing any messages to stderr.

    Returns the Config, or None if loading failed (message emitted)."""
    try:
        cfg = load_config(name, name, _err,
                          update_mode=update_mode, noenv=noenv)
    except ConfigError as exc:
        _err(str(exc))
        return None
    except OSError:
        _err(f"error: file '{name}' not found or could not be opened\nExiting...\n")
        return None
    if validate or full_check:
        cfg.validate(_err)
    if full_check:
        try:
            check_config(cfg, _err, create=create)
        except CheckFatal:
            return None
    return cfg


# --------------------------------------------------------------------------
# Modes


def _do_generate_config(name, short):
    content = resources.get_text(
        "doxyfile_short.txt" if short else "doxyfile_full.txt"
    )
    if name == "-":
        _out(content)
        return 0
    if not write_template_file(name, content):
        _err(f"error: Cannot open file {name} for writing\n")
        return 1
    arg = "" if name == "Doxyfile" else " " + name
    _out(
        f"\n\nConfiguration file '{name}' created.\n"
        "\nNow edit the configuration file and enter\n"
        f"\n  doxygen{arg}\n"
        "\nto generate the documentation for your project\n\n"
    )
    return 0


def _do_update_config(name, explicit, short):
    if not _ensure_config_exists(name, explicit):
        return 1
    cfg = _load(name, update_mode=True)
    if cfg is None:
        return 1
    content = cfg.write_template(short)
    if name == "-":
        _out(content)
        return 0
    if not write_template_file(name, content):
        _err(f"error: Cannot open file {name} for writing\n")
        return 1
    _out(f"\n\nConfiguration file '{name}' updated.\n\n")
    return 0


def _do_compare_config(name, explicit, noenv):
    if not _ensure_config_exists(name, explicit):
        return 1
    cfg = _load(name, noenv=noenv, validate=True)
    if cfg is None:
        return 1
    _out(cfg.write_difference())
    return 0


def _do_layout(rest):
    name = rest[0] if rest else "DoxygenLayout.xml"
    content = resources.get_text("layout.xml")
    if not write_template_file(name, content):
        _err(f"error: Failed to open file {name} for writing!\n")
    return 0


def _spec_and_args(token, rest, missing_message):
    """Split an option like -w/-e/-f into (specifier, remaining args).

    Returns None (after emitting the missing message) if there is no
    specifier."""
    suffix = token[2:]
    if suffix:
        return suffix, list(rest)
    if not rest or rest[0] == "":
        _err(missing_message)
        return None
    return rest[0], list(rest[1:])


def _load_for_write_template(args):
    """Config handling for -w html|latex: an optional config argument,
    otherwise Doxyfile if present, otherwise defaults."""
    if args and args[0] != "":
        cfg_name = args[0]
        return _load(cfg_name, validate=True, full_check=True)
    if os.path.exists("Doxyfile"):
        return _load("Doxyfile", validate=True, full_check=True)
    cfg = config_mod.Config()
    cfg.validate(_err)
    try:
        check_config(cfg, _err)
    except CheckFatal:  # pragma: no cover - cannot happen with defaults
        return None
    return cfg


def _do_write_templates(token, rest):
    parsed = _spec_and_args(
        token, rest,
        'error: option "-w" is missing format specifier rtf, html or latex\n',
    )
    if parsed is None:
        return 1
    spec, args = parsed
    kind = spec.lower()
    if kind not in ("rtf", "html", "latex"):
        _err(
            f'error: Illegal format specifier "{spec}": should be one of '
            "rtf, html or latex\n"
        )
        return 1
    if kind == "rtf":
        if not args:
            _err('error: option "-w rtf" is missing a style sheet file name\n')
            return 1
        content = resources.get_text("rtf_style.txt")
        if not write_template_file(args[0], content):
            _err(f"error: error opening RTF style sheet file {args[0]}!\n")
            return 1
        return 0
    # html / latex
    if len(args) < 3:
        _err(f'error: option "-w {kind}" does not have enough arguments\n')
        return 1
    cfg = _load_for_write_template(args[3:])
    if cfg is None:
        return 1
    header_name, footer_name, style_name = args[0], args[1], args[2]
    if kind == "html":
        write_template_file(header_name, resources.get_text("html_header.html"))
        write_template_file(footer_name, resources.get_text("html_footer.html"))
        write_template_file(style_name, cssgen.generate_css(cfg))
    else:
        write_template_file(header_name, resources.get_text("latex/latex_header.tex"))
        write_template_file(footer_name, resources.get_text("latex/latex_footer.tex"))
        write_template_file(style_name, resources.get_text("latex/latex_style.sty"))
    return 0


def _do_rtf_extensions(token, rest):
    parsed = _spec_and_args(
        token, rest, 'error: option "-e" is missing format specifier rtf.\n'
    )
    if parsed is None:
        return 1
    spec, args = parsed
    if spec.lower() != "rtf":
        _err('error: option "-e" has invalid format specifier.\n')
        return 1
    if not args:
        _err('error: option "-e rtf" is missing an extensions file name\n')
        return 1
    write_template_file(args[0], resources.get_text("rtf_extensions.txt"))
    return 0


def _do_emoji(token, rest):
    parsed = _spec_and_args(
        token, rest, 'error: option "-f" is missing list specifier.\n'
    )
    if parsed is None:
        return 1
    spec, args = parsed
    if spec.lower() != "emoji":
        _err('error: option "-f" has invalid list specifier.\n')
        return 1
    if not args:
        _err('error: option "-f emoji" is missing an output file name\n')
        return 1
    write_template_file(args[0], resources.get_text("emoji.txt"))
    return 0


# --------------------------------------------------------------------------


def _is_option(token):
    if token.startswith("--"):
        return True
    return (
        len(token) >= 2
        and token[0] == "-"
        and (("a" <= token[1] <= "z") or ("A" <= token[1] <= "Z") or token[1] == "?")
    )


class _State:
    def __init__(self):
        self.short = False
        self.quiet = False
        self.unbuffered = False
        self.dump_map = False
        self.debug_flags = set()
        self.comment_file = None
        self.gen_config = False
        self.update_config = False
        self.compare_mode = None  # None | "x" | "x_noenv"
        self.started = None

    @property
    def start_time(self):
        import time

        if self.started is None:
            self.started = time.monotonic()
        return self.started

    def debug_time_prefix(self):
        import time

        if "time" in self.debug_flags:
            return f"{time.monotonic() - self.start_time:.3f} sec: "
        return ""


def main(argv=None):
    global _PROG
    if argv is None:
        argv = sys.argv
    _PROG = argv[0] if argv else "doxygen"
    try:
        sys.stdout.reconfigure(errors="surrogateescape", newline="")
        sys.stderr.reconfigure(errors="surrogateescape", newline="")
    except Exception:
        pass

    args = list(argv[1:])
    state = _State()
    state.started = __import__("time").monotonic()
    config_name = None
    config_explicit = False

    i = 0
    while i < len(args):
        token = args[i]
        if token == "--help":
            _out(usage_text())
            return 0
        if token == "--version":
            _out(VERSION_FULL + "\n")
            return 0
        if token.startswith("--"):
            _out(usage_text())
            _err(f'error: Unknown option "{token}"\n')
            return 1
        if not _is_option(token):
            config_name = token
            config_explicit = True
            break
        opt = token[1]
        if opt == "v":
            _out(VERSION_FULL + "\n")
            return 0
        elif opt == "V":
            _out(VERSION_FULL + "\n    with sqlite3 3.42.0.\n")
            return 0
        elif opt in ("h", "?"):
            _out(usage_text())
            return 0
        elif opt == "s":
            state.short = True
        elif opt == "q":
            state.quiet = True
        elif opt == "b":
            state.unbuffered = True
            try:
                sys.stdout.reconfigure(line_buffering=False)
            except Exception:
                pass
        elif opt == "m":
            state.dump_map = True
        elif opt == "g":
            state.gen_config = True
        elif opt == "u":
            state.update_config = True
        elif opt == "x":
            if token not in ("-x", "-x_noenv"):
                _err(
                    f'error: option should be "-x" or "-x_noenv", found: "{token}".\n'
                )
                return 1
            state.compare_mode = token[1:]
        elif opt == "l":
            return _do_layout(args[i + 1:])
        elif opt == "w":
            return _do_write_templates(token, args[i + 1:])
        elif opt == "e":
            return _do_rtf_extensions(token, args[i + 1:])
        elif opt == "f":
            return _do_emoji(token, args[i + 1:])
        elif opt == "d":
            suffix = token[2:]
            if suffix:
                spec = suffix
            else:
                nxt = args[i + 1] if i + 1 < len(args) else None
                if nxt is None or nxt == "" or nxt.startswith("-"):
                    _out(dev_help_text())
                    return 0
                spec = nxt
                i += 1
            if spec.lower() not in DEBUG_LEVELS:
                _out(state.debug_time_prefix())
                _out(f'option "-d" has unknown debug specifier: "{spec}".\n')
                _out(dev_help_text())
                return 1
            state.debug_flags.add(spec.lower())
        elif opt == "c":
            if i + 1 >= len(args):
                _out('option "-c" is missing the file name to read\n')
                _out(dev_help_text())
                return 1
            state.comment_file = args[i + 1]
            i += 1
        elif opt == "t":
            _err(
                'error: support for option "-t" has not been compiled in '
                "(use a debug build or a release build with tracing enabled).\n"
            )
            return 1
        else:
            _out(usage_text())
            _err(f'error: Unknown option "-{opt}"\n')
            return 1
        i += 1

    if config_name is None:
        config_name = "Doxyfile"
        config_explicit = False

    if state.gen_config:
        return _do_generate_config(config_name, state.short)
    if state.compare_mode is not None:
        return _do_compare_config(
            config_name, config_explicit, state.compare_mode == "x_noenv"
        )
    if state.update_config:
        return _do_update_config(config_name, config_explicit, state.short)

    # Documentation (or -c comment) run.
    if not _ensure_config_exists(config_name, config_explicit):
        return 1
    cfg = _load(config_name, validate=True, full_check=True, create=True)
    if cfg is None:
        return 1
    if state.quiet:
        cfg.set_value("QUIET", "YES", user=False)

    from . import generate

    if state.comment_file is not None:
        return generate.run_comment(cfg, state.comment_file, state)
    return generate.run_documentation(cfg, config_name, state)


if __name__ == "__main__":
    raise SystemExit(main())
