"""Name encoding used for generated files, anchors and XML refids."""

import hashlib
import re

# Single-character codes for common punctuation, and "_0x" codes for the
# rest, as observed by feeding filenames containing each punctuation
# character to the reference and reading back the generated refids.
_SHORT = {
    ":": "_1",
    "<": "_3",
    ">": "_4",
    "*": "_5",
    "&": "_6",
    "|": "_7",
    ".": "_8",
    "!": "_9",
}
_LONG = {
    ",": "_00",
    " ": "_01",
    "{": "_02",
    "}": "_03",
    "?": "_04",
    "^": "_05",
    "%": "_06",
    "(": "_07",
    ")": "_08",
    "+": "_09",
    "=": "_0a",
    "$": "_0b",
    "\\": "_0c",
    "@": "_0d",
    "]": "_0e",
    "[": "_0f",
    "#": "_0g",
    '"': "_0h",
    "~": "_0i",
    "'": "_0j",
    ";": "_0k",
    "`": "_0l",
    "/": "_2",
}


def encode_name(name, allow_unicode=False, case_sensitive=True):
    """Encode a name the way the reference encodes file/compound ids."""
    if not case_sensitive:
        name = name.lower()
    out = []
    for ch in name:
        if ch.isascii() and (ch.isalnum() or ch == "-"):
            out.append(ch)
        elif ch == "_":
            out.append("__")
        elif ch in _SHORT:
            out.append(_SHORT[ch])
        elif ch in _LONG:
            out.append(_LONG[ch])
        elif allow_unicode and not ch.isascii():
            out.append(ch)
        else:
            for byte in ch.encode("utf-8", "surrogateescape"):
                out.append(f"_x{byte:02X}")
    return "".join(out)


def member_anchor(definition, name, argsstring):
    """The 32-hex-digit anchor: md5(definition + name + argsstring)."""
    return hashlib.md5(
        (definition + name + argsstring).encode("utf-8", "surrogateescape")
    ).hexdigest()


def xml_escape(text):
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def xml_escape_attr(text):
    return xml_escape(text).replace('"', "&quot;")


def html_escape(text):
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


_ID_CLEAN_RE = re.compile(r"[^A-Za-z0-9_]+")


def make_id(text):
    """A best-effort identifier for pages/groups."""
    return _ID_CLEAN_RE.sub("_", text.strip()).strip("_")
