    "static", "extern", "inline", "virtual", "explicit", "friend",
    "constexpr", "consteval", "constinit", "mutable", "volatile",
    "register", "thread_local", "abstract", "final", "sealed",
    "public", "private", "protected", "internal", "async", "unsafe",
    "synchronized", "transient", "native", "record",
}


class _Tok:
    __slots__ = ("kind", "text", "line", "col")

    def __init__(self, kind, text, line, col):
        self.kind = kind
        self.text = text
        self.line = line
        self.col = col

    def __repr__(self):
        return f"<{self.kind} {self.text!r} @{self.line}:{self.col}>"


class _Comment:
    __slots__ = ("text", "style", "trailing", "line", "end_line")

    def __init__(self, text, style, trailing, line, end_line):
        self.text = text
        self.style = style
        self.trailing = trailing
        self.line = line
        self.end_line = end_line


def _eval_pp_expr(expr, macros):
    """Evaluate a preprocessor #if expression very approximately."""
    expr = expr.strip()
    if not expr:
        return False

    def expand(name):
        val = macros.get(name)
        if val is None:
            return "0"
        val = str(val).strip()
        return val if re.fullmatch(r"-?\d+", val) else "1"

    expr = re.sub(r"defined\s*\(\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)",
                  lambda m: "1" if m.group(1) in macros else "0", expr)
    expr = re.sub(r"defined\s+([A-Za-z_][A-Za-z0-9_]*)",
                  lambda m: "1" if m.group(1) in macros else "0", expr)
    expr = re.sub(r"\b([A-Za-z_][A-Za-z0-9_]*)\b", lambda m: expand(m.group(1)), expr)
    expr = expr.replace("&&", " and ").replace("||", " or ")
    expr = re.sub(r"!(?!=)", " not ", expr)
    if not re.fullmatch(r"[0-9\s()+\-*/%<>=!&|a-z]+", expr):
        return True
    try:
        return bool(eval(expr, {"__builtins__": {}}, {}))
    except Exception:
        return True


def _join_tokens(tokens):
    """Join declaration tokens with the spacing the reference uses in
    type/args strings (approximately)."""
    out = ""
    prev = None
    for t in tokens:
        txt = t.text if isinstance(t, _Tok) else str(t)
        if out == "":
            out = txt
        elif txt in (",", ")", "]", "::", ";"):
            out += txt
        elif prev in ("(", "[", "::", "~", ".", "->", "#"):
            out += txt
        elif txt in ("(", "["):
            # No space before '(' for calls, but keep one after a keyword.
            if prev in ("if", "while", "for", "return", "switch", "catch"):
                out += " " + txt
            else:
                out += txt
        elif txt == "<":
            out += txt
        elif prev == "<":
            out += txt
        elif txt == ">":
            out += txt
        elif txt in ("*", "&", "&&"):
            # A pointer/reference glued to the following name in types
            # is written with a space before it by doxygen when the
            # previous token is a type name.
            out += " " + txt
        else:
            out += " " + txt
        prev = txt
