    def _classify_block_comment(self, src):
        # src includes /* ... */
        if src in ("/**/", "/*!*/"):
            return None
        if src.startswith("/**<") or src.startswith("/*!<"):
            trailing = True
            style = "block"
            inner = src[4:-2]
        elif src.startswith("/**") and not src.startswith("/***"):
            trailing = False
            style = "block"
            inner = src[3:-2]
        elif src.startswith("/*!") and not src.startswith("/*!!"):
            trailing = False
            style = "qt"
            inner = src[3:-2]
        elif src.startswith("/***"):
            # Banner comments are doc only with JAVADOC_BANNER.
            try:
                if not self.cfg.get_bool("JAVADOC_BANNER"):
                    return None
            except Exception:
                return None
            trailing = False
            style = "block"
            inner = src[3:-2]
        else:
            return None
        # Strip leading '*' decorations per line.
        lines = inner.split("\n")
        out = []
        for k, ln in enumerate(lines):
            s = ln.rstrip()
            st = s.lstrip(" \t")
            if st.startswith("*") and not st.startswith("**"):
                st = st[1:]
                if st.startswith(" "):
                    st = st[1:]
                out.append(st)
            elif st.startswith("**"):
                # Decorative line of stars -> blank
                out.append("" if set(st) <= {"*"} else st.lstrip("*").lstrip())
            else:
                out.append(st if k > 0 else s.strip())
        return "\n".join(out).strip("\n"), style, trailing

    def _classify_line_comment(self, src):
        # src starts with //
        if src.startswith("///<"):
            return src[4:].strip_one_space() if False else (self._strip_one_space(src[4:]), "line", True, 4)
        if src.startswith("//!<"):
            return (self._strip_one_space(src[4:]), "lineqt", True, 4)
        if src.startswith("///") and not src.startswith("////"):
            return (self._strip_one_space(src[3:]), "line", False, 3)
        if src.startswith("//!") and not src.startswith("//!!"):
            return (self._strip_one_space(src[3:]), "lineqt", False, 3)
        return None

    @staticmethod
    def _strip_one_space(s):
        return s[1:] if s.startswith(" ") else s

    # ------------------------------------------------------------------
    # Doc handling
    def _doc_parser(self, comment):
        return DocParser(self.cfg, self.warn, self.file.rel_path or self.file.name, comment.line)

    def _parse_comment(self, comment):
        parser = self._doc_parser(comment)
        style_map = {"block": "block", "qt": "qt", "line": "line", "lineqt": "lineqt"}
        return parser.parse(comment.text, style_map.get(comment.style, "block"), trailing=comment.trailing)

    def _merge_pending_doc(self):
        if not self.pending:
            return Doc()
        docs = [self._parse_comment(c) for c in self.pending]
        self.pending = []
        if len(docs) == 1:
            return docs[0]
        merged = Doc()
        merged.has_doc = True
        for d in docs:
            if d.structural:
                merged.structural = merged.structural or d.structural
            if not merged.brief and d.brief:
                merged.brief = d.brief
            else:
                merged.detailed.extend(d.brief)
            merged.detailed.extend(d.detailed)
            merged.ingroups.extend(d.ingroups)
        return merged

    def _handle_comment(self, comment):
        # Parse eagerly to see if structural.
        doc = self._parse_comment(comment)
        if doc.structural:
            cmd, args = doc.structural
            if cmd == "file":
                # Optionally a filename argument; attach to this file if
                # blank or matching the basename.
                fname = args.split()[0] if args.split() else ""
                if not fname or fname == self.file.name or fname.endswith("/" + self.file.name):
                    if self.file.doc.empty():
                        self.file.doc = doc
                    else:
                        self.file.doc.detailed.extend(doc.brief + doc.detailed)
                    self.file.is_documented_file = True
                return
            self.standalone.append((doc.structural, doc, comment))
            return
        if comment.trailing:
            if self.last_member is not None:
                self._attach_doc(self.last_member, doc, append=True)
            return
        self.pending.append(comment)

    def _attach_doc(self, entity, doc, append=False):
        if doc is None or doc.empty():
            return
        if entity.doc is None or entity.doc.empty():
            entity.doc = doc
        elif append:
            if not entity.doc.brief and doc.brief:
                entity.doc.brief = doc.brief
            entity.doc.detailed.extend(doc.brief if entity.doc.brief and doc.brief else [])
            entity.doc.detailed.extend(doc.detailed)
            entity.doc.inbody.extend(doc.inbody)
        else:
            entity.doc = doc

    def _take_doc(self):
        if self.pending:
            return self._merge_pending_doc()
        return Doc()

    # ------------------------------------------------------------------
    # Parsing
    def parse(self):
        items = self.items
        self.pos = 0
        self._parse_scope(self.file, None)
        return

    def _peek(self, ahead=0):
        # Comments are handled in _next; _peek looks at raw items.
        idx = self.pos + ahead
        return self.items[idx] if idx < len(self.items) else None

    def _next_token(self):
        """Return next _Tok or directive tuple, processing comments."""
        while self.pos < len(self.items):
            item = self.items[self.pos]
            self.pos += 1
            if isinstance(item, tuple) and item[0] == "comment":
                self._handle_comment(item[1])
                continue
            return item
        return None

    def _peek_token(self):
        idx = self.pos
        # Comments preceding a token affect pending doc, but peeking must
        # not consume them.  We only peek within a declaration where any
        # comment would be unusual; simply look past comments.
        while idx < len(self.items):
            item = self.items[idx]
            if isinstance(item, tuple) and item[0] == "comment":
                idx += 1
                continue
            return item
        return None

    def _parse_scope(self, owner, parent_compound, default_access="public", in_class=False):
        access = default_access
        while True:
            tok = self._next_token()
            if tok is None:
                return
            if isinstance(tok, tuple):
                if tok[0] == "define":
                    m = self._make_define(tok, owner)
                    _doc = self._take_doc()
                    self._attach_doc(m, _doc)
                    self._register_member(m, owner)
                    continue
                if tok[0] == "include":
                    self.file.includes.append((tok[1], None, tok[2]))
                    continue
                continue
            if tok.text == "}":
                return
            if tok.text == ";":
                continue
            if tok.kind == "ident" and tok.text in ("public", "protected", "private") and in_class:
                nxt = self._peek_token()
                if isinstance(nxt, _Tok) and nxt.text == ":":
                    self._next_token()
                    access = tok.text
                    continue
                # FALLTHROUGH: modifier on a declaration (Java etc.)
            # Dispatch declarations starting with tok (unread it).
            self.pos -= 1
            self._parse_declaration(owner, parent_compound, access, in_class)

    # --- helpers for token streams --------------------------------------
    def _collect_until(self, stop_texts):
        """Collect tokens until one of stop_texts at depth 0 (not consumed).
        Returns (tokens, stopper)."""
        toks = []
        depth = 0
        while True:
            item = self._peek_token()
            if item is None:
                return toks, None
            if isinstance(item, tuple):
                # Directive interrupts a declaration.
                return toks, item
            if depth == 0 and item.text in stop_texts:
                return toks, item
            item = self._next_token()
            if isinstance(item, tuple):
                return toks, item
            if item.text in ("(", "[", "<"):
                depth += 1
            elif item.text in (")", "]", ">"):
                if depth > 0:
                    depth -= 1
            toks.append(item)

    def _skip_balanced(self, open_t="{", close_t="}"):
        depth = 0
        while True:
            item = self._next_token()
            if item is None:
                return
            if isinstance(item, tuple):
                continue
            if item.text == open_t:
                depth += 1
            elif item.text == close_t:
                depth -= 1
                if depth == 0:
                    return

    def _parse_declaration(self, owner, parent_compound, access, in_class):
        start = self._peek_token()
        if start is None or isinstance(start, tuple):
            self._next_token()
            return
        word = start.text if start.kind == "ident" else ""

        # Attributes [[...]]
        if word == "" and start.text == "[[":
            self._next_token(); self._skip_balanced("[[", "]]")
            return self._parse_declaration(owner, parent_compound, access, in_class)

        # Template prefix(es)
        template_params = []
        is_template = False
        if word == "template":
            self._next_token()
            nxt = self._peek_token()
            if isinstance(nxt, _Tok) and nxt.text == "<":
                self._next_token()
                raw, _ = self._collect_until({">"})
                self._next_token()  # '>'
                template_params = _parse_template_params(raw)
                is_template = True
            # explicit specialization "template<>" has empty params.
            return self._parse_declaration_after_template(owner, parent_compound, access, in_class, template_params, is_template=True)
        return self._parse_declaration_after_template(owner, parent_compound, access, in_class, template_params)

    def _parse_declaration_after_template(self, owner, parent_compound, access, in_class, template_params, is_template=False):
        start = self._peek_token()
        if start is None or isinstance(start, tuple):
            self._next_token(); return
        word = start.text if start.kind == "ident" else ""

        if word == "namespace":
            self._next_token()
            toks, stop = self._collect_until({"{", ";", "="})
            if isinstance(stop, _Tok) and stop.text == "=":
                self._next_token(); self._collect_until({";"}); self._next_token(); return
            if isinstance(stop, _Tok) and stop.text == ";":
                self._next_token(); return
            if isinstance(stop, _Tok) and stop.text == "{":
                self._next_token()
                qname = _join_tokens(toks)
                parts = qname.split("::") if qname else []
                cur = owner
                parent = parent_compound
                prefix = parent.qualified + "::" if parent and parent.kind in ("namespace", "class", "struct") and parent.kind == "namespace" else ""
                doc = self._take_doc()
                cur_parent = parent_compound if parent_compound and parent_compound.kind == "namespace" else None
                full_prefix = cur_parent.qualified + "::" if cur_parent else ""
                comp = None
                for i, part in enumerate(parts):
                    qual = full_prefix + "::".join(parts[:i + 1])
                    comp = self.project.find_compound(qual, {"namespace"})
                    if comp is None:
                        comp = Compound("namespace", qual.split("::")[-1], qual)
                        comp.location = Location(self.file.name, start.line, start.col)
                        self.project.compounds.append(comp)
                        if cur_parent is not None:
                            cur_parent.inner.append(comp)
                        else:
                            self.file.inner.append(comp)
                    cur_parent = comp
                if comp is not None:
                    if doc.has_doc and comp.doc.empty():
                        comp.doc = doc
                    comp.file_compound = self.file
                    self._parse_scope(comp, comp, "public", False)
                else:
                    # Anonymous namespace: members go to current owner.
                    self._parse_scope(owner, parent_compound, access, in_class)
                return
            return

        if word == "extern":
            # extern "C" { ... }
            save = self.pos
            self._next_token()
            nxt = self._peek_token()
            if isinstance(nxt, _Tok) and nxt.kind == "string":
                self._next_token()
                nxt2 = self._peek_token()
                if isinstance(nxt2, _Tok) and nxt2.text == "{":
                    self._next_token()
                    self._parse_scope(owner, parent_compound, access, in_class)
                    return
                if isinstance(nxt2, _Tok) and nxt2.text != ";":
                    # extern "C" declaration without braces: fall through
                    # to generic handling by rewinding to the decl start
                    # after 'extern "C"'.
                    pass
                else:
                    return
            else:
                self.pos = save

        if word in ("class", "struct", "union", "interface"):
            return self._parse_class(owner, parent_compound, access, template_params)
        if word == "enum":
            return self._parse_enum(owner, parent_compound, access)
        if word == "typedef":
            return self._parse_typedef(owner, parent_compound, access)
        if word == "using":
            return self._parse_using(owner, parent_compound, access)
        if word == "concept":
            toks, stop = self._collect_until({";"})
            self._next_token()
            return
        if word in ("package", "import"):
            self._collect_until({";"}); self._next_token(); return
        # Generic declaration
        return self._parse_generic(owner, parent_compound, access, template_params)

    # --- specific declarations -------------------------------------------
    def _make_define(self, tok, owner):
        _kind, name, params, body, lineno, col = tok
        m = Member("define", name)
        m.location = Location(self.file.name, lineno, col)
        m.location.body_file = self.file.name
        m.location.body_start = lineno
        m.location.body_end = -1
        m.initializer = (body or "").strip() or None
        if params is not None:
            m.params = [{"type": "", "declname": p.strip(), "defval": None} for p in params.split(",") if p.strip()]
        return m

    def _register_member(self, member, owner):
        member.parent = owner if isinstance(owner, Compound) else self.file
        member.file_compound = self.file
        if member.parent is not None and member.parent.kind != "file":
            member.qualified = member.parent.qualified + "::" + member.name if member.name else member.parent.qualified
        else:
            member.qualified = member.name
        # Recompute definition if it was built with a placeholder owner.
        owner.members.append(member)
        if member not in self.project.all_members:
            self.project.all_members.append(member)
        self.last_member = member

    def _parse_class(self, owner, parent_compound, access, template_params):
        kw = self._next_token()
        kind = kw.text
        if kind == "interface":
            kind = "interface"
        toks, stop = self._collect_until({"{", ";", ":"})
        # The class name is the first identifier sequence (may have
        # attributes / export macros before it).
        name_toks = []
        name_start_col = kw.col
        name_line = kw.line
        # If a ';' stopper and there are declaration-looking trailing
        # identifiers, this could be an elaborated type in a variable
        # declaration (e.g. 'struct S x;') - heuristic: if more than
        # one plain identifier and stop is ';', treat as generic by
        # re-parsing?  For simplicity, if toks contain 2+ non-template
        # identifiers and stop == ';', fall through as a variable.
        idents = [t for t in toks if t.kind == "ident"]
        if isinstance(stop, _Tok) and stop.text == ";" and len(idents) >= 2 and idents[0].text not in _MODIFIERS:
            # e.g. "struct Foo bar;" - reconstruct a generic declaration.
            decl_toks = [kw] + toks
            self._next_token()
            self._make_from_generic_tokens(decl_toks, owner, parent_compound, access)
            return
        # Name: last qualified identifier chain in toks (skipping macros)
        # Take the first ident chain after any leading macro idents that
        # are all uppercase export macros?  Heuristic: first identifier
        # that is not fully uppercase-with-underscores, else first.
        name = ""
        name_tok = None
        chain = []
        i = 0
        # Find name chain: sequence ident (:: ident)* possibly <...>
        pos = 0
        chosen = None
        # Skip leading attribute/macro idents followed by another ident
        # when they look like EXPORT macros (all caps).
        starts = [i for i, t in enumerate(toks) if t.kind == "ident"]
        for si in starts:
            t = toks[si]
            if t.text.isupper() and len(starts) > 1:
                continue
            chosen = si
            break
        if chosen is None and starts:
            chosen = starts[0]
        spec_toks = []
        if chosen is not None:
            j = chosen
            while j < len(toks):
                t = toks[j]
                if t.kind == "ident" or t.text == "::":
                    name_toks.append(t); j += 1; continue
                if t.text == "<":
                    depth = 0
                    while j < len(toks):
                        spec_toks.append(toks[j])
                        if toks[j].text == "<": depth += 1
                        elif toks[j].text == ">": depth -= 1
                        j += 1
                        if depth == 0: break
                    continue
                break
            name_tok = toks[chosen]
            name = "".join(t.text for t in name_toks)
            if spec_toks:
                spec_text = _join_tokens(spec_toks)
                # doxygen writes template specs as "Name< int >"
                inner = spec_text[1:-1].strip()
                name = f"{name}< {inner} >"
        bases = []
        if isinstance(stop, _Tok) and stop.text == ":":
            self._next_token()
            btoks, stop = self._collect_until({"{", ";"})
            # split bases by commas at top
            cur = []
            for t in btoks + [_Tok("punct", ",", 0, 0)]:
                if t.text == ",":
                    if cur:
                        prot = "private" if kind == "class" else "public"
                        virt = "non-virtual"
                        names = []
                        for bt in cur:
                            if bt.text in ("public", "protected", "private"): prot = bt.text
                            elif bt.text == "virtual": virt = "virtual"
                            else: names.append(bt)
                        if names:
                            bases.append((_join_tokens(names), prot, virt))
                    cur = []
                else:
                    cur.append(t)
        if isinstance(stop, _Tok) and stop.text == ";":
            self._next_token()
            # Forward declaration: register only if documented.
            doc = self._take_doc()
            if name and (doc.has_doc and not doc.empty()):
                comp = self._get_or_create_compound(kind, name, owner, parent_compound, kw, template_params)
                comp.doc = doc
            return
        if not (isinstance(stop, _Tok) and stop.text == "{"):
            return
        self._next_token()
        doc = self._take_doc()
        if not name:
            # Anonymous class/struct: parse body with no compound then
            # expect a declarator handled by caller fallback: skip body.
            self._parse_scope(owner, parent_compound, "public", True)
            # Consume trailing declarators up to ';'
            tt, st = self._collect_until({";"})
            if isinstance(st, _Tok): self._next_token()
            # Attach docs of members lost; acceptable fallback.
            return
        comp = self._get_or_create_compound(kind, name, owner, parent_compound, kw, template_params)
        if doc.has_doc:
            if comp.doc.empty():
                comp.doc = doc
            else:
                comp.doc.detailed.extend(doc.brief + doc.detailed)
        comp.bases = bases
        comp.location.body_file = self.file.name
        comp.location.body_start = kw.line
        default_access = "private" if kind == "class" else "public"
        self._parse_scope(comp, comp, default_access, True)
        end_tok_line = kw.line
        # After '}' (consumed by _parse_scope return) there may be
        # declarators; consume up to ';' and note end line from last item.
        # Track body end approximately using previous token line.
        # _parse_scope consumed the closing brace; its line is in items.
        comp.location.body_end = self._last_consumed_line()
        tt, st = self._collect_until({";"})
        if isinstance(st, _Tok):
            self._next_token()

    def _last_consumed_line(self):
        idx = min(self.pos, len(self.items)) - 1
        while idx >= 0:
            item = self.items[idx]
            if isinstance(item, _Tok):
                return item.line
            idx -= 1
        return 1

    def _get_or_create_compound(self, kind, name, owner, parent_compound, kw, template_params):
        # Qualified name
        if "::" in name:
            qual = name.lstrip(":")
        elif parent_compound is not None and parent_compound.kind in ("namespace", "class", "struct", "union", "interface"):
            qual = parent_compound.qualified + "::" + name
        elif owner is not None and isinstance(owner, Compound) and owner.kind in ("namespace", "class", "struct", "union", "interface"):
            qual = owner.qualified + "::" + name
        else:
            qual = name
        short = qual.split("::")[-1]
        # Strip template spec for identity?  Keep as-is.
        comp = self.project.find_compound(qual, {kind})
        if comp is None:
            comp = Compound(kind, short, qual)
            comp.template_params = template_params or []
            comp.location = Location(self.file.name, kw.line, kw.col)
            comp.file_compound = self.file
            comp.inc_file = self.file.name
            self.project.compounds.append(comp)
            parent = parent_compound if parent_compound is not None else (owner if isinstance(owner, Compound) and owner.kind != "file" else None)
            if parent is not None:
                parent.inner.append(comp)
                comp.parent = parent
            self.file.inner.append(comp)
        return comp

    def _parse_enum(self, owner, parent_compound, access):
        kw = self._next_token()
        strong = False
        is_class = False
        nxt = self._peek_token()
        if isinstance(nxt, _Tok) and nxt.text in ("class", "struct"):
            strong = True
            self._next_token()
        toks, stop = self._collect_until({"{", ";", ":"})
        if isinstance(stop, _Tok) and stop.text == ":":
            self._next_token()
            _bt, stop = self._collect_until({"{", ";"})
        idents = [t for t in toks if t.kind == "ident"]
        if isinstance(stop, _Tok) and stop.text == ";" and len(idents) >= 2:
            # variable of enum type
            decl_toks = [kw] + toks
            self._next_token()
            self._make_from_generic_tokens(decl_toks, owner, parent_compound, access)
            return
        name = idents[-1].text if idents else ""
        name_tok = idents[-1] if idents else kw
        doc = self._take_doc()
        m = Member("enum", name)
        m.strong = strong
        m.prot = access if owner is not None and isinstance(owner, Compound) and owner.kind in ("class", "struct") else "public"
        m.location = Location(self.file.name, kw.line, kw.col)
        m.location.body_file = self.file.name
        m.location.body_start = kw.line
        if isinstance(stop, _Tok) and stop.text == "{":
            self._next_token()
            # Parse enum values.
            saved_last = self.last_member
            while True:
                t = self._next_token()
                if t is None:
                    break
                if isinstance(t, tuple):
                    continue
                if t.text == "}":
                    m.location.body_end = t.line
                    break
                if t.text == ",":
                    continue
                if t.kind == "ident":
                    ev = Member("enumvalue", t.text)
                    ev.location = Location(self.file.name, t.line, t.col)
                    # optional '= value'
                    init = None
                    nt = self._peek_token()
                    if isinstance(nt, _Tok) and nt.text == "=":
                        self._next_token()
                        vt, _st = self._collect_until({",", "}"})
                        init = _join_tokens(vt)
                    ev.initializer = init
                    # pending doc attaches to this value; trailing handled
                    # by _handle_comment via last_member.
                    edoc = self._take_doc()
                    if edoc.has_doc:
                        ev.doc = edoc
                    m.enumvalues.append(ev)
                    self.last_member = ev
                    # peek a trailing comment before next value: comments
                    # are processed when _next_token is called above.
                    continue
                # other tokens inside enum (attributes) skipped
            # Trailing declarators
            tt, st = self._collect_until({";"})
            if isinstance(st, _Tok):
                self._next_token()
            self.last_member = saved_last
        else:
            if isinstance(stop, _Tok):
                self._next_token()
            m.location.body_end = kw.line
        if name or m.enumvalues:
            self._attach_doc(m, doc)
            # Definition for id hashing: enums have no <definition> in XML;
            # their anchor is computed from name+name (verified pattern
            # for variables).  For enums use qualified name as prefix
            # component set in _register_member then fix definition.
            self._register_member(m, owner)
            m.definition = m.qualified
            for ev in m.enumvalues:
                ev.parent = m.parent
                ev.file_compound = self.file
                ev.qualified = (m.qualified + "::" + ev.name) if m.qualified else ev.name
        return

    def _parse_typedef(self, owner, parent_compound, access):
        kw = self._next_token()
        # typedef struct/enum with body
        nxt = self._peek_token()
        if isinstance(nxt, _Tok) and nxt.text in ("struct", "class", "union", "enum"):
            # Let class/enum parser run with owner; trailing name becomes
            # the typedef.  Simplified: parse the compound/enum, then
            # create a typedef to it if a name followed.
            # Capture compound count.
            if nxt.text == "enum":
                self._parse_enum(owner, parent_compound, access)
            else:
                self._parse_class(owner, parent_compound, access, [])
            return
        toks, stop = self._collect_until({";"})
        if isinstance(stop, _Tok):
            self._next_token()
        if not toks:
            return
        # Name is last identifier (before any [ or () suffix).
        name_idx = None
        for i in range(len(toks) - 1, -1, -1):
            if toks[i].kind == "ident" and toks[i].text not in _MODIFIERS:
                name_idx = i
                break
        if name_idx is None:
            return
        name = toks[name_idx].text
        type_toks = toks[:name_idx]
        m = Member("typedef", name)
        m.type = _join_tokens(type_toks)
        m.prot = access if owner is not None and isinstance(owner, Compound) and owner.kind in ("class", "struct") else "public"
        m.location = Location(self.file.name, toks[name_idx].line, toks[name_idx].col)
        m.location.body_file = self.file.name
        m.location.body_start = toks[name_idx].line
        m.location.body_end = -1
        doc = self._take_doc()
        self._attach_doc(m, doc)
        self._register_member(m, owner)
        m.definition = f"typedef {m.type} {m.qualified}".strip()

    def _parse_using(self, owner, parent_compound, access):
        kw = self._next_token()
        toks, stop = self._collect_until({";"})
        if isinstance(stop, _Tok):
            self._next_token()
        # using Name = Type;
        eq = next((i for i, t in enumerate(toks) if t.text == "="), None)
        if eq is not None and eq >= 1:
            name = toks[eq - 1].text
            m = Member("typedef", name)
            m.type = _join_tokens(toks[eq + 1:])
            m.prot = access if owner is not None and isinstance(owner, Compound) and owner.kind in ("class", "struct") else "public"
            m.location = Location(self.file.name, toks[eq - 1].line, toks[eq - 1].col)
            m.location.body_file = self.file.name
            m.location.body_start = toks[eq - 1].line
            m.location.body_end = -1
            doc = self._take_doc()
            self._attach_doc(m, doc)
            self._register_member(m, owner)
            m.definition = f"typedef {m.type} {m.qualified}".strip()
        else:
            # consume pending doc (using namespace / declaration)
            self._take_doc()

    # --- generic declarations ---------------------------------------------
    def _parse_generic(self, owner, parent_compound, access, template_params):
        toks, stop = self._collect_until({";", "{", "}"})
        if isinstance(stop, _Tok) and stop.text == "}":
            # Not a declaration; let scope loop handle the brace by
            # rewinding: we consumed nothing of the brace (stop is peek).
            # Put tokens back is not possible; treat toks as a decl if any.
            if toks:
                self._make_from_generic_tokens(toks, owner, parent_compound, access, template_params)
            return
        body_start = body_end = None
        if isinstance(stop, _Tok) and stop.text == "{":
            self._next_token()
            body_start_line = stop.line
            # Function definition if toks contain '('
            self._skip_balanced("{", "}")
            body_end_line = self._last_consumed_line()
            self._make_from_generic_tokens(toks, owner, parent_compound, access, template_params, body=(body_start_line, body_end_line))
            return
        if isinstance(stop, _Tok) and stop.text == ";":
            self._next_token()
        if toks:
            self._make_from_generic_tokens(toks, owner, parent_compound, access, template_params)

    def _make_from_generic_tokens(self, toks, owner, parent_compound, access, template_params=None, body=None):
        # Remove stray attributes and extern "C" strings at start.
        doc = self._take_doc()
        if toks and toks[0].text == "extern" and len(toks) > 1 and toks[1].kind == "string":
            toks = [toks[0]] + toks[2:]
        if not toks:
            return
        in_class = owner is not None and isinstance(owner, Compound) and owner.kind in ("class", "struct", "union", "interface")
        # Find function pattern: '(' whose preceding token is an ident
        # (or 'operator...') and which is not after '='
        func = _find_function(toks)
        members = []
        if func is not None:
            members = [self._make_function(toks, func, owner, access, template_params, body)]
        else:
            members = self._make_variables(toks, owner, access, template_params)
        for m in members:
            if m is None:
                continue
            self._attach_doc(m, doc)
            self._register_member(m, owner)
            # Namespace members keep their qualified name; file members
            # have plain qualified name (set in _register_member).
            # Recompute definition with qualified name if needed.
            self._finalize_definition(m, in_class)

    def _finalize_definition(self, m, in_class):
        if m.kind == "function":
            if m.type:
                m.definition = f"{m.type} {m.qualified}"
            else:
                m.definition = m.qualified
        elif m.kind == "variable":
            m.definition = f"{m.type} {m.qualified}".strip()
        elif m.kind == "typedef":
            if not m.definition.startswith("typedef"):
                m.definition = f"typedef {m.type} {m.qualified}".strip()
        elif m.kind == "enum":
            m.definition = m.qualified

    def _make_function(self, toks, func, owner, access, template_params, body):
        name_idx, lparen, rparen = func
        name_tok = toks[name_idx]
        name = name_tok.text
        # Qualified name tokens before name (Scope::name)
        qparts = []
        j = name_idx
        while j >= 2 and toks[j - 1].text == "::" and toks[j - 2].kind == "ident":
            qparts.insert(0, toks[j - 2].text)
            j -= 2
        ret_toks = toks[:j] if not qparts else toks[:j]
        # If qualified, ret is tokens before the qualifier chain.
        if qparts:
            ret_toks = toks[:name_idx - 2 * len(qparts)]
        mods = []
        type_parts = []
        for t in ret_toks:
            if t.text in _MODIFIERS and t.text not in ("volatile",):
                mods.append(t.text)
            else:
                type_parts.append(t)
        in_class = owner is not None and isinstance(owner, Compound) and owner.kind in ("class", "struct", "union", "interface")
        class_name = owner.name if in_class else (qparts[-1] if qparts else None)
        is_ctor = class_name is not None and name == class_name.split("<")[0]
        is_dtor = name.startswith("~")
        m = Member("function", name if not operator_fix(name) else name)
        m.template_params = template_params or []
        if is_ctor or is_dtor:
            m.type = ""
        else:
            m.type = _join_tokens(type_parts)
        args_toks = toks[lparen + 1:rparen]
        suffix_toks = toks[rparen + 1:]
        m.params = _parse_params(args_toks)
        args_core = _join_tokens(args_toks)
        argsstring = "(" + args_core + ")"
        suffix_text = _join_tokens([t for t in suffix_toks if t.text not in (";",)])
        m.const = any(t.text == "const" for t in suffix_toks) or is_const_type(mods, ret_toks) and False
        if any(t.text == "const" for t in suffix_toks):
            m.const = True
        if "static" in mods: m.static = True
        if "inline" in mods: m.inline = True
        if "explicit" in mods: m.explicit = True
        if "extern" in mods: m.extern = True
        if "virtual" in mods:
            # pure virtual if '= 0' in suffix
            m.virt = "pure-virtual" if any(t.text == "0" for t in suffix_toks) else "virtual"
        elif any(t.text == "override" for t in suffix_toks):
            m.virt = "virtual"
        if "friend" in mods:
            m.kind = "friend"
        if suffix_text:
            # Remove removed/default markers from argsstring? keep const etc.
            suffix_clean = []
            skip = False
            for t in suffix_toks:
                if t.text == "=":
                    break
                if t.text in ("override", "final"):
                    continue
                suffix_clean.append(t)
            sc = _join_tokens(suffix_clean)
            if sc:
                argsstring += " " + sc
        m.argsstring = argsstring
        m.prot = access if in_class else "public"
        m.location = Location(self.file.name, name_tok.line, name_tok.col)
        if body:
            m.location.body_file = self.file.name
            m.location.body_start = body[0]
            m.location.body_end = body[1]
            if toks:
                m.location.decl_file = self.file.name
                m.location.decl_line = name_tok.line
                m.location.decl_column = name_tok.col
        else:
            if not in_class:
                m.location.decl_file = self.file.name
                m.location.decl_line = name_tok.line
                m.location.decl_column = name_tok.col
        return m

    def _make_variables(self, toks, owner, access, template_params):
        # Ignore non-declarations (expressions, control statements).
        first = toks[0].text if toks else ""
        if first in ("return", "if", "for", "while", "switch", "case", "break", "continue", "goto", "else", "do", "throw"):
            return []
        # Split declarators by commas at top level (ignoring inits).
        decl_groups = _split_top_level(toks, ",")
        if not decl_groups:
            return []
        members = []
        base_type = None
        base_mods = []
        for gi, group in enumerate(decl_groups):
            if not group:
                continue
            # Initializer
            init_toks = None
            eq_idx = next((i for i, t in enumerate(group) if t.text == "="), None)
            decl = group
            if eq_idx is not None:
                decl = group[:eq_idx]
                init_toks = group[eq_idx + 1:]
            # Pointer/reference prefixes and array suffix around name.
            name_idx = _find_var_name(decl, first_group=(gi == 0))
            if name_idx is None:
                continue
            name_tok = decl[name_idx]
            prefix = decl[:name_idx]
            suffix = decl[name_idx + 1:]
            if gi == 0:
                mods = [t.text for t in prefix if t.text in _MODIFIERS and t.text not in ("const", "volatile")]
                # const/volatile belong to the type text for variables.
                type_toks = [t for t in prefix if t.text not in ("static", "extern", "inline", "register", "mutable", "thread_local", "friend", "constexpr")]
                base_type = _join_tokens(type_toks)
                base_mods = mods
                ptr = "".join(t.text for t in prefix if t.text in ("*", "&", "&&"))
                vtype = (base_type + (" " + ptr if ptr and base_type else ptr)).strip()
                # If prefix ended with */& that also is in type_toks, ptr duplication
                # can happen: rebuild by removing trailing ptr from base if needed.
                vtype = _join_tokens(type_toks)
            else:
                mods = list(base_mods)
                ptr_toks = [t for t in prefix]
                vtype = ((base_type or "") + (" " if base_type and ptr_toks else "") + _join_tokens(ptr_toks)).strip()
            in_class = owner is not None and isinstance(owner, Compound) and owner.kind in ("class", "struct", "union", "interface")
            m = Member("variable", name_tok.text)
            m.type = vtype
            m.prot = access if in_class else "public"
            m.static = "static" in mods or any(t.text == "static" for t in toks[:name_idx])
            m.extern = any(t.text == "extern" for t in toks)
            m.mutable = any(t.text == "mutable" for t in toks)
            if init_toks is not None:
                init_text = _join_tokens(init_toks)
                m.initializer = "= " + init_text if init_text else None
                if suffix and suffix[0].text in ("[", "("):
                    # array / constructor init handled below
                    pass
            if suffix and suffix[0].text == "[":
                # Array: argsstring holds dimensions, type remains element
                dim = _join_tokens(suffix)
                m.argsstring = dim
                if init_toks is not None:
                    m.initializer = "= " + _join_tokens(init_toks)
            elif suffix and suffix[0].text == "(":
                args = _join_tokens(suffix)
                m.argsstring = args
                m.initializer = None
            m.location = Location(self.file.name, name_tok.line, name_tok.col)
            if m.extern and not in_class:
                m.location.decl_file = self.file.name
                m.location.decl_line = name_tok.line
                m.location.decl_column = name_tok.col
            else:
                m.location.body_file = self.file.name
                m.location.body_start = name_tok.line
                m.location.body_end = -1
            members.append(m)
        return members


