            # their anchor is computed from name+name (verified pattern
            # for variables).  For enums use qualified name as prefix
            # component set in _register_member then fix definition.
            self._register_member(m, owner)
            m.definition = m.qualified
            for ev in m.enumvalues:
                ev.parent = m.parent
                ev.file_compound = self.file
                ev.qualified = (m.qualified + "::" + ev.name) if m.qualified else ev.name
