        nxt = self._peek_token()
        if isinstance(nxt, _Tok) and nxt.text in ("struct", "class", "union", "enum"):
            # Let class/enum parser run with owner; trailing name becomes
            # the typedef.  Simplified: parse the compound/enum, then
            # create a typedef to it if a name followed.
            # Capture compound count.
            if nxt.text == "enum":
                self._parse_enum(owner, parent_compound, access)
            else:
                self._parse_class(owner, parent_compound, access, [])
