            m.const = True
        if "static" in mods: m.static = True
        if "inline" in mods: m.inline = True
        if "explicit" in mods: m.explicit = True
        if "extern" in mods: m.extern = True
        if "virtual" in mods:
            # pure virtual if '= 0' in suffix
            m.virt = "pure-virtual" if any(t.text == "0" for t in suffix_toks) else "virtual"
        elif any(t.text == "override" for t in suffix_toks):
            m.virt = "virtual"
        if "friend" in mods:
            m.kind = "friend"
