    def _make_variables(self, toks, owner, access, template_params):
        # Ignore non-declarations (expressions, control statements).
        first = toks[0].text if toks else ""
        if first in ("return", "if", "for", "while", "switch", "case", "break", "continue", "goto", "else", "do", "throw"):
            return []
        # Split declarators by commas at top level (ignoring inits).
        decl_groups = _split_top_level(toks, ",")
        if not decl_groups:
            return []
        members = []
        base_type = None
        base_mods = []
        for gi, group in enumerate(decl_groups):
            if not group:
                continue
            # Initializer
            init_toks = None
            eq_idx = next((i for i, t in enumerate(group) if t.text == "="), None)
            decl = group
            if eq_idx is not None:
                decl = group[:eq_idx]
                init_toks = group[eq_idx + 1:]
