                mods = [t.text for t in prefix if t.text in _MODIFIERS and t.text not in ("const", "volatile")]
                # const/volatile belong to the type text for variables.
                type_toks = [t for t in prefix if t.text not in ("static", "extern", "inline", "register", "mutable", "thread_local", "friend", "constexpr")]
                base_type = _join_tokens(type_toks)
                base_mods = mods
                ptr = "".join(t.text for t in prefix if t.text in ("*", "&", "&&"))
