                # If prefix ended with */& that also is in type_toks, ptr duplication
                # can happen: rebuild by removing trailing ptr from base if needed.
                vtype = _join_tokens(type_toks)
            else:
                mods = list(base_mods)
                ptr_toks = [t for t in prefix]
                vtype = ((base_type or "") + (" " if base_type and ptr_toks else "") + _join_tokens(ptr_toks)).strip()
            in_class = owner is not None and isinstance(owner, Compound) and owner.kind in ("class", "struct", "union", "interface")
            m = Member("variable", name_tok.text)
            m.type = vtype
            m.prot = access if in_class else "public"
            m.static = "static" in mods or any(t.text == "static" for t in toks[:name_idx])
            m.extern = any(t.text == "extern" for t in toks)
            m.mutable = any(t.text == "mutable" for t in toks)
            if init_toks is not None:
                init_text = _join_tokens(init_toks)
                m.initializer = "= " + init_text if init_text else None
                if suffix and suffix[0].text in ("[", "("):
                    # array / constructor init handled below
                    pass
            if suffix and suffix[0].text == "[":
                # Array: argsstring holds dimensions, type remains element
                dim = _join_tokens(suffix)
                m.argsstring = dim
                if init_toks is not None:
                    m.initializer = "= " + _join_tokens(init_toks)
            elif suffix and suffix[0].text == "(":
                args = _join_tokens(suffix)
                m.argsstring = args
                m.initializer = None
            m.location = Location(self.file.name, name_tok.line, name_tok.col)
            if m.extern and not in_class:
                m.location.decl_file = self.file.name
                m.location.decl_line = name_tok.line
                m.location.decl_column = name_tok.col
            else:
                m.location.body_file = self.file.name
                m.location.body_start = name_tok.line
                m.location.body_end = -1
            members.append(m)
        return members


