def _split_top_level(toks, sep=","):
    out = []
    cur = []
    depth = 0
    for t in toks:
        if t.text in ("(", "[", "{", "<"):
            depth += 1
        elif t.text in (")", "]", "}", ">"):
            if depth > 0:
                depth -= 1
        if t.text == sep and depth == 0:
            out.append(cur)
            cur = []
        else:
            cur.append(t)
    if cur or not out:
        out.append(cur)
    return out


def _parse_params(args_toks):
    if not args_toks:
        return []
    groups = _split_top_level(args_toks, ",")
    params = []
    for g in groups:
        if not g:
            continue
        # default value
        defval = None
        eq = next((i for i, t in enumerate(g) if t.text == "="), None)
        if eq is not None:
            defval = _join_tokens(g[eq + 1:])
            g = g[:eq]
        if len(g) == 1 and g[0].text == "void":
            params.append({"type": "void", "declname": None, "defval": None})
            continue
        if _join_tokens(g) == "...":
            params.append({"type": "...", "declname": None, "defval": None})
            continue
        name_idx = _find_var_name(g, first_group=True, param=True)
        if name_idx is None or name_idx == 0:
            params.append({"type": _join_tokens(g), "declname": None, "defval": defval})
        else:
            # Array suffix belongs to type in doxygen output usually.
            suffix = g[name_idx + 1:]
            type_text = _join_tokens(g[:name_idx])
            if suffix:
                # e.g. int a[] -> type "int []"? doxygen keeps as "int[]" often.
                type_text = (type_text + _join_tokens(suffix)).strip()
            params.append({"type": type_text, "declname": g[name_idx].text, "defval": defval})
    return params


def _parse_template_params(toks):
    groups = _split_top_level(toks, ",")
    out = []
    for g in groups:
        if not g:
            continue
        defval = None
        eq = next((i for i, t in enumerate(g) if t.text == "="), None)
        if eq is not None:
            defval = _join_tokens(g[eq + 1:])
            g = g[:eq]
        name_idx = _find_var_name(g, first_group=True, param=True)
        if name_idx is None:
            out.append({"type": _join_tokens(g), "declname": None, "defval": defval})
        else:
            out.append({"type": _join_tokens(g[:name_idx]), "declname": g[name_idx].text, "defval": defval})
    return out


def _find_function(toks):
    """Find (name_idx, lparen, rparen) for a function declaration."""
    # '=' before '(' generally means an initializer, not a function,
    # unless the '(' is after an identifier and no '=' precedes it.
    n = len(toks)
    for i, t in enumerate(toks):
        if t.text != "(":
            continue
        if i == 0:
            continue
        prev = toks[i - 1]
        # operator()
        if prev.kind == "ident" or prev.text in (">", "]"):
            # Find matching ) at top.
            depth = 0
            rparen = None
            for j in range(i, n):
                if toks[j].text == "(": depth += 1
                elif toks[j].text == ")":
                    depth -= 1
                    if depth == 0:
                        rparen = j
                        break
            if rparen is None:
                return None
            # If there's an '=' before lparen (initializer), bail.
            if any(x.text == "=" for x in toks[:i]):
                return None
            # Function pointer: (*name)(...) prev is ')' handling skipped.
            name_idx = i - 1
            # operator< etc: name includes 'operator' token + following.
            if prev.kind != "ident":
                continue
            return (name_idx, i, rparen)
        if prev.text == "~":
            continue
    # Destructor ~Name(...)
    for i, t in enumerate(toks):
        if t.text == "~" and i + 2 < n and toks[i + 1].kind == "ident" and toks[i + 2].text == "(":
            depth = 0; rparen = None
            for j in range(i + 2, n):
                if toks[j].text == "(": depth += 1
                elif toks[j].text == ")":
                    depth -= 1
                    if depth == 0: rparen = j; break
            if rparen is not None:
                toks[i + 1].text = "~" + toks[i + 1].text
                return (i + 1, i + 2, rparen)
    return None


def _find_var_name(toks, first_group=True, param=False):
    """Return index of the declared name in a declarator token list."""
    if not toks:
        return None
    # Pointer/array: last identifier that is not a type keyword and not
    # part of a qualified/template type chain when it is the only one.
    candidates = []
    prev_was_scope = False
    in_template = 0
    for i, t in enumerate(toks):
        if t.text == "<": in_template += 1
        elif t.text == ">": in_template = max(0, in_template - 1)
        if t.kind != "ident":
            if t.text == "::":
                prev_was_scope = True
            else:
                prev_was_scope = False
            continue
        is_typeword = t.text in _KEYWORD_TYPES or t.text in _MODIFIERS or t.text in ("const", "struct", "class", "enum", "union", "typename", "template")
        candidates.append((i, is_typeword, prev_was_scope, in_template > 0))
        prev_was_scope = False
    if not candidates:
        return None
    # A name is generally the LAST ident that is not inside <>, and
    # either not a scope component, or the last scope component right
    # before '(' in a qualified function name (handled elsewhere).
    # For a declarator like "unsigned long x": last ident is name.
    # For "std::string name": chain std::string then name.
    # Strategy: from end, choose first ident not in template and not a
    # keyword; but if it is preceded by '::' and there is a further
    # ident after? none.
    for i, is_type, was_scope, in_tmpl in reversed(candidates):
        if in_tmpl:
            continue
        if is_type:
            continue
        # If this ident is a type component followed by '::', it's part of type.
        if i + 1 < len(toks) and toks[i + 1].text == "::":
            continue
        # If all tokens before are none (single ident param "int" handled by keyword)
        return i
    return None


def scan_file(project, file_compound, source, warn):
    scanner = _Scanner(project, file_compound, project.cfg, warn)
    scanner.lex(source)
    scanner.parse()
    return scanner.standalone
