"""Shared rendering helpers for documentation blocks."""

import re

from .names import html_escape, xml_escape, xml_escape_attr

_WORD_RE = re.compile(r"([A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*)")


class RenderContext:
    def __init__(self, project, cfg, warn=None):
        self.project = project
        self.cfg = cfg
        self.warn = warn
        self._index = None

    @property
    def index(self):
        if self._index is None:
            self._index = self.project.symbol_index()
        return self._index

    def resolve(self, target):
        target = target.strip()
        idx = self.index
        if target in idx:
            return idx[target]
        # \ref to a file by name
        for f in self.project.files:
            if f.name == target or f.qualified == target:
                return f
        # Function references may be written as name() or name(args)
        m = re.match(r"^([A-Za-z_][\w:]*)\s*\(.*\)$", target)
        if m and m.group(1) in idx:
            return idx[m.group(1)]
        return None

    def refid_of(self, entity):
        from .model import Compound, Member

        if isinstance(entity, Compound):
            return entity.id, "compound"
        if isinstance(entity, Member):
            if entity.kind == "enumvalue":
                return entity.id, "member"
            return entity.id, "member"
        return "", "compound"

    def autolink(self, text):
        """Split a text string into (is_ref, text, entity) chunks when
        AUTOLINK_SUPPORT is enabled."""
        if self.cfg is not None and not self.cfg.get_bool("AUTOLINK_SUPPORT"):
            return [(False, text, None)]
        ignore = set()
        if self.cfg is not None:
            try:
                ignore = set(self.cfg.get_list("AUTOLINK_IGNORE_WORDS"))
            except Exception:
                pass
        out = []
        pos = 0
        for m in _WORD_RE.finditer(text):
            word = m.group(1)
            entity = self.index.get(word) if word not in ignore else None
            # Require an exact (case sensitive) match on a known name with
            # at least two characters, or a qualified name.
            if entity is not None and (len(word) >= 2):
                # Only link if the matched name really is this word.
                ent_names = {getattr(entity, "qualified", ""), getattr(entity, "name", "")}
                if word not in ent_names:
                    entity = None
            else:
                entity = None
            if entity is None:
                continue
            if m.start() > pos:
                out.append((False, text[pos:m.start()], None))
            out.append((True, word, entity))
            pos = m.end()
        if pos < len(text):
            out.append((False, text[pos:], None))
        if not out:
            out = [(False, text, None)]
        return out


# --------------------------------------------------------------------------
# XML rendering of doc blocks


def _xml_text_with_autolink(text, ctx):
    out = []
    for is_ref, chunk, entity in ctx.autolink(text):
        if is_ref:
            refid, kindref = ctx.refid_of(entity)
            out.append(f'<ref refid="{xml_escape_attr(refid)}" kindref="{kindref}">{xml_escape(chunk)}</ref>')
        else:
            out.append(xml_escape(chunk))
    return "".join(out)


def xml_inline(nodes, ctx):
    out = []
    for node in nodes:
        tag = node[0]
        if tag == "text":
            out.append(_xml_text_with_autolink(node[1], ctx))
        elif tag == "code":
            out.append(f"<computeroutput>{xml_escape(node[1])}</computeroutput>")
        elif tag == "bold":
            out.append(f"<bold>{xml_inline(node[1], ctx)}</bold>")
        elif tag == "emph":
            out.append(f"<emphasis>{xml_inline(node[1], ctx)}</emphasis>")
        elif tag == "ref":
            target = node[1]
            entity = ctx.resolve(target)
            display_nodes = node[2] if len(node) > 2 and node[2] else [("text", target)]
            display = xml_inline_plain(display_nodes, ctx)
            if entity is not None:
                refid, kindref = ctx.refid_of(entity)
                out.append(f'<ref refid="{xml_escape_attr(refid)}" kindref="{kindref}">{display}</ref>')
            else:
                out.append(display)
        elif tag == "link":
            out.append(f'<ulink url="{xml_escape_attr(node[1])}">{xml_inline(node[2], ctx)}</ulink>')
        elif tag == "break":
            out.append("<linebreak/>")
    return "".join(out)


def xml_inline_plain(nodes, ctx):
    # Like xml_inline but without autolinking nested text.
    out = []
    for node in nodes:
        if node[0] == "text":
            out.append(xml_escape(node[1]))
        elif node[0] == "code":
            out.append(f"<computeroutput>{xml_escape(node[1])}</computeroutput>")
        elif node[0] == "bold":
            out.append(f"<bold>{xml_inline_plain(node[1], ctx)}</bold>")
        elif node[0] == "emph":
            out.append(f"<emphasis>{xml_inline_plain(node[1], ctx)}</emphasis>")
        else:
            out.append(xml_inline([node], ctx))
    return "".join(out)


def _para_xml(nodes, ctx, trailing_space=True):
    inner = xml_inline(nodes, ctx)
    # The reference strips leading space and (for the last paragraph of a
    # description) leaves a single trailing space after text content.
    inner = inner.lstrip()
    if trailing_space and inner and not inner.endswith(" ") and not inner.endswith(">"):
        inner += " "
    elif trailing_space and inner.endswith(">") and not inner.endswith("/>"):
        # Text ending in a tag (e.g. </ref>) gets a space too in cases
        # like '<ref...>Color</ref> enum. ' - already in text nodes.
        pass
    if not trailing_space:
        inner = inner.rstrip()
    return f"<para>{inner}</para>"


def xml_blocks(blocks, ctx, top=True):
    """Render a list of blocks as XML description content."""
    out = []
    n = len(blocks)
    i = 0
    while i < n:
        b = blocks[i]
        tag = b[0]
        last = (i == n - 1)
        if tag == "para":
            out.append(_para_xml(b[1], ctx, trailing_space=last))
            out.append("\n")
        elif tag in ("paramlist", "simplesect"):
            # Consecutive paramlist/simplesect blocks share one <para>.
            group = []
            while i < n and blocks[i][0] in ("paramlist", "simplesect"):
                group.append(blocks[i])
                i += 1
            i -= 1
            inner = []
            for g in group:
                inner.append(_xml_param_or_sect(g, ctx))
            out.append("<para>" + "\n".join(inner) + "\n</para>")
            out.append("\n")
        elif tag == "list":
            listtag = "orderedlist" if b[1] else "itemizedlist"
            items = []
            for item in b[2]:
                items.append("<listitem>" + xml_blocks(item, ctx).strip("\n") + "</listitem>")
            out.append("<para><" + listtag + ">\n" + "\n".join(items) + "\n</" + listtag + ">\n</para>")
            out.append("\n")
        elif tag in ("codeblock", "verbatim"):
            text = b[1]
            lines = []
            for ln in text.split("\n"):
                lines.append(f'<codeline><highlight class="normal">{xml_escape(ln)}</highlight></codeline>')
            para_inner = "<programlisting>" + "".join(lines) + "</programlisting>"
