    # Files themselves have location without line info.
    if kind == "file":
        return " ".join(attrs)
    attrs.append(f'line="{loc.line}"')
    attrs.append(f'column="{loc.column}"')
    if loc.decl_file:
        attrs.append(f'declfile="{xml_escape_attr(loc.decl_file)}"')
        attrs.append(f'declline="{loc.decl_line}"')
        attrs.append(f'declcolumn="{loc.decl_column}"')
    if loc.body_file:
        attrs.append(f'bodyfile="{xml_escape_attr(loc.body_file)}"')
        attrs.append(f'bodystart="{loc.body_start}"')
        attrs.append(f'bodyend="{loc.body_end}"')
    return " ".join(attrs)


def _section_key(parent_kind, member):
    if parent_kind in ("class", "struct", "union", "interface"):
        if member.kind == "friend":
            return ("friend", 99, 0)
        if member.kind in ("typedef", "enum"):
            return (f"{member.prot}-type", 0, _PROT_ORDER.get(member.prot, 0))
        if member.kind == "variable":
            key = f"{member.prot}-static-attrib" if member.static else f"{member.prot}-attrib"
            return (key, 1, _PROT_ORDER.get(member.prot, 0) + (10 if member.static else 0))
        if member.kind == "function":
            key = f"{member.prot}-static-func" if member.static else f"{member.prot}-func"
            return (key, 2, _PROT_ORDER.get(member.prot, 0) + (10 if member.static else 0))
        return (f"{member.prot}-func", 3, 0)
    key = {"define": "define", "enum": "enum", "typedef": "typedef",
           "variable": "var", "function": "func", "friend": "func"}.get(member.kind, "func")
    return (key, _NS_KIND_ORDER.get(member.kind, 4), 0)


def _group_sections(parent, sort_brief=False):
    sections = {}
    order = {}
    for m in parent.members:
        if m.kind == "enumvalue":
            continue
        key, cat, sub = _section_key(parent.kind, m)
        order[key] = (cat, sub)
        sections.setdefault(key, []).append(m)
    keys = sorted(sections.keys(), key=lambda k: order[k])
    if sort_brief:
        for k in keys:
            sections[k] = sorted(sections[k], key=lambda m: m.name)
    return [(k, sections[k]) for k in keys]


def _member_xml(m, ctx, indent="      "):
    cfg = ctx.cfg
    out = []
    attrs = [f'kind="{m.kind}"', f'id="{xml_escape_attr(m.id)}"', f'prot="{m.prot}"']
    if m.kind != "enumvalue":
        attrs.append(f'static="{_yn(m.static)}"')
    if m.kind == "function" or m.kind == "friend":
        attrs.append(f'const="{_yn(m.const)}"')
        attrs.append(f'explicit="{_yn(m.explicit)}"')
        attrs.append(f'inline="{_yn(m.inline)}"')
        attrs.append(f'virt="{m.virt}"')
    elif m.kind == "variable":
        if m.extern:
            attrs.append(f'extern="{_yn(m.extern)}"')
        attrs.append(f'mutable="{_yn(m.mutable)}"')
    elif m.kind == "enum":
        attrs.append(f'strong="{_yn(m.strong)}"')
    out.append(f"{indent}<memberdef {' '.join(attrs)}>\n")
    ii = indent + "  "
    if m.template_params:
        out.append(f"{ii}<templateparamlist>\n")
        for p in m.template_params:
            out.append(f"{ii}  <param>\n")
            out.append(f"{ii}    <type>{xml_type(p.get('type',''), ctx)}</type>\n")
            if p.get("declname"):
                out.append(f"{ii}    <declname>{xml_escape(p['declname'])}</declname>\n")
                out.append(f"{ii}    <defname>{xml_escape(p['declname'])}</defname>\n")
            if p.get("defval"):
                out.append(f"{ii}    <defval>{xml_type(p['defval'], ctx)}</defval>\n")
            out.append(f"{ii}  </param>\n")
        out.append(f"{ii}</templateparamlist>\n")
    if m.kind in ("function", "variable", "typedef", "friend"):
        out.append(f"{ii}<type>{xml_type(m.type, ctx)}</type>\n")
        if m.definition:
            out.append(f"{ii}<definition>{xml_escape(m.definition)}</definition>\n")
        out.append(f"{ii}<argsstring>{xml_escape(m.argsstring)}</argsstring>\n")
    elif m.kind == "enum":
        out.append(f"{ii}<type>{xml_type(m.type, ctx) if m.type else ''}</type>\n")
    out.append(f"{ii}<name>{xml_escape(m.name)}</name>\n")
    parent = m.parent
    if parent is not None and parent.kind != "file":
        out.append(f"{ii}<qualifiedname>{xml_escape(m.qualified)}</qualifiedname>\n")
    for p in m.params:
        out.append(f"{ii}<param>\n")
        out.append(f"{ii}  <type>{xml_type(p.get('type',''), ctx)}</type>\n")
        if p.get("declname"):
            out.append(f"{ii}  <declname>{xml_escape(p['declname'])}</declname>\n")
        if p.get("defval") is not None:
            out.append(f"{ii}  <defval>{xml_type(p['defval'], ctx)}</defval>\n")
        out.append(f"{ii}</param>\n")
    if m.kind == "enum":
        for ev in m.enumvalues:
            evid = _enumvalue_id(m, ev)
            out.append(f'{ii}<enumvalue id="{xml_escape_attr(evid)}" prot="{ev.prot}">\n')
            out.append(f"{ii}  <name>{xml_escape(ev.name)}</name>\n")
            if ev.initializer:
                out.append(f"{ii}  <initializer>= {xml_escape(ev.initializer.lstrip('= '))}</initializer>\n")
            out.append(f"{ii}  <briefdescription>{xml_description(ev.doc.brief, ctx)}{ii}  </briefdescription>\n")
            out.append(f"{ii}  <detaileddescription>{xml_description(ev.doc.detailed, ctx)}{ii}  </detaileddescription>\n")
            out.append(f"{ii}</enumvalue>\n")
    if m.initializer is not None and m.kind in ("variable", "define"):
        init = m.initializer
        if m.kind == "variable" and not init.startswith("="):
            init = "= " + init
        out.append(f"{ii}<initializer>{xml_escape(init)}</initializer>\n")
    out.append(f"{ii}<briefdescription>{xml_description(m.doc.brief, ctx)}{ii}</briefdescription>\n")
    out.append(f"{ii}<detaileddescription>{xml_description(m.doc.detailed, ctx)}{ii}</detaileddescription>\n")
    out.append(f"{ii}<inbodydescription>{xml_description(m.doc.inbody, ctx)}{ii}</inbodydescription>\n")
    out.append(f"{ii}<location {_location_attrs(m.location, m.kind)}/>\n")
    out.append(f"{indent}</memberdef>\n")
    return "".join(out)


def _enumvalue_id(enum_member, ev):
    return enum_member.id + "a" + hashlib.md5(ev.name.encode()).hexdigest()


def _compound_xml(c, ctx):
    cfg = ctx.cfg
    out = []
    out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
    out.append(
        '<doxygen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" '
        f'xsi:noNamespaceSchemaLocation="compound.xsd" version="1.17.0" xml:lang="{XML_LANG}">\n'
    )
    attrs = [f'id="{xml_escape_attr(c.id)}"', f'kind="{c.kind}"']
    if c.kind in ("class", "struct", "union", "interface", "namespace", "file", "concept", "module"):
        attrs.append(f'language="{xml_escape_attr(c.language)}"')
    if c.kind in ("class", "struct", "union", "interface", "concept"):
        attrs.append(f'prot="{c.prot}"')
    out.append(f"  <compounddef {' '.join(attrs)}>\n")
    out.append(f"    <compoundname>{xml_escape(_display_name(c, cfg))}</compoundname>\n")
    if c.kind in ("class", "struct", "union", "interface", "concept"):
        if c.inc_file and cfg.get_bool("SHOW_HEADERFILE"):
            # Search for the file compound id.
            ref = ""
            for f in ctx.project.files:
                if f.name == c.inc_file:
                    ref = f.id
                    break
            local = "no"
            out.append(f'    <includes refid="{xml_escape_attr(ref)}" local="{local}">{xml_escape(c.inc_file)}</includes>\n')
        for base_name, base_prot, base_virt in c.bases:
            base = ctx.project.find_compound(base_name)
            refattr = f' refid="{xml_escape_attr(base.id)}"' if base is not None else ""
            out.append(f'    <basecompoundref{refattr} prot="{base_prot}" virt="{base_virt}">{xml_escape(base_name)}</basecompoundref>\n')
        for der in c.derived:
            out.append(f'    <derivedcompoundref refid="{xml_escape_attr(der.id)}" prot="public" virt="non-virtual">{xml_escape(der.qualified)}</derivedcompoundref>\n')
        if c.template_params:
            out.append("    <templateparamlist>\n")
            for p in c.template_params:
                out.append("      <param>\n")
                out.append(f"        <type>{xml_type(p.get('type',''), ctx)}</type>\n")
                if p.get("declname"):
                    out.append(f"        <declname>{xml_escape(p['declname'])}</declname>\n")
                    out.append(f"        <defname>{xml_escape(p['declname'])}</defname>\n")
                if p.get("defval"):
                    out.append(f"        <defval>{xml_type(p['defval'], ctx)}</defval>\n")
                out.append("      </param>\n")
            out.append("    </templateparamlist>\n")
    if c.kind == "file" and cfg.get_bool("SHOW_INCLUDE_FILES"):
        for inc_name, _ref, local in c.includes:
            ref = ""
            for f in ctx.project.files:
                if f.name == inc_name or (f.rel_path or "").endswith("/" + inc_name):
                    ref = f.id
                    break
            out.append(f'    <includes refid="{xml_escape_attr(ref)}" local="{"yes" if local else "no"}">{xml_escape(inc_name)}</includes>\n')
        for inc_name in c.included_by:
            out.append(f'    <includedby refid="" local="no">{xml_escape(inc_name)}</includedby>\n')
    # Inner compounds
    inner_kinds = [
        ("innerclass", ("class", "struct", "union", "interface", "concept")),
        ("innernamespace", ("namespace",)),
        ("innerfile", ("file",)),
        ("innerpage", ("page",)),
        ("innergroup", ("group",)),
    ]
    seen = set()
    for tagname, kinds in inner_kinds:
        for inner in c.inner:
            if inner.kind in kinds and inner.id not in seen:
                seen.add(inner.id)
                protattr = f' prot="{inner.prot}"' if tagname == "innerclass" else ""
                out.append(f'    <{tagname} refid="{xml_escape_attr(inner.id)}"{protattr}>{xml_escape(inner.qualified)}</{tagname}>\n')
    if c.kind == "dir":
        # Files/subdirs are represented through inner lists in generate.
        pass
    sort_brief = cfg.get_bool("SORT_BRIEF_DOCS")
    for key, members in _group_sections(c, sort_brief=sort_brief):
        out.append(f'    <sectiondef kind="{key}">\n')
        for m in members:
            out.append(_member_xml(m, ctx))
        out.append("    </sectiondef>\n")
    out.append(f"    <briefdescription>{xml_description(c.doc.brief, ctx)}    </briefdescription>\n")
    out.append(f"    <detaileddescription>{xml_description(c.doc.detailed, ctx)}    </detaileddescription>\n")
    if c.kind == "file" and cfg.get_bool("XML_PROGRAMLISTING") and c.source:
        out.append("    <programlisting>\n")
        out.append(_program_listing(c, ctx))
        out.append("    </programlisting>\n")
    if c.kind == "file":
        out.append(f'    <location file="{xml_escape_attr(c.name)}"/>\n')
    elif c.kind in ("page", "group"):
        pass
    elif c.kind == "dir":
        out.append(f'    <location file="{xml_escape_attr(c.name)}"/>\n')
    else:
        out.append(f"    <location {_location_attrs(c.location, c.kind)}/>\n")
    if c.kind in ("class", "struct", "union", "interface"):
        out.append("    <listofallmembers>\n")
        for m in sorted(c.members, key=lambda mm: mm.name.lower()):
            virt = m.virt if m.kind == "function" else "non-virtual"
            out.append(f'      <member refid="{xml_escape_attr(m.id)}" prot="{m.prot}" virt="{virt}"><scope>{xml_escape(c.qualified)}</scope><name>{xml_escape(m.name)}</name></member>\n')
        out.append("    </listofallmembers>\n")
    out.append("  </compounddef>\n")
    out.append("</doxygen>\n")
    return "".join(out)


def _display_name(c, cfg):
    if c.kind == "file":
        return c.name
    if c.kind == "dir":
        return c.name
    return c.qualified


_KEYWORDTYPES = {"void", "bool", "char", "short", "int", "long", "float", "double", "signed", "unsigned", "wchar_t"}
_KEYWORDS = {
    "class", "struct", "union", "enum", "namespace", "public", "private",
    "protected", "virtual", "static", "const", "if", "else", "for",
    "while", "do", "switch", "case", "default", "return", "new",
    "delete", "template", "typename", "typedef", "using", "friend",
    "inline", "extern", "volatile", "mutable", "constexpr", "noexcept",
    "this", "true", "false", "nullptr",
}
_FLOW = {"return", "if", "else", "for", "while", "do", "switch", "case", "break", "continue", "goto"}


def _program_listing(file_compound, ctx):
    cfg = ctx.cfg
    source = file_compound.source or ""
    strip = cfg.get_bool("STRIP_CODE_COMMENTS")
    # Remove comments if requested / all doc comment lines.
    lines = _code_lines(source, strip_comments=strip)
    # Index members declared per line.
    by_line = {}
    for m in ctx.project.all_members:
        if m.file_compound is file_compound:
            by_line.setdefault(m.location.line, []).append(m)
    out = []
    for lineno, code in lines:
        toks = _tokenize_code_line(code)
        members_here = by_line.get(lineno, [])
        ref_member = None
        for m in members_here:
            if m.documented():
                ref_member = m
                break
        attrs = f'lineno="{lineno}"'
        if ref_member is not None:
            attrs += f' refid="{xml_escape_attr(ref_member.id)}" refkind="member"'
        out.append(f"<codeline {attrs}>")
        segs = []
        cur_class = None
        cur_text = []

        def push(cls, text):
            nonlocal cur_class, cur_text
            if cls != cur_class:
                if cur_class is not None:
                    segs.append((cur_class, "".join(cur_text)))
                cur_class = cls
                cur_text = []
            cur_text.append(text)

        for tok in toks:
            text = tok
            if text in _KEYWORDTYPES:
                cls = "keywordtype"
            elif text in _FLOW:
                cls = "keywordflow"
            elif text in _KEYWORDS:
                cls = "keyword"
            else:
                cls = "normal"
            # Link documented member/compound names.
            if cls == "normal" and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", text):
                ent = None
                for m in members_here:
                    if m.name == text and m.documented():
                        ent = m
                        break
                if ent is not None:
                    push("normal", "\x01" + ent.id + "\x02" + text + "\x03")
                    continue
            push(cls, text)
        if cur_class is not None:
            segs.append((cur_class, "".join(cur_text)))
        if not segs:
            segs = [("normal", "")]
        for cls, text in segs:
            content = _xml_code_text(text, cls)
            out.append(f'<highlight class="{cls}">{content}</highlight>')
        out.append("</codeline>\n")
    return "".join(out)


def _xml_code_text(text, cls):
    # Handle embedded ref markers.
    parts = re.split(r"([\x01].*?[\x03])", text)
    out = []
    for part in parts:
        if part.startswith("\x01"):
            refid, word = part[1:-1].split("\x02", 1)
            out.append(f'<ref refid="{xml_escape_attr(refid)}" kindref="member">{xml_escape(word)}</ref>')
        else:
            esc = xml_escape(part)
            if cls == "normal":
                esc = esc.replace(" ", "<sp/>")
            out.append(esc)
    return "".join(out)


def _tokenize_code_line(code):
    toks = []
    for m in re.finditer(r'"(?:[^"\\]|\\.)*"|\'(?:[^\'\\]|\\.)*\'|[A-Za-z_][A-Za-z0-9_]*|\d+(?:\.\d+)?|\s+|.', code):
        toks.append(m.group(0))
    return toks


def _code_lines(source, strip_comments=True):
    lines = source.split("\n")
    out = []
    in_block = False
    block_start_line = None
    for idx, line in enumerate(lines, 1):
        result = ""
        i = 0
        was_comment_line = False
        while i < len(line):
            if in_block:
                end = line.find("*/", i)
                if end == -1:
                    i = len(line)
                    was_comment_line = True
                else:
                    in_block = False
                    i = end + 2
                continue
            if line.startswith("/*", i):
                end = line.find("*/", i + 2)
                was_comment_line = True
                if end == -1:
                    in_block = True
                    block_start_line = idx
                    i = len(line)
                else:
                    if not strip_comments:
                        result += line[i:end + 2]
                    i = end + 2
                continue
            if line.startswith("//", i):
                was_comment_line = True
                if not strip_comments:
                    result += line[i:]
                i = len(line)
                continue
            result += line[i]
            i += 1
        if result.strip() == "":
            if was_comment_line and not in_block and idx == block_start_line:
                out.append((idx, ""))
            elif was_comment_line and block_start_line == idx:
                out.append((idx, ""))
            continue
        out.append((idx, result.rstrip()))
    return out


def _index_xml(project, cfg):
    out = []
    out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
    out.append(
        '<doxygenindex xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" '
        f'xsi:noNamespaceSchemaLocation="index.xsd" version="1.17.0" xml:lang="{XML_LANG}">\n'
    )
    sort_brief = cfg.get_bool("SORT_BRIEF_DOCS")
    for c in _sorted_compounds(project):
        out.append(f'  <compound refid="{xml_escape_attr(c.id)}" kind="{c.kind}"><name>{xml_escape(_display_name(c, cfg))}</name>\n')
        for _key, members in _group_sections(_MembersView(c), sort_brief=False) if False else _group_sections(c, sort_brief=False):
            for m in members:
                out.append(f'    <member refid="{xml_escape_attr(m.id)}" kind="{m.kind}"><name>{xml_escape(m.name)}</name></member>\n')
                for ev in m.enumvalues:
                    out.append(f'    <member refid="{xml_escape_attr(_enumvalue_id(m, ev))}" kind="enumvalue"><name>{xml_escape(ev.name)}</name></member>\n')
        out.append("  </compound>\n")
    out.append("</doxygenindex>\n")
    return "".join(out)


class _MembersView:
    def __init__(self, c):
        self.c = c


def _sorted_compounds(project):
    # The reference orders compounds in index.xml by kind groups and
    # then by name (case-insensitively) within a group.
    kind_order = {
        "class": 0, "struct": 1, "union": 2, "interface": 3,
        "protocol": 4, "category": 5, "exception": 6, "concept": 7,
        "namespace": 8, "module": 9, "file": 10, "page": 11,
        "group": 12, "dir": 13,
    }
    comps = list(project.compounds) + list(project.pages) + list(project.groups) + list(project.files) + list(project.dirs)
    return sorted(comps, key=lambda c: (kind_order.get(c.kind, 50), _display_name(c, project.cfg).lower(), _display_name(c, project.cfg)))


def generate_xml(project, output_dir, cfg, msg, warn):
    xml_dir = os.path.join(output_dir, cfg.get_string("XML_OUTPUT") or "xml")
    os.makedirs(xml_dir, exist_ok=True)
    ctx = RenderContext(project, cfg, warn)
    msg("Generating XML output...")
    # Static schema files.
    for name in ("combine.xslt", "compound.xsd", "doxyfile.xsd", "index.xsd", "xml.xsd"):
        write_output_file(os.path.join(xml_dir, name), resources.get_bytes("xml/" + name))
    write_output_file(os.path.join(xml_dir, "Doxyfile.xml"), cfg.write_doxyfile_xml(XM := "en-US"))
    write_output_file(os.path.join(xml_dir, "index.xml"), _index_xml(project, cfg))
    for c in list(project.compounds) + list(project.pages) + list(project.groups) + list(project.files) + list(project.dirs):
        msg(f"Generating XML output for {_kind_phrase(c)} {_display_name(c, cfg)}")
        write_output_file(os.path.join(xml_dir, c.id + ".xml"), _compound_xml(c, ctx))


def _kind_phrase(c):
    return {
        "class": "class", "struct": "struct", "union": "union",
        "interface": "interface", "namespace": "namespace",
        "file": "file", "page": "page", "group": "group",
        "dir": "directory", "concept": "concept", "module": "module",
    }.get(c.kind, c.kind)
