def _make_file_compound(project, ap, rel, display, cfg, basename_counts, cwd):
    fc = Compound("file", os.path.basename(display), os.path.basename(display))
    fc.abs_path = ap
    fc.rel_path = rel
    if basename_counts.get(os.path.basename(display), 0) > 1:
        fc.unique_path = display
    else:
        fc.unique_path = os.path.basename(display)
    fc.location.file = os.path.basename(display)
    return fc


def _make_dir_compounds(project, cfg, cwd):
    dirs = {}
    for fc in project.files:
        rel_dir = os.path.dirname(os.path.relpath(fc.abs_path, cwd)) if fc.abs_path else ""
        if rel_dir in ("", "."):
            continue
        parts = rel_dir.split(os.sep)
        for i in range(1, len(parts) + 1):
            name = "/".join(parts[:i])
            if name not in dirs:
                dc = Compound("dir", name, name)
                dc.abs_path = os.path.join(cwd, *parts[:i])
                dirs[name] = dc
                project.dirs.append(dc)
                if i > 1:
                    parent = dirs.get("/".join(parts[:i - 1]))
                    if parent is not None:
                        parent.inner.append(dc)
            if i == len(parts):
                dirs[name].inner.append(fc)
    # The reference lists directories in a nested-first order in some
    # outputs; keep discovery order here and sort in generators.
    return dirs


def _apply_standalone(project, standalone_all, warn):
    for structural, doc, comment in standalone_all:
        cmd, args = structural
        if cmd in ("class", "struct", "union", "interface", "namespace", "concept", "protocol", "category"):
            target_name = args.strip()
            comp = project.find_compound(target_name) or _find_by_short(project, target_name)
            if comp is not None:
                if comp.doc.empty():
                    comp.doc = doc
                else:
                    comp.doc.detailed.extend(doc.brief + doc.detailed)
            continue
        if cmd in ("page", "mainpage"):
            parts = args.split(None, 1) if cmd == "page" else []
            if cmd == "mainpage":
                pid = "index"
                title = args.strip()
            else:
                pid = parts[0] if parts else "page"
                title = parts[1].strip() if len(parts) > 1 else ""
            page = Compound("page", pid, pid)
            page.doc = doc
            page.page_title = title
            project.pages.append(page)
            if cmd == "mainpage":
                project.main_page = page
            continue
        if cmd in ("defgroup", "addtogroup", "weakgroup"):
            parts = args.split(None, 1)
            gid = parts[0] if parts else "group"
            title = parts[1].strip() if len(parts) > 1 else ""
            grp = next((g for g in project.groups if g.name == gid), None)
            if grp is None:
                grp = Compound("group", gid, gid)
                project.groups.append(grp)
            grp.page_title = title
            if grp.doc.empty():
                grp.doc = doc
            continue
        if cmd in ("fn", "var", "typedef", "enum"):
            # Attach to a member whose name appears in the signature.
            words = re.findall(r"[A-Za-z_][A-Za-z0-9_]*", args)
            target = None
            for w in reversed(words):
                for m in project.all_members:
                    if m.name == w:
                        target = m
                        break
                if target is not None:
                    break
            if target is not None and target.doc.empty():
                target.doc = doc
            continue


def _find_by_short(project, name):
    for c in project.compounds:
        if c.name == name or c.qualified.split("::")[-1] == name:
            return c
    return None


def _resolve_bases(project):
    for c in project.compounds:
        for base_name, _prot, _virt in c.bases:
            base = project.find_compound(base_name) or _find_by_short(project, base_name.split("<")[0].split("::")[-1])
            if base is not None and c not in base.derived:
                base.derived.append(c)


_KIND_WORDS = {
    "function": "function", "variable": "variable", "typedef": "typedef",
    "enum": "enumeration", "define": "macro definition", "friend": "friend",
}


def _postprocess(project, cfg, warn):
    # Group membership via \ingroup in docs.
    for m in project.all_members:
        for gid in m.doc.ingroups:
            grp = next((g for g in project.groups if g.name == gid), None)
            if grp is None:
                grp = Compound("group", gid, gid)
                project.groups.append(grp)
            if m not in grp.members:
                grp.members.append(m)
            m.group = grp
    for c in project.compounds:
        for gid in c.doc.ingroups:
            grp = next((g for g in project.groups if g.name == gid), None)
            if grp is not None and c not in grp.inner:
                grp.inner.append(c)

    if cfg.get_enum("WARN_AS_ERROR") == "YES":
        # Handled at return-code level; immediate stop is approximated.
        pass
    _warn_undocumented(project, cfg, warn)
    _warn_doc_errors(project, cfg, warn)


def _is_documented_member(m):
    return m.doc.has_doc and not m.doc.empty()


def _warn_undocumented(project, cfg, warn):
    if not cfg.get_bool("WARN_IF_UNDOCUMENTED"):
        return
    if cfg.get_bool("EXTRACT_ALL"):
        return
    # Parents in this order: files, then classes/namespaces.
    parents = []
    for f in project.files:
        if f.is_documented_file:
            parents.append(f)
    for c in project.compounds:
        if c.kind in ("class", "struct", "union", "interface", "namespace") and c.documented():
            parents.append(c)
    # Kind order for warnings (functions before variables in files).
    kind_key = {"define": 0, "typedef": 1, "enum": 2, "function": 3, "variable": 4}
    for parent in parents:
        members = sorted(parent.members, key=lambda m: (kind_key.get(m.kind, 9),))
        for m in members:
            if _is_documented_member(m):
                continue
            if m.kind == "enum":
                continue
            kind_word = _KIND_WORDS.get(m.kind, m.kind)
            if parent.kind == "file":
                loc = parent.name
                where = f"of file {loc}"
                absf = parent.abs_path or parent.name
            else:
                where = f"of {parent.kind} {parent.qualified}"
                absf = (project.files[0].abs_path if project.files else parent.name)
                # Prefer the member's own file path if known.
                for f in project.files:
                    if f.name == m.location.file:
                        absf = f.abs_path
                        break
            sig = m.name + (m.argsstring if m.kind == "function" else "")
            warn_format_file = absf
            text = f"Member {sig} ({kind_word}) {where} is not documented."
            warn(_format_warning(cfg, warn_format_file, m.location.line, text))


def _warn_doc_errors(project, cfg, warn):
    if not cfg.get_bool("WARN_IF_DOC_ERROR"):
        return
    for m in project.all_members:
        for blk in m.doc.detailed + m.doc.brief:
            if blk[0] == "paramlist" and blk[1] == "param":
                param_names = {p.get("declname") for p in m.params if p.get("declname")}
                for names, _desc in blk[2]:
                    for item in names:
                        nm = item[0] if isinstance(item, tuple) else item
                        if nm and param_names and nm not in param_names:
                            absf = m.file_compound.abs_path if m.file_compound else m.location.file
                            sig = f"{m.name}{m.argsstring}"
                            text = f"argument '{nm}' of command @param is not found in the argument list of {sig}"
                            warn(_format_warning(cfg, absf, m.location.line, text))
                        elif nm and not param_names and m.kind == "function":
                            absf = m.file_compound.abs_path if m.file_compound else m.location.file
                            sig = f"{m.name}{m.argsstring}"
                            text = f"argument '{nm}' of command @param is not found in the argument list of {sig}"
                            warn(_format_warning(cfg, absf, m.location.line, text))


def _format_warning(cfg, filename, line, text):
    fmt = "$file:$line: warning: $text\n"
    try:
        f = cfg.get_string("WARN_FORMAT")
        if f:
            fmt = f + "\n"
            # WARN_FORMAT customarily includes the warning text itself
            # without a trailing 'warning:' prefix handling; patterns
            # like "$file:$line: $text" are common - but the observed
            # default output includes "warning:" inside the format.
            # If the user format has no "warning", still we must not add.
            # The default format string is exactly the default below.
            if "$text" in f:
                return f.replace("$file", str(filename)).replace("$line", str(line)).replace("$text", "warning: " + text if "warning" not in f else text) + "\n" if False else _default_format(f, filename, line, text)
    except Exception:
        pass
    return _default_format(fmt, filename, line, text)


def _default_format(fmt, filename, line, text):
    # The stock WARN_FORMAT is "$file:$line: $text" and the reference
    # emits "$file:$line: warning: <text>".  That means $text itself is
    # prefixed by "warning: " in the standard handler.
    rendered = fmt.replace("$file", str(filename)).replace("$line", str(line)).replace("$text", text)
    if "warning:" not in rendered:
        rendered = rendered.replace(str(line) + ": ", str(line) + ": warning: ", 1) if False else f"{filename}:{line}: warning: {text}"
        return rendered + "\n"
    return rendered + "\n"


def _write_symbol_map(project, out_base, cfg):
    from .fileutil import write_output_file
    lines = []
    for m in project.all_members:
        lines.append(f"{m.qualified} {m.location.file} {m.location.line}\n")
    write_output_file(os.path.join(out_base, "symbols.sql"), "".join(lines))


