"""Top-level documentation generation pipeline."""

import fnmatch
import os
import re
import sys
import time

from . import cscan, xmlgen
from .config import VERSION_FULL
from .docparse import Doc
from .model import Compound, Project


class _Messenger:
    def __init__(self, quiet, debug_flags, start_time):
        self.quiet = quiet
        self.debug_flags = debug_flags or set()
        self.start_time = start_time

    def msg(self, text):
        if self.quiet:
            return
        prefix = ""
        if "time" in self.debug_flags:
            prefix = f"{time.monotonic() - self.start_time:.3f} sec: "
        stream = sys.stderr if "stderr" in self.debug_flags else sys.stdout
        stream.write(prefix + text + "\n")
        stream.flush()


class _Warner:
    def __init__(self, cfg):
        self.cfg = cfg
        self.count = 0
        self._fh = None
        self._to_stdout = False
        self._opened = False

    def open(self):
        self._opened = True
        logfile = ""
        try:
            logfile = self.cfg.get_string("WARN_LOGFILE")
        except Exception:
            pass
        if not logfile:
            return
        if logfile == "-":
            self._to_stdout = True
            return
        directory = os.path.dirname(logfile)
        if directory and not os.path.isdir(directory):
            try:
                os.mkdir(directory)
            except OSError:
                sys.stderr.write(
                    f"error: Cannot create directory for '{logfile}', "
                    "redirecting 'WARN_LOGFILE' output to 'stderr'\n"
                )
                return
        try:
            self._fh = open(logfile, "w", encoding="utf-8", errors="surrogateescape")
        except OSError:
            self._fh = None

    def warn(self, text):
        self.count += 1
        if self._fh is not None:
            self._fh.write(text)
            self._fh.flush()
        elif self._to_stdout:
            sys.stdout.write(text)
        else:
            sys.stderr.write(text)

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None


def _is_excluded(abs_path, rel_path, cfg, exclude_paths):
    for ex in exclude_paths:
        if abs_path == ex or abs_path.startswith(ex.rstrip("/") + "/"):
            return True
    try:
        patterns = cfg.get_list("EXCLUDE_PATTERNS")
    except Exception:
        patterns = []
    for pat in patterns:
        if (
            fnmatch.fnmatch(abs_path, pat)
            or fnmatch.fnmatch(rel_path, pat)
            or fnmatch.fnmatch(os.path.basename(abs_path), pat)
            or fnmatch.fnmatch("/" + rel_path, pat)
        ):
            return True
    return False


def _matches_patterns(name, patterns):
    if not patterns:
        return True
    for pat in patterns:
        if fnmatch.fnmatch(name, pat) or fnmatch.fnmatch(name.lower(), pat.lower()):
            return True
    return False


def _discover_inputs(cfg, msg, warn):
    cwd = os.getcwd()
    inputs = cfg.get_list("INPUT")
    explicit = bool(inputs)
    if not inputs:
        inputs = ["."]
    patterns = cfg.get_list("FILE_PATTERNS")
    recursive = cfg.get_bool("RECURSIVE")
    exclude_symlinks = cfg.get_bool("EXCLUDE_SYMLINKS")
    exclude_paths = []
    for e in cfg.get_list("EXCLUDE"):
        exclude_paths.append(os.path.abspath(os.path.join(cwd, e)))

    files = []
    seen = set()

    def add_file(abs_path):
        ap = os.path.normpath(abs_path)
        if ap in seen:
            return
        rel = os.path.relpath(ap, cwd)
        if _is_excluded(ap, rel, cfg, exclude_paths):
            return
        seen.add(ap)
        files.append(ap)

    def search_dir(dir_abs, display):
        msg(f"Searching for files in directory {display}")
        collected = []

        def recurse(cur):
            try:
                entries = list(os.scandir(cur))
            except OSError:
                return
            subdirs = []
            for entry in entries:
                ap = os.path.join(cur, entry.name)
                rel = os.path.relpath(ap, cwd)
                if entry.is_dir(follow_symlinks=True):
                    if recursive:
                        if exclude_symlinks and entry.is_symlink():
                            continue
                        if _is_excluded(ap, rel, cfg, exclude_paths):
                            continue
                        subdirs.append(entry)
                    continue
                if not entry.is_file(follow_symlinks=True):
                    continue
                if exclude_symlinks and entry.is_symlink():
                    continue
                if not _matches_patterns(entry.name, patterns):
                    continue
                if _is_excluded(ap, rel, cfg, exclude_paths):
                    continue
                collected.append(ap)
            for sd in subdirs:
                sub_display = os.path.join(display.rstrip("/"), os.path.relpath(sd.path, dir_abs))
                msg(f"Searching for files in directory {sub_display}")
                recurse(sd.path)

        recurse(dir_abs)
        for ap in sorted(collected):
            add_file(ap)

    for entry in inputs:
        abs_entry = os.path.abspath(os.path.join(cwd, entry))
        if os.path.isfile(abs_entry):
            add_file(abs_entry)
        elif os.path.isdir(abs_entry):
            if entry in (".", "./") and explicit:
                display = abs_entry + "/"
            else:
                display = abs_entry
            # Searching is announced; we sort collected files by path.
            _search_dir_with_sorted_files(abs_entry, display, msg, cfg,
                                          patterns, recursive,
                                          exclude_symlinks, exclude_paths, add_file, cwd)
        else:
            warn(f"warning: source '{entry}' is not a readable file or directory... skipping.\n")
    return files


def _search_dir_with_sorted_files(dir_abs, display, msg, cfg, patterns, recursive,
                                  exclude_symlinks, exclude_paths, add_file, cwd):
    collected = []

    def recurse(cur, disp):
        msg(f"Searching for files in directory {disp}")
        try:
            entries = list(os.scandir(cur))
        except OSError:
            return
        subdirs = []
        for entry in entries:
            ap = entry.path
            rel = os.path.relpath(ap, cwd)
            try:
                is_dir = entry.is_dir(follow_symlinks=True)
            except OSError:
                continue
            if is_dir:
                if recursive:
                    if exclude_symlinks and entry.is_symlink():
                        continue
                    if _is_excluded(ap, rel, cfg, exclude_paths):
                        continue
                    subdirs.append(entry)
                continue
            try:
                is_file = entry.is_file(follow_symlinks=True)
            except OSError:
                continue
            if not is_file:
                continue
            if exclude_symlinks and entry.is_symlink():
                continue
            if not _matches_patterns(entry.name, patterns):
                continue
            if _is_excluded(ap, rel, cfg, exclude_paths):
                continue
            collected.append(ap)
        for sd in subdirs:
            sub_display = os.path.join(disp.rstrip("/"), sd.name)
            recurse(sd.path, sub_display)

    recurse(dir_abs, display)
    for ap in sorted(collected):
        add_file(ap)


def _check_source_paths(cfg, warn, tag):
    try:
        entries = cfg.get_list(tag)
    except Exception:
        return
    for e in entries:
        if e and not os.path.exists(e):
            warn(f"warning: source '{e}' is not a readable file or directory... skipping.\n")


def _display_and_unique_paths(project_files, cfg, cwd):
    # file Compounds are built in scan loop; helper used before that
    pass


def _strip_from_path(abs_path, cfg, cwd):
    strips = cfg.get_list("STRIP_FROM_PATH")
    if not strips:
        strips = [cwd]
    result = abs_path
    best = ""
    for s in strips:
        sp = os.path.abspath(os.path.join(cwd, s)) if not os.path.isabs(s) else s
        if abs_path.startswith(sp) and len(sp) > len(best):
            best = sp
    if best:
        result = abs_path[len(best):].lstrip("/")
    return result or os.path.basename(abs_path)


def _language_for(path, cfg):
    ext = os.path.splitext(path)[1].lower()
    extmap = {}
    for item in cfg.get_list("EXTENSION_MAPPING"):
        if "=" in item:
            k, v = item.split("=", 1)
            k = k.strip().lower()
            if not k.startswith("."):
                k = "." + k
            extmap[k] = v.strip()
    if ext in extmap:
        lang = extmap[ext]
        low = lang.lower()
        if low in ("c", "c++", "cpp", "cxx"): return "C++"
        if low == "python": return "Python"
        if low == "java": return "Java"
        if low in ("c#", "csharp", "cs"): return "C#"
        if low == "php": return "PHP"
        if low == "objc": return "Objective-C"
        return lang
    if ext == ".py" or ext == ".pyw":
        return "Python"
    if ext == ".java":
        return "Java"
    if ext == ".cs":
        return "C#"
    if ext == ".php":
        return "PHP"
    if ext in (".m", ".mm"):
        return "Objective-C"
    if ext in (".f90", ".f95", ".f03", ".f08", ".f18", ".f", ".for"):
        return "Fortran"
    if ext in (".vhd", ".vhdl"):
        return "VHDL"
    if ext in (".md", ".markdown"):
        return "Markdown"
    return "C++"


def run_comment(cfg, comment_file, state):
    # -c: process the file as one documentation block to HTML.
    try:
        with open(comment_file, "r", encoding="utf-8", errors="surrogateescape") as fh:
            text = fh.read()
    except OSError:
        return 0
    from .docparse import DocParser
    from .htmlrender import doc_to_html_fragment
    from .model import Project
    from .render import RenderContext

    proj = Project(cfg)
    ctx = RenderContext(proj, cfg, _stderr_warn)
    doc = DocParser(cfg, _stderr_warn, comment_file, 1).parse(text, style="block")
    blocks = doc.brief + doc.detailed
    sys.stdout.write(doc_to_html_fragment(blocks, ctx))
    return 0


def _stderr_warn(text):
    sys.stderr.write(text)


def run_documentation(cfg, config_name, state):
    quiet = cfg.get_bool("QUIET")
    messenger = _Messenger(quiet, getattr(state, "debug_flags", set()), getattr(state, "started", time.monotonic()))
    msg = messenger.msg

    output_dir_value = cfg.get_string("OUTPUT_DIRECTORY")
    output_dir = output_dir_value if output_dir_value else ""
    msg(f"Doxygen version used: {VERSION_FULL}")
    if output_dir:
        if os.path.exists(output_dir):
            if not os.path.isdir(output_dir):
                sys.stderr.write(
                    f"error: tag OUTPUT_DIRECTORY: Output directory '{output_dir_value}' does not exist and cannot be created\n"
                )
                if not quiet:
                    sys.stdout.write("Exiting...\n")
                return 1
        else:
            try:
                os.mkdir(output_dir)
            except OSError:
                sys.stderr.write(
                    f"error: tag OUTPUT_DIRECTORY: Output directory '{output_dir_value}' does not exist and cannot be created\n"
                )
                if not quiet:
                    sys.stdout.write("Exiting...\n")
                return 1
    out_base = output_dir if output_dir else "."

    warner = _Warner(cfg)
    warner.open()
    warn = warner.warn

    try:
        return _run(cfg, config_name, state, messenger, warner, out_base)
    finally:
        warner.close()


def _run(cfg, config_name, state, messenger, warner, out_base):
    msg = messenger.msg
    warn = warner.warn
    cwd = os.getcwd()

    # Layout file (only existence is modelled initially).
    layout = cfg.get_string("LAYOUT_FILE")
    if layout and not os.path.exists(layout):
        warn(f"warning: failed to open layout file '{layout}' for reading! Using default settings.\n")

    msg("Searching for include files...")
    _check_source_paths(cfg, warn, "INCLUDE_PATH")
    msg("Searching for example files...")
    _check_source_paths(cfg, warn, "EXAMPLE_PATH")
    msg("Searching for images...")
    _check_source_paths(cfg, warn, "IMAGE_PATH")
    msg("Searching for dot files...")
    _check_source_paths(cfg, warn, "DOTFILE_DIRS")
    msg("Searching for msc files...")
    _check_source_paths(cfg, warn, "MSCFILE_DIRS")
    msg("Searching for dia files...")
    _check_source_paths(cfg, warn, "DIAFILE_DIRS")
    msg("Searching for plantuml files...")
    _check_source_paths(cfg, warn, "PLANTUMLFILE_DIRS")
    msg("Searching for files to exclude")
    msg("Searching INPUT for files to process...")
    input_files = _discover_inputs(cfg, msg, warn)

    project = Project(cfg)

    # Markdown/page files are not announced with Preprocessing lines.
    code_files = []
    md_files = []
    for ap in input_files:
        if os.path.splitext(ap)[1].lower() in (".md", ".markdown"):
            md_files.append(ap)
        else:
            code_files.append(ap)

    msg("Reading and parsing tag files")
    if not input_files:
        warn("warning: No files to be processed, please check your settings, in particular INPUT, FILE_PATTERNS, and RECURSIVE\n")
    # Tag files are only presence-checked at this stage (parsing them is
    # not yet implemented).
    for tf in cfg.get_list("TAGFILES"):
        tf_name = tf.split("=")[0].strip()
        if tf_name and not os.path.isfile(tf_name):
            warn(f"error: Tag file '{tf_name}' does not exist or is not a file. Skipping it...\n")

    msg("Parsing files")
    standalone_all = []

    # Build file compounds with display/unique names.
    file_infos = []
    for ap in code_files:
        rel = os.path.relpath(ap, cwd)
        if cfg.get_bool("FULL_PATH_NAMES"):
            display = _strip_from_path(ap, cfg, cwd)
        else:
            display = os.path.basename(ap)
        file_infos.append((ap, rel, display))
    # Unique paths for ids: basename unless duplicated.
    basename_counts = {}
    for _ap, _rel, disp in file_infos:
        basename_counts[os.path.basename(disp)] = basename_counts.get(os.path.basename(disp), 0) + 1

    enable_pp = cfg.get_bool("ENABLE_PREPROCESSING")
    for ap, rel, display in file_infos:
        if enable_pp:
            msg(f"Preprocessing {ap}...")
        msg(f"Parsing file {ap}...")
        fc = _make_file_compound(project, ap, rel, display, cfg, basename_counts, cwd)
        project.files.append(fc)
        try:
            with open(ap, "rb") as fh:
                data = fh.read()
            encoding = cfg.get_string("INPUT_ENCODING") or "UTF-8"
            try:
                source = data.decode(encoding, errors="surrogateescape")
            except (LookupError, UnicodeDecodeError):
                source = data.decode("utf-8", errors="surrogateescape")
        except OSError:
            source = ""
        fc.source = source
        lang = _language_for(ap, cfg)
        fc.language = lang if lang != "Markdown" else "C++"
        if lang == "Python":
            from . import pyscan
            standalone_all.extend(pyscan.scan_file(project, fc, source, warn) or [])
        else:
            standalone_all.extend(cscan.scan_file(project, fc, source, warn) or [])

    # Markdown / page files.
    from . import mdscan
    for ap in md_files:
        try:
            with open(ap, "r", encoding="utf-8", errors="surrogateescape") as fh:
                md_text = fh.read()
        except OSError:
            md_text = ""
        mdscan.scan_markdown(project, ap, md_text, warn)

    _make_dir_compounds(project, cfg, cwd)
    _apply_standalone(project, standalone_all, warn)
    _resolve_bases(project)
    _postprocess(project, cfg, warn)

    for phase in _PHASES_AFTER_PARSING:
        msg(phase)

    _generate(project, cfg, out_base, messenger, warner, state, config_name)

    if getattr(state, "dump_map", False):
        _write_symbol_map(project, out_base, cfg)

    # Cache statistics: approximated.
    if not messenger.quiet:
        used = len({m.qualified for m in project.all_members})
        hits = used if cfg.get_bool("GENERATE_XML") else 0
        sys.stdout.write("type lookup cache used 0/65536 hits=0 misses=0\n")
        sys.stdout.write(f"symbol lookup cache used {used}/65536 hits={hits} misses={used}\n")
        sys.stdout.write("finished...\n")

    warn_as_error = cfg.get_enum("WARN_AS_ERROR")
    if warn_as_error in ("FAIL_ON_WARNINGS", "FAIL_ON_WARNINGS_PRINT") and warner.count > 0:
        return 1
    return 0


