def inline_html(nodes, ctx):
    out = []
    for node in nodes:
        tag = node[0]
        if tag == "text":
            # autolink
            for is_ref, chunk, entity in ctx.autolink(node[1]):
                if is_ref and entity is not None:
                    href = _href_for(entity, ctx)
                    if href:
                        out.append(f'<a class="el" href="{html_escape(href)}">{html_escape(chunk)}</a>')
                    else:
                        out.append(html_escape(chunk))
                else:
                    out.append(html_escape(chunk))
        elif tag == "code":
            out.append(f"<code>{html_escape(node[1])}</code>")
        elif tag == "bold":
            out.append(f"<b>{inline_html(node[1], ctx)}</b>")
        elif tag == "emph":
            out.append(f"<em>{inline_html(node[1], ctx)}</em>")
        elif tag == "ref":
            target = node[1]
            entity = ctx.resolve(target)
            display = inline_html_plain(node[2], ctx) if len(node) > 2 and node[2] else html_escape(target)
            if entity is not None:
                href = _href_for(entity, ctx)
                out.append(f'<a class="el" href="{html_escape(href)}">{display}</a>')
            else:
                out.append(display)
        elif tag == "link":
            out.append(f'<a href="{html_escape(node[1])}">{inline_html(node[2], ctx)}</a>')
        elif tag == "break":
            out.append("<br/>")
    return "".join(out)


def inline_html_plain(nodes, ctx):
    out = []
    for node in nodes or []:
        if node[0] == "text":
            out.append(html_escape(node[1]))
        else:
            out.append(inline_html([node], ctx))
    return "".join(out)


def _href_for(entity, ctx):
    from .model import Compound, Member

    cfg = ctx.cfg
    ext = ".html"
    try:
        ext = cfg.get_string("HTML_FILE_EXTENSION") or ".html"
    except Exception:
        pass
    if isinstance(entity, Compound):
        return entity.id + ext
    if isinstance(entity, Member):
        p = entity.parent
        anchor = entity.id.split("_1a")[-1]
        base = p.id if p is not None else entity.anchor_base()
        return f"{base}{ext}#a{anchor}"
    return ""


_SIMPLESECT_TITLES = {
    "return": "Returns", "note": "Note", "warning": "Warning",
    "attention": "Attention", "author": "Author", "date": "Date",
    "version": "Version", "since": "Since", "pre": "Precondition",
    "post": "Postcondition", "invariant": "Invariant",
    "remark": "Remarks", "see": "See also", "todo": "Todo",
    "test": "Test", "bug": "Bug", "deprecated": "Deprecated",
    "satisfies": "Satisfies", "verifies": "Verifies",
}


def render_blocks_html(blocks, ctx):
    out = []
    for b in blocks:
        out.append(render_block_html(b, ctx))
    return "".join(out)


def render_block_html(block, ctx):
    tag = block[0]
    if tag == "para":
        return f"<p>{inline_html(block[1], ctx).strip()} </p>\n"
    if tag == "simplesect":
        kind = block[1]
        title = _SIMPLESECT_TITLES.get(kind, kind.capitalize())
        inner = render_blocks_html(block[2], ctx)
        if kind == "return":
            return f'<dl class="section return"><dt>Returns</dt><dd>{inner}</dd></dl>\n'
        return f'<dl class="section {kind}"><dt>{html_escape(title)}</dt><dd>{inner}</dd></dl>\n'
    if tag == "paramlist":
        kind = block[1]
        klass = "params" if kind == "param" else "retval" if kind == "retval" else "tparams" if kind == "templateparam" else "exception"
        title = {"param": "Parameters", "templateparam": "Template Parameters", "retval": "Return values", "exception": "Exceptions"}.get(kind, "Parameters")
        rows = []
        for names, desc in block[2]:
            nm = ", ".join(html_escape(str(x[0] if isinstance(x, tuple) else x)) for x in names)
            dtext = render_blocks_html(desc, ctx)
            # Strip <p> wrapper used for standalone fragments.
            dtext = re.sub(r"^<p>(.*)</p>\s*$", r"\1", dtext.strip(), flags=re.S)
            rows.append(f'<tr><td class="paramname">{nm}</td><td>{dtext}</td></tr>')
        return (
            f'<dl class="{klass}"><dt>{title}</dt><dd>'
            '<table class="' + klass + '">' + "".join(rows) + "</table></dd></dl>\n"
        )
    if tag in ("codeblock", "verbatim"):
        text = html_escape(block[1])
        return f'<div class="fragment"><pre>{text}</pre></div>\n'
    if tag == "list":
        listtag = "ol" if block[1] else "ul"
        items = "".join(f"<li>{render_blocks_html(i, ctx)}</li>" for i in block[2])
        return f"<{listtag}>{items}</{listtag}>\n"
    if tag == "sect":
        level = min(max(block[1], 1), 6)
        inner = render_blocks_html(block[4], ctx)
        return f"<h{level}>{inline_html(block[3], ctx)}</h{level}>\n{inner}"
    if tag == "heading":
        level = min(max(block[1], 1), 6)
        return f"<h{level}>{inline_html(block[3], ctx)}</h{level}>\n"
    if tag == "only":
        if block[1] is None or "html" in block[1]:
            return render_blocks_html(block[2], ctx)
        return ""
    if tag == "image":
        return f'<img src="{html_escape(block[2])}" alt=""/>\n'
    return ""
