def add_period_to_brief(doc):
    """A brief description that starts with an upper case letter is
    turned into a sentence by appending a period when it does not
    already end with sentence punctuation."""
    texts = []
    # Collect references to mutable para node lists.
    paras = []

    def collect(blocks):
        for b in blocks:
            if b[0] == "para":
                paras.append(b[1])
            elif b[0] == "sect":
                collect(b[4])

    collect(doc.brief)
    if not paras:
        return
    flat_text = ""
    for para in paras:
        for node in para:
            if node[0] == "text":
                flat_text += node[1]
            elif node[0] == "code":
                flat_text += node[1]
            elif node[0] in ("bold", "emph"):
                flat_text += "".join(x[1] for x in node[1] if x[0] == "text")
    stripped = flat_text.strip()
    if not stripped:
        return
    if not stripped[0].isupper():
        return
    if stripped[-1] in ".!?":
        return
    last_para = paras[-1]
    if last_para and last_para[-1][0] == "text":
        node = last_para[-1]
        last_para[-1] = ("text", node[1].rstrip() + ".")
    elif last_para:
        last_para.append(("text", "."))

