    """Return [(lineno, code)] for a file's program listing.

    Every source line is represented.  Documentation comments are
    removed when STRIP_CODE_COMMENTS is on; a contiguous run of
    documentation comment lines collapses into one empty line (the
    first line of the run).  Ordinary comments are kept as text."""
    lines = source.split("\n")
    # split() gives a final empty entry for a trailing newline; drop it.
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    i = 0
    n = len(lines)
    prev_was_doc_run = False
    while i < n:
        line = lines[i]
        lineno = i + 1
        # Skip a run of doc comments (blocks and line comments) possibly
        # separated only by whitespace.
        j = i
        run_end = None  # (line_index_after_run, remainder_on_last_line)
        is_doc_start = _doc_comment_starts(line)
        if strip_comments and is_doc_start:
            # Consume the whole run.
            k = i
            rem = ""
            while k < n:
                ln = lines[k]
                ds = _doc_comment_starts(ln)
                if ds == "line":
                    k += 1
                    # Consecutive line doc comments continue the run.
                    if k < n and _doc_comment_starts(lines[k]) == "line":
                        continue
                    break
                if ds == "block":
                    end, rem, last = _consume_block(lines, k)
                    k = last + 1
                    if rem.strip():
                        break
                    # Another doc comment following on next lines?
                    if k < n and _doc_comment_starts(lines[k]):
                        continue
                    break
                if ln.strip() == "" and k > i:
                    # Blank line inside/after a doc run ends it.
                    break
                break
            out.append((lineno, ""))
            if rem.strip():
                out.append((k, rem))  # k is 1-based line after increment == last+1 => line no = last+1
            i = k
            continue
        # Normal line: strip doc comments embedded in it if requested,
        # preserving ordinary comments as text unless they are doc.
        processed = _process_code_line_comments(line, strip_comments)
        # If the line opens a multi-line ordinary/doc block that is not
        # at its start, fall back to per-character handling below.
        out.append((lineno, processed.rstrip()))
        # Handle multi-line block comments that started in this line and
        # are not doc-at-line-start: consume following lines as comment
        # text lines (kept) or skip them for doc blocks.
        # Simplify: if an unterminated /* exists in the (original) line,
        # consume until */.
        if _unterminated_block_start(line) is not None:
            start_doc = _is_doc_block_start(line)
            k = i + 1
            while k < n:
                endln = lines[k]
                idx = endln.find("*/")
                if strip_comments and start_doc:
                    if idx != -1:
                        rem = endln[idx + 2:]
                        if rem.strip():
                            out.append((k + 1, rem.rstrip()))
                        k += 1
                        break
                    k += 1
                    continue
                out.append((k + 1, endln.rstrip()))
                k += 1
                if idx != -1:
                    break
            i = k
            continue
        i += 1
    return out


def _doc_comment_starts(line):
    s = line.lstrip()
    if s.startswith(("///", "//!")) and not s.startswith("////") and not s.startswith("//!!"):
        return "line"
    if (s.startswith("/**") and not s.startswith("/***")) or s.startswith("/*!"):
        return "block"
    return None


def _is_doc_block_start(line):
    idx = line.find("/**")
    q = line.find("/*!")
    return idx != -1 or q != -1


def _unterminated_block_start(line):
    idx = line.find("/*")
    while idx != -1:
        end = line.find("*/", idx + 2)
        if end == -1:
            return idx
        idx = line.find("/*", end + 2)
    return None


def _consume_block(lines, start_idx):
    """Consume a block comment starting in lines[start_idx]; returns
    (end_index_in_line, remainder, last_line_index)."""
    first = lines[start_idx]
    pos = first.find("/*")
    end = first.find("*/", pos + 2)
    if end != -1:
        return end, first[end + 2:], start_idx
    k = start_idx + 1
    while k < len(lines):
        end = lines[k].find("*/")
        if end != -1:
            return end, lines[k][end + 2:], k
        k += 1
    return -1, "", len(lines) - 1


def _process_code_line_comments(line, strip_comments):
    if not strip_comments:
        return line
    out = ""
    i = 0
    while i < len(line):
        if line.startswith("/*", i):
            is_doc = line.startswith(("/**", "/*!"), i)
            end = line.find("*/", i + 2)
            if end == -1:
                return out if is_doc else out + line[i:]
            if is_doc:
                i = end + 2
                continue
            out += line[i:end + 2]
            i = end + 2
            continue
        if line.startswith("//", i):
            is_doc = line.startswith(("///", "//!"), i)
            if is_doc:
                return out
            out += line[i:]
            return out
        out += line[i]
        i += 1
    return out


