"""Python source scanner (based on the stdlib ``ast`` parser plus
comment tokenisation for Doxygen-style ``##`` comments)."""

import ast
import io
import os
import re
import tokenize

from .docparse import Doc, DocParser
from .model import Compound, Location, Member


def _infer_type(node, source):
    if node is None:
        return ""
    if isinstance(node, ast.Constant):
        v = node.value
        if isinstance(v, bool):
            return "bool"
        if isinstance(v, int):
            return "int"
        if isinstance(v, float):
            return "float"
        if isinstance(v, str):
            return "str"
        if isinstance(v, bytes):
            return "bytes"
        if v is None:
            return ""
        return type(v).__name__
    if isinstance(node, ast.List):
        return "list"
    if isinstance(node, ast.Tuple):
        return "tuple"
    if isinstance(node, ast.Dict):
        return "dict"
    if isinstance(node, ast.Set):
        return "set"
    if isinstance(node, ast.Call):
        f = node.func
        if isinstance(f, ast.Name):
            return f.id
        if isinstance(f, ast.Attribute):
            seg = ast.get_source_segment(source, f)
            return seg or ""
    return ""


class _CommentGroup:
    def __init__(self, start, end, lines, indent):
        self.start = start
        self.end = end
        self.lines = lines
        self.indent = indent
        self.used = False


class _PyScanner:
    def __init__(self, project, file_compound, source, warn):
        self.project = project
        self.file = file_compound
        self.cfg = project.cfg
        self.source = source
        self.warn = warn
        self.lines = source.split("\n")
        self.module_name = os.path.splitext(file_compound.name)[0]
        if file_compound.name == "__init__.py":
            # package name is the directory name
            rel = file_compound.rel_path or ""
            parts = rel.replace(os.sep, "/").split("/")
            self.module_name = parts[-2] if len(parts) >= 2 else self.module_name
        self.comments = self._collect_comments()
        self.standalone = []

    # -- comments ------------------------------------------------------
    def _collect_comments(self):
        groups = []
        raw = []
        try:
            tokens = tokenize.generate_tokens(io.StringIO(self.source).readline)
            for tok in tokens:
                if tok.type == tokenize.COMMENT:
                    raw.append((tok.start[0], tok.start[1], tok.string))
        except Exception:
            for i, line in enumerate(self.lines, 1):
                s = line.lstrip()
                if s.startswith("#"):
                    raw.append((i, len(line) - len(s), s))
        i = 0
        while i < len(raw):
            lineno, col, text = raw[i]
            if not (text.startswith("##") and not text.startswith("###")):
                i += 1
                continue
            # A doxygen comment block: this line plus immediately
            # following comment lines at the same column.
            glines = [self._comment_content(text, first=True)]
            end = lineno
            j = i + 1
            while j < len(raw):
                l2, c2, t2 = raw[j]
                if l2 != end + 1 or c2 != col:
                    break
                glines.append(self._comment_content(t2))
                end = l2
                j += 1
            trailing = glines and False
            groups.append(_CommentGroup(lineno, end, glines, col))
            i = j
        return groups

    @staticmethod
    def _comment_content(text, first=False):
        if text.startswith("##"):
            s = text[2:]
        else:
            s = text[1:]
        if s.startswith(" "):
            s = s[1:]
        return s

    def _doc_for(self, node):
        """Find a comment group immediately preceding node (allowing the
        node's decorator lines)."""
        start = node.lineno
        if getattr(node, "decorator_list", None):
            start = min([d.lineno for d in node.decorator_list] + [start])
        best = None
        for g in self.comments:
            if g.used:
                continue
            if g.end < start:
                best = g
            else:
                break
        if best is not None:
            best.used = True
            parser = DocParser(self.cfg, self.warn,
                               self.file.rel_path or self.file.name, best.start)
            return parser.parse("\n".join(best.lines), style="line")
        return Doc()

    def _docstring_doc(self, node):
        if self.cfg is not None and not self.cfg.get_bool("PYTHON_DOCSTRING"):
            return Doc()
        try:
            ds_node = node.body[0] if getattr(node, "body", None) else None
        except Exception:
            ds_node = None
        is_ds = (
            isinstance(ds_node, ast.Expr)
            and isinstance(ds_node.value, ast.Constant)
            and isinstance(ds_node.value.value, str)
        )
        if not is_ds:
            return Doc()
        seg = ast.get_source_segment(self.source, ds_node) or ""
        text = ast.get_docstring(node, clean=True) or ""
        # Doxygen-style docstring starts with """! or '''!
        stripped = seg.lstrip()
        if stripped.startswith(('"""!', "'''!")):
            parser = DocParser(self.cfg, self.warn,
                               self.file.rel_path or self.file.name, ds_node.lineno)
            return parser.parse(text, style="block")
        doc = Doc()
        doc.has_doc = True
        doc.detailed = [("verbatimpara", text)]
        return doc

    # -- structure --------------------------------------------------------
    def scan(self):
        try:
            tree = ast.parse(self.source)
        except SyntaxError:
            return []
        module = Compound("namespace", self.module_name, self.module_name)
        module.language = "Python"
        module.file_compound = self.file
        module.location = Location(self.file.name, 1, 1)
        module.doc = self._docstring_doc(tree)
        if not module.doc.has_doc:
            module.doc = self._doc_for(tree) if False else module.doc
        self.project.compounds.append(module)
        self.file.inner.append(module)
        self._process_body(tree.body, module, module, is_module=True)
        return self.standalone

    def _process_body(self, body, owner, namespace, is_module=False, in_class=None, in_function=None):
        for node in body:
            if isinstance(node, ast.ClassDef):
                self._process_class(node, owner, namespace)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                self._process_function(node, owner, namespace, in_class)
            elif isinstance(node, ast.Assign):
                # Attributes assigned on self inside a method.
                if in_function is not None and in_class is not None:
                    for target in node.targets:
                        if isinstance(target, ast.Attribute) and isinstance(target.value, ast.Name) and target.value.id in ("self", "cls"):
                            self._make_variable(target.attr, node, in_class, namespace,
                                                is_static=False, in_function=in_function)
                    # Recurse is not needed.
                elif is_module or in_class is not None:
                    for target in node.targets:
                        self._targets_to_variables(target, node, owner, namespace, in_class)
            elif isinstance(node, ast.AnnAssign):
                if is_module or in_class is not None:
                    t = node.target
                    if isinstance(t, ast.Name):
                        self._make_variable(t.id, node, owner, namespace,
                                            is_static=(in_class is not None), ann=node.annotation, in_class=in_class)
                    elif isinstance(t, ast.Attribute) and in_class is not None:
                        self._make_variable(t.attr, node, in_class, namespace, is_static=False, in_class=in_class)
            elif isinstance(node, (ast.If, ast.Try)):
                inner = list(getattr(node, "body", [])) + list(getattr(node, "orelse", []))
                for h in getattr(node, "handlers", []):
                    inner += list(h.body)
                self._process_body(inner, owner, namespace, is_module, in_class, in_function)

    def _targets_to_variables(self, target, node, owner, namespace, in_class):
        if isinstance(target, ast.Name):
            self._make_variable(target.id, node, owner, namespace,
                                is_static=(in_class is not None), in_class=in_class)
        elif isinstance(target, (ast.Tuple, ast.List)):
            for elt in target.elts:
                self._targets_to_variables(elt, node, owner, namespace, in_class)

    def _prot_for(self, name):
        if name.startswith("__") and not name.endswith("__"):
            return "private"
        if name.startswith("_"):
            return "protected"
        return "public"

    def _body_end(self, node, body_list_context=None):
        # End line = the line before the next sibling statement handled
        # by callers through _fix_body_ends after processing a body is
        # approximated here by the node's own end line.
        return getattr(node, "end_lineno", node.lineno)

    def _make_variable(self, name, node, owner, namespace, is_static=False, ann=None, in_class=None, in_function=None):
        parent = in_class if in_class is not None else owner
        # Existing instance variable? update instead of duplicate.
        for ex in parent.members:
            if ex.kind == "variable" and ex.name == name:
                return ex
        m = Member("variable", name)
        m.static = bool(is_static)
        m.prot = self._prot_for(name) if in_class is not None else "public"
        value_node = getattr(node, "value", None)
        if ann is not None:
            m.type = ast.get_source_segment(self.source, ann) or ""
        else:
            m.type = _infer_type(value_node, self.source) if not (in_function is not None and isinstance(value_node, ast.Name)) else ""
        if value_node is not None:
            vtext = ast.get_source_segment(self.source, value_node) or ""
            m.initializer = "=  " + vtext
        m.location = Location(self.file.name, node.lineno, 1)
        m.location.body_file = self.file.name
        m.location.body_start = node.lineno
        m.location.body_end = -1
        # DOC: preceding ## comment.
        doc = self._doc_for(node)
        if doc.has_doc:
            m.doc = doc
        # qualified dotted form
        if in_class is not None:
            m.qualified = in_class.qualified.replace("::", ".") + "." + name
            qual_def = in_class.qualified.replace("::", ".")
            if m.type:
                m.definition = f"{m.type} {qual_def}::{name}"
            else:
                m.definition = f"{qual_def}::{name}"
        else:
            m.qualified = self.module_name + "." + name
            if m.type:
                m.definition = f"{m.type} {m.qualified}"
            else:
                m.definition = m.qualified
        m.parent = parent
        m.file_compound = self.file
        parent.members.append(m)
        self.project.all_members.append(m)
        return m

    def _process_class(self, node, owner, namespace):
        if isinstance(owner, Compound) and owner.kind == "namespace":
            qual = owner.qualified + "::" + node.name
            parent = owner
        elif isinstance(owner, Compound) and owner.kind in ("class", "struct"):
            qual = owner.qualified + "::" + node.name
            parent = owner
        else:
            parent = namespace
            qual = namespace.qualified + "::" + node.name
        comp = Compound("class", node.name, qual)
        comp.language = "Python"
        comp.file_compound = self.file
        comp.inc_file = self.file.name
        comp.parent = parent
        comp.location = Location(self.file.name, node.lineno, 1)
        comp.location.body_file = self.file.name
        comp.location.body_start = node.lineno
        comp.location.body_end = self._sibling_end(node)
        for b in node.bases:
            bname = ast.get_source_segment(self.source, b) or ""
            if bname:
                comp.bases.append((bname, "public", "non-virtual"))
        doc = self._doc_for(node)
        ds = self._docstring_doc(node)
        if ds.has_doc:
            comp.doc = ds
        if doc.has_doc:
            if comp.doc.empty():
                comp.doc = doc
            else:
                comp.doc.brief = comp.doc.brief or doc.brief
                comp.doc.detailed = doc.detailed + comp.doc.detailed
        self.project.compounds.append(comp)
        if parent is not None:
            parent.inner.append(comp)
        self.file.inner.append(comp)
        self._process_body(node.body, comp, namespace, is_module=False, in_class=comp)

    def _sibling_end(self, node):
        # Body end: we approximate with the last line of the node plus
        # any trailing blank lines up to the next top-level statement,
        # handled by _process_body post-adjustment in scan via stored
        # node ordering.  ast end_lineno is a good first approximation;
        # a follow-up pass (_adjust_body_ends) refines it.
        self._pending_ends = getattr(self, "_pending_ends", [])
        self._pending_ends.append(node)
        return getattr(node, "end_lineno", node.lineno)

    def _process_function(self, node, owner, namespace, in_class):
        name = node.name
        m = Member("function", name)
        m.prot = self._prot_for(name) if in_class is not None else "public"
        # decorators
        decos = []
        for d in node.decorator_list:
            seg = ast.get_source_segment(self.source, d) or ""
            decos.append(seg.split(".")[-1])
        if "staticmethod" in decos or "classmethod" in decos:
            m.static = True
        if "property" in decos:
            m.kind = "property"
        # Return annotation
        if node.returns is not None:
            m.type = ast.get_source_segment(self.source, node.returns) or ""
        # Arguments argstring from source
        m.argsstring = self._args_string(node)
        m.params = self._params(node)
        m.location = Location(self.file.name, node.lineno, 1)
        m.location.body_file = self.file.name
        m.location.body_start = node.lineno
        m.location.body_end = getattr(node, "end_lineno", node.lineno)
        doc = self._doc_for(node)
        ds = self._docstring_doc(node)
        if ds.has_doc:
            m.doc = ds
        if doc.has_doc:
            if m.doc.empty():
                m.doc = doc
            else:
                # Doxygen comments take precedence as the real docs;
                # docstring becomes detailed content in that case in the
                # reference too (they are normally not combined).  Keep
                # the comment docs.
                m.doc = doc
        parent = in_class if in_class is not None else namespace
        if in_class is not None:
            dotted = in_class.qualified.replace("::", ".")
            m.qualified = dotted + "." + name
            if m.type:
                m.definition = f"{m.type} {m.qualified}"
            else:
                m.definition = m.qualified
        else:
            m.qualified = self.module_name + "." + name
            if m.type:
                m.definition = f"{m.type} {name}"
            else:
                m.definition = name
        m.parent = parent
        m.file_compound = self.file
        parent.members.append(m)
        self.project.all_members.append(m)
        # Process self.x assignments inside this function as attributes.
        if in_class is not None:
            self._process_body(node.body, parent, namespace, is_module=False, in_class=in_class, in_function=m)
        else:
            # Nested functions are picked up as (local) functions if documented?
            for sub in node.body:
                if isinstance(sub, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    self._process_function(sub, owner, namespace, in_class)
                elif isinstance(sub, ast.ClassDef):
                    self._process_class(sub, owner, namespace)

    def _args_string(self, node):
        src_lines = self.lines[node.lineno - 1: (node.body[0].lineno if node.body else node.lineno + 1)]
        text = " ".join(l.strip() for l in src_lines) if src_lines else ""
        m = re.search(r"\((.*)\)\s*(?:->[^:]*)?:?\s*$", text, re.S)
        if m:
            inner = re.sub(r"\s+", " ", m.group(1)).strip()
            return "(" + inner + ")"
        # Fallback from AST
        parts = []
        for a in node.args.posonlyargs + node.args.args:
            parts.append(a.arg)
        return "(" + ", ".join(parts) + ")"

    def _params(self, node):
        args = node.args
        params = []
        positional = list(args.posonlyargs) + list(args.args)
        defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
        for a, dflt in zip(positional, defaults):
            if a.annotation is not None:
                typ = ast.get_source_segment(self.source, a.annotation) or ""
            else:
                typ = a.arg
            params.append({
                "type": typ,
                "declname": None,
                "defname": a.arg,
                "defval": (ast.get_source_segment(self.source, dflt) if dflt is not None else None),
            })
        if args.vararg is not None:
            params.append({"type": "*args", "declname": None, "defname": args.vararg.arg, "defval": None})
        for a, dflt in zip(args.kwonlyargs, args.kw_defaults):
            typ = ast.get_source_segment(self.source, a.annotation) if a.annotation is not None else a.arg
            params.append({
                "type": typ or a.arg, "declname": None, "defname": a.arg,
                "defval": (ast.get_source_segment(self.source, dflt) if dflt is not None else None),
            })
        if args.kwarg is not None:
            params.append({"type": "**kwargs", "declname": None, "defname": args.kwarg.arg, "defval": None})
        return params


def _fix_body_ends(source, project_nodes):
    pass


def scan_file(project, file_compound, source, warn):
    scanner = _PyScanner(project, file_compound, source, warn)
    std = scanner.scan()
    # Refine body ends: a class/function body ends on the line before the
    # next entity at the same or lower scope.  Approximated by looking at
    # the sorted list of entity start lines in the same file.
    starts = []
    for c in project.compounds:
        if c.file_compound is file_compound:
            starts.append((c.location.line, c))
    funcs = [m for m in project.all_members if m.file_compound is file_compound and m.kind in ("function", "property")]
    all_starts = sorted(set([s for s, _ in starts] + [m.location.line for m in funcs]))
    nlines = len(source.split("\n"))
    for m in funcs:
        later = [s for s in all_starts if s > m.location.line]
        if later:
            m.location.body_end = later[0] - 1
        else:
            m.location.body_end = nlines
    for s, c in starts:
        later = [x for x in all_starts if x > s]
        # A class ends before the next top-level entity; inner members are
        # not a reliable bound.  Use the next compound start at module level.
        comp_later = [x for x, cc in starts if x > s]
        func_later = [m.location.line for m in funcs if m.location.line > s and m.parent is not c]
        bounds = comp_later + func_later
        if bounds:
            c.location.body_end = min(bounds) - 1
    return std
