    if not type_text:
        return ""
    out = []
    pos = 0
    for match in re.finditer(r"[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*", type_text):
        word = match.group(0)
