        out.append(html_escape(type_text[pos:match.start()]).replace(" ", "&#160;"))
        if isinstance(ent, Compound) and ent.kind in ("class", "struct", "union", "interface", "concept") and gen.compound_visible(ent):
            out.append(f'<a class="el" href="{html_escape(ent.id + gen.ext)}">{html_escape(word)}</a>')
        else:
            out.append(html_escape(word))
        pos = match.end()
    out.append(html_escape(type_text[pos:]).replace(" ", "&#160;"))
    # Pointer etc spacing is already in type text
    return "".join(out)


def _decl_type_html(gen, m):
    if not m.type:
        left = ""
    else:
        left = _type_html(gen, m.type)
    if m.kind == "typedef":
        left = "typedef " + left
        return html_escape("typedef ")[:-1] + " " + _type_html(gen, m.type) if False else _type_html(gen, "typedef " + m.type)
    return left


