    hue, sat, gamma = cfg.get_int("HTML_COLORSTYLE_HUE"), cfg.get_int("HTML_COLORSTYLE_SAT"), cfg.get_int("HTML_COLORSTYLE_GAMMA")

    def style_variant(name, default_name=None):
