    def put(name, content):
        if isinstance(content, str):
            content = content.encode("utf-8")
        write_output_file(os.path.join(out, name), content)

    dynamic_menus = gen.b("HTML_DYNAMIC_MENUS") and not gen.b("GENERATE_HTMLHELP")
