    else:
        put("doxygen.css", cssgen.generate_css(cfg))
    for item in cfg.get_list("HTML_EXTRA_STYLESHEET"):
        try:
            with open(item, "rb") as fh:
                put(os.path.basename(item), fh.read())
        except OSError:
            gen.warn(f"error: Style sheet '{item}' specified by HTML_EXTRA_STYLESHEET does not exist!\n")
    put("tabs.css", tabs)
    if not gen.b("GENERATE_HTMLHELP"):
        put("dynsections.js", dyn)
