        put("darkmode_toggle.js", resources.get_bytes("html_res/darkmode_toggle.js"))
    # Search resources are written with search indices later.
    # Project logo/icon and extra files.
    for tag, what in (("PROJECT_LOGO", "logo"), ("PROJECT_ICON", "icon")):
