    if mode == "TOGGLE":
        put("darkmode_toggle.js", resources.get_bytes("html_res/darkmode_toggle.js"))
    # Search resources are written with search indices later.
    # Project logo/icon and extra files.
    for tag, what in (("PROJECT_LOGO", "logo"), ("PROJECT_ICON", "icon")):
        val = gen.s(tag)
        if val:
            try:
                with open(val, "rb") as fh:
                    put(os.path.basename(val), fh.read())
            except OSError:
                gen.warn(f"error: Project {what} '{val}' specified by {tag} does not exist!\n")
    for item in cfg.get_list("HTML_EXTRA_FILES"):
