def _header_block(gen, title):
    return '<div class="header">\n  <div class="headertitle"><div class="title">' + html_escape(title) + "</div></div>\n</div><!--header-->\n"


def _top_summary(gen, entity):
    brief = entity.doc.brief
    if not brief:
        return ""
    html = render_blocks_html(brief, gen.ctx)
    # Summary is a single <p> with two trailing spaces plus More link.
    # Extract first paragraph content.
    m = re.match(r"<p>(.*?)</p>", html.strip(), re.S)
    inner = m.group(1).rstrip() if m else html.strip()
    has_more = bool(gen._detailed_blocks(entity)) or bool(entity.doc.detailed)
    out = f"\n<p>{inner}  \n"
    if has_more:
        out += '<a href="#details">More...</a></p>\n'
    else:
        out += "</p>\n"
    return out


def _member_sections_html(gen, compound):
    """Sections for the member declaration tables of a compound."""
    members = _decl_members(gen, compound)
    if compound.kind in ("class", "struct", "union", "interface"):
        return _class_sections(gen, compound, members)
    return _file_sections(gen, compound, members)


def _decl_members(gen, compound):
    if compound.kind == "file":
        result = list(compound.members)
        # Add members defined in this file that live in hidden namespaces.
        for m in gen.project.all_members:
            if m.file_compound is compound and m.parent is not compound:
                p = m.parent
                if p is not None and p.kind == "namespace" and not gen.compound_visible(p):
                    if m not in result:
                        result.append(m)
        return [m for m in result if gen.member_visible(m)]
    return gen.visible_members(compound)


# Section metadata: key -> (anchor, title, doc-anchor, doc-title)
_CLASS_SECTIONS = [
    ("public-types", "pub-types", "Public Types", "pub-types", "Member Type Documentation"),
    ("public-methods", "pub-methods", "Public Member Functions", "doc-func-members", "Member Function Documentation"),
    ("public-static-methods", "pub-static-methods", "Static Public Member Functions", "doc-func-members", "Member Function Documentation"),
    ("public-attributes", "pub-attribs", "Public Attributes", "doc-variable-members", "Member Data Documentation"),
    ("public-static-attributes", "pub-static-attribs", "Static Public Attributes", "doc-variable-members", "Member Data Documentation"),
    ("protected-types", "pro-types", "Protected Types", "pro-types", "Member Type Documentation"),
    ("protected-methods", "pro-methods", "Protected Member Functions", "doc-func-members", "Member Function Documentation"),
    ("protected-static-methods", "pro-static-methods", "Static Protected Member Functions", "doc-func-members", "Member Function Documentation"),
    ("protected-attributes", "pro-attribs", "Protected Attributes", "doc-variable-members", "Member Data Documentation"),
    ("protected-static-attributes", "pro-static-attribs", "Static Protected Attributes", "doc-variable-members", "Member Data Documentation"),
    ("private-types", "pri-types", "Private Types", "pri-types", "Member Type Documentation"),
    ("private-methods", "pri-methods", "Private Member Functions", "doc-func-members", "Member Function Documentation"),
    ("private-static-methods", "pri-static-methods", "Static Private Member Functions", "doc-func-members", "Member Function Documentation"),
    ("private-attributes", "pri-attribs", "Private Attributes", "doc-variable-members", "Member Data Documentation"),
