def _class_section_key(m):
    prot = m.prot
    if m.kind == "friend":
        return "friends"
    if m.kind in ("typedef", "enum"):
        return f"{prot}-types"
    if m.kind == "function":
        return f"{prot}-static-methods" if m.static else f"{prot}-methods"
    if m.kind == "variable":
        return f"{prot}-static-attributes" if m.static else f"{prot}-attributes"
    return f"{prot}-methods"


def _class_sections(gen, compound, members):
    grouped = {}
    for m in members:
        grouped.setdefault(_class_section_key(m), []).append(m)
    out_secs = []
    for key, anchor, title, doc_anchor, doc_title in _CLASS_SECTIONS:
        if key in grouped:
            out_secs.append((key, anchor, title, doc_anchor, doc_title, grouped[key]))
    return out_secs


_FILE_SECTIONS = [
    ("classes", "nested-classes", "Classes", None, None),
    ("namespaces", "namespaces", "Namespaces", None, None),
    ("defines", "define-members", "Macros", "doc-define-members", "Macro Definition Documentation"),
    ("typedefs", "typedef-members", "Typedefs", "doc-typedef-members", "Typedef Documentation"),
    ("enums", "enum-members", "Enumerations", "doc-enum-members", "Enumeration Type Documentation"),
    ("functions", "func-members", "Functions", "doc-func-members", "Function Documentation"),
    ("variables", "var-members", "Variables", "doc-var-members", "Variable Documentation"),
]


def _file_section_key(m):
    return {"define": "defines", "typedef": "typedefs", "enum": "enums",
            "function": "functions", "variable": "variables",
            "friend": "functions"}.get(m.kind, "functions")


def _file_sections(gen, compound, members):
    grouped = {}
    for m in members:
        grouped.setdefault(_file_section_key(m), []).append(m)
    out_secs = []
    # Inner classes of this file (visible ones).
    inners = [c for c in gen.project.compounds
              if c.file_compound is compound and c.kind in ("class", "struct", "union", "interface") and gen.compound_visible(c)]
    if inners:
        out_secs.append(("classes", "nested-classes", "Classes", None, None, inners))
    nss = [c for c in gen.project.compounds
           if c.file_compound is compound and c.kind == "namespace" and gen.compound_visible(c)]
    if nss and compound.kind == "file":
        out_secs.append(("namespaces", "namespaces", "Namespaces", None, None, nss))
    for key, anchor, title, doc_anchor, doc_title in _FILE_SECTIONS:
        if key in ("classes", "namespaces"):
            continue
        if key in grouped:
            out_secs.append((key, anchor, title, doc_anchor, doc_title, grouped[key]))
    return out_secs


def _section_table(gen, compound, secs):
    out = []
    for key, anchor, title, doc_anchor, doc_title, members in secs:
        out.append('<table class="memberdecls">\n')
        out.append(f'<tr class="heading"><td colspan="2"><h2 id="header-{anchor}" class="groupheader"><a id="{anchor}" name="{anchor}"></a>\n')
        out.append(f"{html_escape(title)}</h2></td></tr>\n")
        for m in members:
            out.append(_decl_row(gen, compound, m))
        out.append("</table>")
    return "".join(out)


def _decl_row(gen, compound, m):
    if isinstance(m, Compound):
        return _compound_decl_row(gen, m)
    anchor = _anchor(m)
    has_detail = gen.has_detail(m) or (m.kind == "enum" and any(ev.doc.has_doc and not ev.doc.empty() for ev in m.enumvalues))
    out = []
    out.append(f'<tr class="memitem:{anchor}" id="r_{anchor}">')
    # Left cell
    left = ""
    if not has_detail:
        left += f'<a id="{anchor}" name="{anchor}"></a>\n'
    left += _left_cell(gen, m)
    out.append(f'<td class="memItemLeft">{left}</td>')
    # Right cell
    right = _right_cell(gen, compound, m, has_detail)
    out.append(f'<td class="memItemRight">{right}</td></tr>\n')
    # Brief description row
    if gen.b("BRIEF_MEMBER_DESC"):
        brief = gen._brief_html(m)
        if brief:
            more = ""
            if has_detail:
                href = f"#{anchor}" if True else ""
                more = f' <a href="{href}">More...</a>'
            out.append(f'<tr class="memdesc:{anchor}"><td class="mdescLeft">&#160;</td><td class="mdescRight">{brief} {more}<br /></td></tr>\n')
    return "".join(out)


def _left_cell(gen, m):
    if m.kind == "define":
        return "#define&#160;"
    if m.kind == "enum":
        return ("enum class &#160;" if m.strong else "enum &#160;")
    if m.kind == "typedef":
        return _type_html(gen, "typedef " + (m.type or "")) + "&#160;" if False else _escape_nb(_type_html(gen, "typedef " + (m.type or "")))
    if m.kind in ("function", "friend"):
        t = m.type
        if m.static and m.parent is not None and m.parent.kind in ("class", "struct"):
            # Static appears as part of type cell in doxygen for members?
            pass
        return (_type_html(gen, t) + "&#160;") if t else "&#160;"
    if m.kind == "variable":
        return (_type_html(gen, m.type) + "&#160;") if m.type else "&#160;"
    return "&#160;"


def _escape_nb(html):
    # Replace spaces outside tags with &#160; in left cells.
    parts = re.split(r"(<[^>]+>)", html)
    return "".join(p if p.startswith("<") else p.replace(" ", "&#160;") for p in parts)


def _right_cell(gen, compound, m, has_detail):
    anchor = _anchor(m)
    parent = m.parent
    in_file = compound.kind == "file"
    # Display name: qualified if the compound page is not the parent.
    display = m.name
    if parent is not None and parent is not compound and parent.kind == "namespace":
        display = parent.qualified + "::" + m.name if parent.language != "Python" else parent.qualified.replace("::", ".") + "." + m.name
        # Namespace members shown on a file page use C++ :: in samples.
        if in_file and parent.language != "Python":
            display = parent.qualified + "::" + m.name
    if has_detail:
        name_html = f'<a class="el" href="#{anchor}">{html_escape(display)}</a>'
    else:
        name_html = f"<b>{html_escape(display)}</b>"
    if m.kind == "function" or m.kind == "friend":
        return f"{name_html} {html_escape(m.argsstring)}" if m.argsstring else name_html
    if m.kind == "define":
        init = ""
        if m.params:
            init = "(" + ", ".join(p.get("declname") or "" for p in m.params) + ")"
        if m.initializer:
            init += "&#160;&#160;&#160;" + html_escape(m.initializer)
        return name_html + init
    if m.kind == "enum":
        vals = []
        for ev in m.enumvalues:
            ev_has_detail = gen.has_detail(m) and (ev.doc.has_doc and not ev.doc.empty())
            if ev_has_detail or has_detail and ev.doc.has_doc and not ev.doc.empty():
                vals.append(f'<a class="el" href="#{_enumvalue_id(m, ev)}">{html_escape(ev.name)}</a>')
            else:
                vals.append(f"<b>{html_escape(ev.name)}</b>")
        return name_html + " { " + "\n, ".join(vals) + "\n }"
    if m.kind == "variable":
        extra = ""
        # Initializers are not shown in brief decl rows for variables.
        return name_html + extra
    return name_html


def _compound_decl_row/gen_dummy():
    pass
