def _compound_decl_row(gen, c):
    kindword = {"class": "class", "struct": "struct", "union": "union",
                "interface": "interface", "namespace": "namespace"}.get(c.kind, c.kind)
    # The memitem suffix for compound rows encodes ':' as _3A etc.
