    out = []
    out.append(f'<tr class="memitem:{html_escape(suffix)}" id="r_{html_escape(suffix)}">')
    out.append(f'<td class="memItemLeft">{html_escape(kindword)} &#160;</td>')
    out.append(f'<td class="memItemRight"><a class="el" href="{html_escape(href)}">{html_escape(c.qualified)}</a></td></tr>\n')
