    return "".join(out)


# --------------------------------------------------------------------------
# Detailed member documentation


def _detail_sections(gen, compound, secs):
    out = []
    # Group detailed members by doc-section title in section order.
    seen_titles = []
    grouped = {}
    for key, anchor, title, doc_anchor, doc_title, members in secs:
        if key in ("classes", "namespaces"):
            continue
        detailed = [m for m in members if isinstance(m, Member) and (gen.has_detail(m) or (m.kind == "enum" and any(ev.doc.has_doc and not ev.doc.empty() for ev in m.enumvalues)))]
        if not detailed:
            continue
        effective_title = doc_title or title
        effective_anchor = doc_anchor or ("doc-" + anchor)
        if effective_title not in grouped:
            grouped[effective_title] = (effective_anchor, [])
            seen_titles.append(effective_title)
        grouped[effective_title][1].extend(detailed)
    for title_text in seen_titles:
        anchor, members = grouped[title_text]
        if gen.b("SORT_MEMBER_DOCS"):
            members = sorted(members, key=lambda mm: (0 if (gen.b("SORT_MEMBERS_CTORS_1ST") and _is_ctor(gen, mm)) else 1, mm.name.lower(), mm.name))
        out.append(f'<a name="{anchor}" id="{anchor}"></a><h2 id="header-{anchor}" class="groupheader">{html_escape(title_text)}</h2>\n')
        for m in members:
            out.append(_member_detail(gen, compound, m))
    return "".join(out)


def _is_ctor(gen, m):
    return m.parent is not None and m.name == m.parent.name.split("<")[0]


def _member_detail(gen, compound, m):
    anchor = _anchor(m)
    out = []
    title_name = m.name + ("()" if m.kind == "function" else "")
    out.append(f'<a id="{anchor}" name="{anchor}"></a>\n')
    out.append(f'<h2 class="memtitle"><span class="permalink"><a href="#{anchor}">&#9670;&#160;</a></span>{html_escape(title_name)}</h2>\n\n')
    out.append('<div class="memitem">\n<div class="memproto">\n')
    out.append(_memproto(gen, m))
    out.append('</div><div class="memdoc">\n')
    blocks = []
    if gen.b("REPEAT_BRIEF") and m.doc.brief:
        blocks.extend(m.doc.brief)
    blocks.extend(m.doc.detailed)
    if blocks:
        out.append("\n" + render_blocks_html(blocks, gen.ctx))
    if m.kind == "enum" and m.enumvalues:
        if any(ev.doc.has_doc and not ev.doc.empty() for ev in m.enumvalues):
            out.append('<table class="fieldtable">\n<tr><th colspan="2">Enumerator</th></tr>')
            for ev in m.enumvalues:
                if not (ev.doc.has_doc and not ev.doc.empty()):
                    continue
                evid = _enumvalue_id(m, ev)
                dhtml = render_blocks_html(ev.doc.brief + ev.doc.detailed, gen.ctx)
                out.append(f'<tr><td class="fieldname"><a id="{evid}" name="{evid}"></a>{html_escape(ev.name)}&#160;</td><td class="fielddoc">{dhtml}</td></tr>\n')
            out.append("</table>\n")
    out.append("\n</div>\n</div>\n")
    return "".join(out)


def _labels_for(m):
    labels = []
    if m.kind == "enum" and m.strong:
        labels.append(("strong", "strong"))
    if m.static and m.kind in ("function", "variable"):
        parent_static = m.parent is not None and m.parent.kind in ("class", "struct", "union", "interface")
        if parent_static:
            labels.append(("static", "static"))
    if m.inline:
        labels.append(("inline", "inline"))
    if m.kind == "function" and m.virt == "virtual":
        labels.append(("virtual", "virtual"))
    if m.kind == "function" and m.virt == "pure-virtual":
        labels.append(("virtual", "pure virtual"))
    if getattr(m, "mutable", False):
        labels.append(("mutable", "mutable"))
    if getattr(m, "extern", False) and m.kind == "variable" and m.parent is not None and m.parent.kind in ("class", "struct"):
        labels.append(("extern", "extern"))
    return labels


def _memproto(gen, m):
    labels = _labels_for(m)
    inner = _memname_table(gen, m)
    if not labels:
        return inner
    spans = "".join(f'<span class="mlabel {cls_}">{html_escape(txt)}</span>' for cls_, txt in labels)
    return (
        '<table class="mlabels">\n  <tr>\n  <td class="mlabels-left">\n'
        + inner
        + '  </td>\n  <td class="mlabels-right">\n'
        + f'<span class="mlabels">{spans}</span>  </td>\n  </tr>\n</table>\n'
    )


def _memname_table(gen, m):
    out = ['      <table class="memname">\n']
    if m.kind == "function" or m.kind == "friend":
        # memname text: type + qualified name (C++ style) or Python dotted.
        if m.parent is not None and m.parent.kind in ("class", "struct", "union", "interface"):
            if m.parent.language == "Python":
                qname = m.qualified
            else:
                qname = m.parent.qualified + "::" + m.name
        elif m.parent is not None and m.parent.kind == "namespace" and m.parent.language == "Python":
            qname = m.name
        elif m.parent is not None and m.parent.kind == "namespace":
            qname = m.name
        else:
            qname = m.name
        memname = (f"{m.type} " if m.type else "") + qname
        memname_html = _type_html(gen, memname)
        params = m.params
        suffix = ""
        if m.const and "const" in (m.argsstring or ""):
            suffix = " const"
        if not params:
            out.append("        <tr>\n")
            out.append(f'          <td class="memname">{memname_html} </td>\n          <td>(</td>\n')
            out.append('          <td class="paramname"><span class="paramname"><em></em></span></td><td>)</td>\n')
            if suffix:
                out.append(f"          <td>{suffix}</td>\n")
            out.append("        </tr>\n")
        elif len(params) == 1 and params[0].get("type") == "void" and not (params[0].get("declname") or params[0].get("defname")):
            out.append("        <tr>\n")
            out.append(f'          <td class="memname">{memname_html} </td>\n          <td>(</td>\n')
            out.append('          <td class="paramtype">void</td>          <td class="paramname"><span class="paramname"><em></em></span></td><td>)</td>\n')
            if suffix:
                out.append(f"          <td>{suffix}</td>\n")
            out.append("        </tr>\n")
        else:
            for idx, p in enumerate(params):
                ptype = _type_html(gen, p.get("type", ""))
                pname = p.get("declname") or p.get("defname") or ""
                pnamedef = f'<span class="paramname"><em>{html_escape(pname)}</em></span>'
                if p.get("defval"):
                    pnamedef += f' = {html_escape(p["defval"])}'
                out.append("        <tr>\n")
                if idx == 0:
                    out.append(f'          <td class="memname">{memname_html} </td>\n          <td>(</td>\n')
                else:
                    out.append('          <td class="paramkey"></td>\n          <td></td>\n')
                endmark = ", " if idx < len(params) - 1 else "&#160;)"
                out.append(f'          <td class="paramtype">{ptype}</td>          <td class="paramname">{pnamedef}{endmark}</td>\n')
                if idx == len(params) - 1 and suffix:
                    # suffix is included after the ) above in samples for 0 params; keep simple
                    pass
                out.append("        </tr>\n")
    elif m.kind == "enum":
        qual = m.parent.qualified + "::" + m.name if m.parent is not None and m.parent.kind == "namespace" else m.qualified
        kind_txt = "enum class " if m.strong else "enum "
        anchor = _anchor(m)
        out.append("        <tr>\n")
        out.append(f'          <td class="memname">{kind_txt}<a class="el" href="#{anchor}">{html_escape(qual)}</a></td>\n')
        out.append("        </tr>\n")
    elif m.kind == "define":
        params = ""
        if m.params:
            params = "(" + ", ".join(p.get("declname") or "" for p in m.params) + ")"
        line = f"#define {html_escape(m.name)}{params}"
        if m.initializer:
            line += f"&#160;&#160;{html_escape(m.initializer)}"
        out.append(f'        <tr><td class="memname">{line}</td></tr>\n')
    else:
        defn = m.definition or ((m.type + " ") if m.type else "") + m.qualified
        line = _type_html(gen, defn)
        if m.argsstring:
            line += html_escape(m.argsstring)
        if m.initializer and m.kind == "variable":
            line += " " + html_escape(m.initializer)
        out.append(f'        <tr><td class="memname">{line}</td></tr>\n')
    out.append("      </table>\n")
    return "".join(out)
