    if summary:
        content.append(summary)
    if is_file and gen.b("SOURCE_BROWSER") is not None:
        # Source link is shown for documented files in samples.
        content.append(f'\n<p><a href="{c.id}_source{gen.ext}">Go to the source code of this file.</a></p>\n')
