def _navpath(gen, c):
    items = []
    if c.kind == "file":
        # directory ancestors
        rel = (c.rel_path or c.name).replace(os.sep, "/")
        parts = rel.split("/")[:-1]
        prefix = ""
        for part in parts:
            prefix = part if not prefix else prefix + "/" + part
            d = next((x for x in gen.project.dirs if x.name == prefix), None)
            if d is not None:
                items.append((part, d.id + gen.ext))
        items.append((c.name, c.id + gen.ext))
        return items
    if c.kind in ("class", "struct", "union", "interface", "namespace", "concept"):
        chain = c.qualified.split("::")
        cur = ""
        for idx, part in enumerate(chain):
            cur = part if not cur else cur + "::" + part
            if idx == len(chain) - 1:
                items.append((part, c.id + gen.ext))
            else:
                anc = gen.project.find_compound(cur)
                if anc is not None and gen.compound_visible(anc) and anc.kind == "namespace" and not anc.documented() and gen.b("HIDE_UNDOC_NAMESPACES"):
                    items.append((part, None))
                elif anc is not None:
                    items.append((part, anc.id + gen.ext))
                else:
                    items.append((part, None))
        return items
    return []


