def _source_page(gen, f):
    title = f"{f.name} Source File"
    heading = f.name
    source = f.source or ""
    lines = _code_lines(source, strip_comments=gen.b("STRIP_CODE_COMMENTS")) if f.language != "Python" else [(i + 1, l) for i, l in enumerate(source.split("\n")[:-1])]
    by_line = {}
    for m in gen.project.all_members:
        if m.file_compound is f:
            by_line.setdefault(m.location.line, []).append(m)
    by_comp = {}
    for c in gen.project.compounds:
        if c.file_compound is f:
            by_comp.setdefault(c.location.line, []).append(c)
    tooltips = []
    out_lines = []
    state = {"in_comment": False}
    for lineno, code in lines:
        members = by_line.get(lineno, [])
        comps = [c for c in by_comp.get(lineno, []) if c.kind in ("class", "struct", "union", "interface")]
        refm = None
        for m in members:
            from .xmlgen import _member_visible_in_code
            if _member_visible_in_code(m, gen.ctx):
                refm = m
                break
        toks = _tokenize_code_line(code)
        segs = _code_segments(toks, members, comps, gen.ctx, gen.cfg, state)
        # Build html code text with refs.
        code_html = _segs_to_html(gen, segs, f)
        if refm is not None:
            href = f"{_member_page_base(gen, refm)}{gen.ext}#{_anchor(refm)}"
            lineno_html = f'<a class="line" href="{href}">{lineno:>5}</a>'
            tooltips.append(_tooltip(gen, refm, f))
        elif comps:
            href = comps[0].id + gen.ext
            lineno_html = f'<a class="line" href="{href}">{lineno:>5}</a>'
            tooltips.append(_tooltip_compound(gen, comps[0], f))
        else:
            lineno_html = f"{lineno:>5}"
        out_lines.append(
            f'<div class="line"><a id="l{lineno:05d}" name="l{lineno:05d}"></a><span class="lineno">{lineno_html}</span>{code_html}</div>\n'
        )
    fragment = (
        f'<a href="{f.id}{gen.ext}">Go to the documentation of this file.</a>'
        '<div class="fragment">' + "".join(out_lines) + "".join(tooltips) + "</div><!-- fragment -->"
    )
    gen.write_page(f.id + "_source" + gen.ext, title, fragment,
                   page_kind="source", navpath_items=_navpath(gen, f), header_title=heading)


def _tooltip(gen, m, f):
    anchor = _anchor(m)
    base = _member_page_base(gen, m)
    tid = f"a{f.id}_html_{anchor}"
    decl = html_escape((m.definition or m.name) + (m.argsstring or ""))
    doc = gen._brief_plain(m)
    parts = [f'<div class="ttc" id="{tid}"><div class="ttname"><a href="{base}{gen.ext}#{anchor}">{html_escape(m.name)}</a></div><div class="ttdeci">{decl}</div>']
    if doc:
        parts.append(f'<div class="ttdoc">{html_escape(doc)}</div>')
    parts.append("</div>\n")
    return "".join(parts)


def _tooltip_compound(gen, c, f):
    tid = f"a{f.id}_html_{c.id}"
    decl = html_escape(c.qualified)
    doc = gen._brief_plain(c)
    parts = [f'<div class="ttc" id="{tid}"><div class="ttname"><a href="{c.id}{gen.ext}">{html_escape(c.name)}</a></div>']
    if doc:
        parts.append(f'<div class="ttdoc">{html_escape(doc)}</div>')
    parts.append("</div>\n")
    return "".join(parts)


def _segs_to_html(gen, segs, f):
    out = []
    # The reference starts most lines (after the first) without the empty
    # normal segment artefact that XML code listing has: single leading
    # empty segments are dropped in HTML, while whitespace tokens stay.
    for cls, text in segs:
        pieces = re.split(r"([\x01].*?[\x03])", text)
        buf = []
        for piece in pieces:
            if piece.startswith("\x01"):
                bits = piece[1:-1].split("\x02")
                refid, word = bits[0], bits[1] if len(bits) > 1 else ""
                kind = bits[2] if len(bits) > 2 else "member"
                if kind == "compound":
                    buf.append(f'<a class="code hl_class" href="{refid}{gen.ext}">{html_escape(word)}</a>')
                else:
                    ent = _member_by_id(gen, refid)
                    base = _member_page_base(gen, ent) if ent is not None else refid.rsplit("_1a", 1)[0]
                    anchor = "a" + refid.rsplit("_1a", 1)[-1]
                    hl = "hl_function" if ent is not None and ent.kind in ("function", "friend") else "hl_variable"
                    buf.append(f'<a class="code {hl}" href="{base}{gen.ext}#{anchor}">{html_escape(word)}</a>')
            else:
                buf.append(html_escape(piece))
        text_html = "".join(buf)
        if cls == "normal":
            out.append(text_html)
        else:
            if text_html == "":
                continue
            out.append(f'<span class="{cls}">{text_html}</span>')
    return "".join(out)


def _member_by_id(gen, refid):
    for m in gen.project.all_members:
        if m.id == refid:
            return m
    return None
