def _js_escape(s):
    return s.replace("\\", "\\\\").replace('"', '\\"')


def _nav_children(gen):
    """Build a nested nav data structure:
    entries are [text, url, children_url_or_None, children_list]."""
    # We model the nav tree after the default layout tabs.
    root_children = []

    def file_children():
        children = []
        if gen._files_doc:
            children.append(["File List", "files" + gen.ext, "files_dup", []])
            gm = _global_member_categories(gen)
            if gm:
                all_children = [["All", "globals" + gen.ext, None, []]]
                labels = {"function": "Functions", "variable": "Variables", "typedef": "Typedefs", "enum": "Enumerations", "enumvalue": "Enumeration Values", "define": "Macros"}
                fnames = {"function": "globals_func", "variable": "globals_vars", "typedef": "globals_type", "enum": "globals_enum", "enumvalue": "globals_eval", "define": "globals_defs"}
                for kind in ("function", "variable", "typedef", "enum", "enumvalue", "define"):
                    if kind in gm:
                        all_children.append([labels[kind], fnames[kind] + gen.ext, None, []])
                children.append(["File Members", "globals" + gen.ext, None, all_children])
        return children

    tabs = []
    classes = gen._classes
    namespaces = gen._namespaces
    if any(not _is_main(p) for p in gen.project.pages):
        tabs.append(["Related Pages", "pages" + gen.ext, None, []])
    if gen.project.groups:
        tabs.append(["Topics", "topics" + gen.ext, None, []])
    if namespaces:
        ns_children = [["Namespace List", "namespaces" + gen.ext, None, []]]
        # namespace members child elided unless present
        tabs.append(["Namespaces", "namespaces" + gen.ext, None, ns_children])
    if classes:
        class_children = [["Class List", "annotated" + gen.ext, "annotated_dup", []]]
        if gen.b("ALPHABETICAL_INDEX"):
            class_children.append(["Class Index", "classes" + gen.ext, None, []])
        class_children.append(["Class Hierarchy", "hierarchy" + gen.ext, "hierarchy", []])
        cm = _class_member_categories(gen)
        if cm:
            mem_children = [["All", "functions" + gen.ext, None, []]]
            if "function" in cm:
                mem_children.append(["Functions", "functions_func" + gen.ext, None, []])
            if "variable" in cm:
                mem_children.append(["Variables", "functions_vars" + gen.ext, None, []])
            class_children.append(["Class Members", "functions" + gen.ext, None, mem_children])
        tabs.append(["Classes", "annotated" + gen.ext, None, class_children])
    if gen._files_doc:
        fc = file_children()
        if fc:
            tabs.append(["Files", "files" + gen.ext, None, fc])
    root = [_project_name(gen.cfg), "index" + gen.ext, None, tabs]
    # Menu children exclude the root itself.
    return root, tabs


def _global_member_categories(gen):
    cats = set()
    for m in gen.project.all_members:
        if not m.documented():
            continue
        p = m.parent
        if p is not None and p.kind == "file" and gen.file_documented(p):
            cats.add(m.kind)
        elif p is not None and p.kind == "namespace" and gen.compound_visible(p):
            cats.add(m.kind)
    return cats


def _class_member_categories(gen):
    cats = set()
    for c in gen._classes:
        for m in c.members:
            if m.documented():
                cats.add(m.kind)
    return cats


def _navtree_js(node, indent=2):
    text, url, dup, children = node[0], node[1], node[2], node[3]
    pad = " " * indent
    if not children:
        if dup:
            return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", "{_js_escape(dup)}" ]'
        return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", null ]'
    inner = ",\n".join(_navtree_js(c, indent + 2) for c in children)
    if dup:
        return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", "{_js_escape(dup)}", [\n{inner}\n{pad}] ]'
    return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", [\n{inner}\n{pad}] ]'


def _menu_js(node, top=False):
    # node: [text,url,dup,children]
    text, url, dup, children = node
    bits = []
    if children:
        ctext = ",".join(_menu_js(c) for c in children)
        bits.append("{text:\"" + _js_escape(text) + "\",url:\"" + _js_escape(url) + "\",children:[" + ctext + "]}")
    else:
        bits.append("{text:\"" + _js_escape(text) + "\",url:\"" + _js_escape(url) + "\"}")
    return bits[0]


def _nav_paths(gen, root):
    """Map page URL -> index path in nav tree (for navtreeindex)."""
    paths = {}

    def walk(node, path):
        url = node[1]
        if url and url not in paths:
            paths[url] = list(path)
        for i, child in enumerate(node[3]):
            walk(child, path + [i])
        # Expanded child content (files, classes) is addressed under the
        # corresponding dup nodes - handled by the caller additions.

    walk(root, [])
    # Main page reference in samples.
    paths.setdefault("index" + gen.ext, [])
    paths.setdefault("pages" + gen.ext, [])
    return paths


def _nav_and_search(gen):
    out = gen.out
    root, tabs = _nav_children(gen)

    # menudata.js (present when the index is enabled)
    if not gen.b("DISABLE_INDEX"):
        main = ["Main Page", "index" + gen.ext, None, []]
        menu_children = []
        # Root tabs in menu include Main Page first.
        menu_children.append("{text:\"Main Page\",url:\"index" + gen.ext + "\"}")
        for t in tabs:
            menu_children.append(_menu_js(t))
        menu_children_js = ",\n".join(menu_children) + "]}"
        menudata = _LICENSE_LINES + "var menudata={children:[\n" + ",\n".join(menu_children) + "]}"
        write_output_file(os.path.join(out, "menudata.js"), menudata)
        if gen.b("HTML_DYNAMIC_MENUS"):
            write_output_file(os.path.join(out, "menu.js"), resources.get_bytes("html_res/menu.js"))

    if gen.b("GENERATE_TREEVIEW"):
        nav = _LICENSE_LINES + "var NAVTREE =\n[\n" + _navtree_js(root, 2) + "\n];\n\n"
        # NAVTREEINDEX lists the first entry page.
        first_url = ""
        # We find first leaf in depth order.
        def first_leaf(node):
            if node[3]:
                return first_leaf(node[3][0])
            return node[1]
        if root[3]:
            first_url = first_leaf(root)
        nav += "var NAVTREEINDEX =\n[\n\"" + _js_escape(first_url) + "\"\n];\n\n"
        nav += "const SYNCONMSG = 'click to disable panel synchronization';\n"
        nav += "const SYNCOFFMSG = 'click to enable panel synchronization';\n"
        nav += "const LISTOFALLMEMBERS = 'List of all members';"
        write_output_file(os.path.join(out, "navtreedata.js"), nav)
        # navtreeindex0.js
        paths = _nav_paths(gen, root)
        # Add compound/file pages under the File List / Class List nodes.
        _augment_nav_paths(gen, paths, root)
        entries = []
        for url in sorted(paths.keys()):
            entries.append(f'"{_js_escape(url)}":[{",".join(str(x) for x in paths[url])}]')
        write_output_file(os.path.join(out, "navtreeindex0.js"),
                          "var NAVTREEINDEX0 =\n{\n" + ",\n".join(entries) + "\n};\n")
        # Per-parent dup data files.
        _write_dup_files(gen)
    _search_indices(gen)


def _augment_nav_paths(gen, paths, root):
    # Files
    files_path = None
    ann_path = None

    def find(node, path, url):
        if node[1] == url:
            return list(path)
        for i, c in enumerate(node[3]):
            r = find(c, path + [i], url)
            if r is not None:
                return r
        return None

    fl = find(root, [], "files" + gen.ext)
    docs = sorted(gen._files_doc, key=lambda f: f.name.lower())
    if fl is not None:
        for i, f in enumerate(docs):
            paths[f.id + gen.ext] = fl + [i]
            paths[f.id + "_source" + gen.ext] = fl + [i]
            # Documented members of the file.
            mi = 0
            for m in f.members:
                if m.documented():
                    paths[f.id + gen.ext + "#" + _anchor(m)] = fl + [i, mi]
                    mi += 1
    ann = find(root, [], "annotated" + gen.ext)
    if ann is not None:
        # Classes are listed grouped by namespace in annotated_dup:
        # approximate with a flat enumeration.
        flat = []
        def collect(classes):
            for c in classes:
                flat.append(c)
        collect(sorted(gen._classes, key=lambda c: c.qualified.lower()))
        for i, c in enumerate(flat):
            paths[c.id + gen.ext] = ann + [i]
    return paths


def _write_dup_files(gen):
    out = gen.out
    # files_dup.js
    if gen._files_doc:
        rows = []
        for f in sorted(gen._files_doc, key=lambda x: x.name.lower()):
            rows.append(f'    [ "{_js_escape(f.name)}", "{f.id}{gen.ext}", "{f.id}" ]')
            members = [m for m in f.members if m.documented()]
            member_rows = []
            for m in members:
