        write_output_file(os.path.join(out, "files_dup.js"),
                          "var files_dup =\n[\n" + ",\n".join(rows) + "\n];")
    if gen._classes:
        rows = []
        ns_seen = []

        def class_row(c):
            var = c.id
            if c.members:
                rows_ = []
                for m in c.members:
                    rows_.append(f'    [ "{_js_escape(m.name)}", "{c.id}{gen.ext}#{_anchor(m)}", null ]')
                write_output_file(os.path.join(out, var + ".js"),
                                  f"var {var} =\n[\n" + ",\n".join(rows_) + "\n];")
                return f'    [ "{_js_escape(c.name)}", "{c.id}{gen.ext}", "{c.id}" ]'
            return f'    [ "{_js_escape(c.name)}", "{c.id}{gen.ext}", null ]'

        by_ns = {}
        for c in gen._classes:
            parent = c.parent
            key = parent.qualified if parent is not None and parent.kind == "namespace" else ""
            by_ns.setdefault(key, []).append(c)
        items = []
        for ns in sorted(by_ns):
            if ns:
                inner = ",\n".join(class_row(c) for c in sorted(by_ns[ns], key=lambda x: x.name.lower()))
                render = ns.rsplit(".", 1)
                a = None
                short = ns.split("::")[-1]
                short = ns.split(".")[-1] if short == ns else short
                short = ns.replace("::", ".").split(".")[-1]
                items.append(f'    [ "{short}", null, [\n' + inner + "\n        ] ]" if False else f'    [ "{short}", null, [\n' + inner + "\n    ] ]")
            else:
                for c in by_ns[ns]:
                    items.append(class_row(c))
        write_output_file(os.path.join(out, "annotated_dup.js"),
                          "var annotated_dup =\n[\n" + ",\n".join(items) + "\n];")
        # hierarchy dup is referenced in nav data but file name is class id based?
