def _search_indices(gen):
    if not gen.b("SEARCHENGINE") or gen.b("SERVER_BASED_SEARCH") or gen.b("EXTERNAL_SEARCH"):
        return
    out = os.path.join(gen.out, "search")
    os.makedirs(out, exist_ok=True)
    mode = gen.cfg.get_enum("HTML_COLORSTYLE")
