    sections = [x for x in sorted(sections, key=lambda x: order_names.index(x[0])) if x[0] == "all" or any(s[2] == x[0] for s in symbols)]
    index_with_content = {}
    section_data = {}
    for i, (kind, label) in enumerate(sections):
        entries = symbols if kind == "all" else [s for s in symbols if s[2] == kind]
        by_letter = {}
        letters = []
        for name, url, _k, scope in sorted(entries, key=lambda e: (e[0].lower(), e[0])):
            ch = name[0].lower() if name else "?"
            if ch not in by_letter:
                by_letter[ch] = []
                letters.append(ch)
            by_letter[ch].append((name, url, scope))
        index_with_content[i] = "".join(sorted(set(letters)))
        for j, ch in enumerate(sorted(set(letters))):
