def _global_member_categories(gen):
    cats = set()
    for m in gen.project.all_members:
        if not m.documented():
            continue
        p = m.parent
        if p is not None and p.kind == "file" and gen.file_documented(p):
            cats.add(m.kind)
        elif p is not None and p.kind == "namespace" and gen.compound_visible(p):
            cats.add(m.kind)
    return cats


def _class_member_categories(gen):
    cats = set()
    for c in gen._classes:
        for m in c.members:
            if m.documented():
                cats.add(m.kind)
    return cats


def _navtree_js(node, indent=2):
    text, url, dup, children = node[0], node[1], node[2], node[3]
    pad = " " * indent
    if not children:
        if dup:
            return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", "{_js_escape(dup)}" ]'
        return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", null ]'
    inner = ",\n".join(_navtree_js(c, indent + 2) for c in children)
    if dup:
        return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", "{_js_escape(dup)}", [\n{inner}\n{pad}] ]'
    return f'{pad}[ "{_js_escape(text)}", "{_js_escape(url)}", [\n{inner}\n{pad}] ]'


def _menu_js(node, top=False):
    # node: [text,url,dup,children]
    text, url, dup, children = node
    bits = []
    if children:
        ctext = ",".join(_menu_js(c) for c in children)
        bits.append("{text:\"" + _js_escape(text) + "\",url:\"" + _js_escape(url) + "\",children:[" + ctext + "]}")
    else:
        bits.append("{text:\"" + _js_escape(text) + "\",url:\"" + _js_escape(url) + "\"}")
    return bits[0]


def _nav_paths(gen, root):
    """Map page URL -> index path in nav tree (for navtreeindex)."""
    paths = {}

    def walk(node, path):
        url = node[1]
        if url and url not in paths:
            paths[url] = list(path)
        for i, child in enumerate(node[3]):
            walk(child, path + [i])
        # Expanded child content (files, classes) is addressed under the
        # corresponding dup nodes - handled by the caller additions.

    walk(root, [])
    # Main page reference in samples.
    paths.setdefault("index" + gen.ext, [])
    paths.setdefault("pages" + gen.ext, [])
    return paths


