def _search_indices(gen):
    if not gen.b("SEARCHENGINE") or gen.b("SERVER_BASED_SEARCH") or gen.b("EXTERNAL_SEARCH"):
        return
    out = os.path.join(gen.out, "search")
    os.makedirs(out, exist_ok=True)
    mode = gen.cfg.get_enum("HTML_COLORSTYLE")
    dynamic = gen.b("HTML_DYNAMIC_MENUS") and not gen.b("GENERATE_HTMLHELP")
    name = "search.css" if dynamic else "search_static.css"
    css = resources.get_text("html_res/search/" + name)
    css = cssgen.resolve_variables(css, mode)
    css = cssgen.apply_colorstyle(css, gen.cfg.get_int("HTML_COLORSTYLE_HUE"),
                                  gen.cfg.get_int("HTML_COLORSTYLE_SAT"),
                                  gen.cfg.get_int("HTML_COLORSTYLE_GAMMA"))
    write_output_file(os.path.join(out, "search.css"), css)
    write_output_file(os.path.join(out, "search.js"), resources.get_bytes("html_res/search/search.js"))

    # Collect entries: (symbol, url, kind?, scope)
    symbols = []
    # Files by name
    for f in gen._files_doc:
        symbols.append((f.name, f.id + gen.ext, "files", ""))
    for c in gen._classes:
        symbols.append((c.name, c.id + gen.ext, "classes", c.qualified.rsplit("::", 1)[0] if "::" in c.qualified else ""))
    for ns in gen._namespaces:
        symbols.append((ns.name, ns.id + gen.ext, "namespaces", ""))
    for m in gen.project.all_members:
        if not m.documented():
            continue
        parent = m.parent
        if parent is not None and parent.kind == "file":
            scope = parent.name
            url = parent.id + gen.ext + "#" + _anchor(m)
        elif parent is not None and parent.kind in ("class", "struct", "union", "interface"):
            scope = parent.qualified
            url = parent.id + gen.ext + "#" + _anchor(m)
        elif parent is not None and parent.kind == "namespace":
            if not gen.compound_visible(parent):
                # Members of hidden namespaces are attached to the file.
                if m.file_compound is None:
                    continue
                scope = m.file_compound.name
                url = m.file_compound.id + gen.ext + "#" + _anchor(m)
            else:
                scope = parent.qualified
                url = parent.id + gen.ext + "#" + _anchor(m)
        else:
            continue
        kind = {"function": "functions", "variable": "variables", "typedef": "typedefs",
                "enum": "enums", "define": "defines"}.get(m.kind)
        if kind:
            symbols.append((m.name, url, kind, scope))

    sections = [("all", "All")]
    for kind, label in (("classes", "Classes"), ("namespaces", "Namespaces"), ("files", "Files"),
                        ("functions", "Functions"), ("variables", "Variables"),
                        ("typedefs", "Typedefs"), ("enums", "Enumerations"), ("defines", "Macros")):
        if any(s[2] == kind for s in symbols):
            sections.append((kind, label))
    # Alphabetical ordering of sections in samples: all, files, functions.
    # Implement traversal order used by the reference's SearchIndex:
    order_names = ["all", "classes", "namespaces", "files", "functions", "variables", "typedefs", "enums", "defines"]
    sections = [x for x in sorted(sections, key=lambda x: order_names.index(x[0])) if x[0] == "all" or any(s[2] == x[0] for s in symbols)]
    index_with_content = {}
    section_data = {}
    for i, (kind, label) in enumerate(sections):
        entries = symbols if kind == "all" else [s for s in symbols if s[2] == kind]
        by_letter = {}
        letters = []
        for name, url, _k, scope in sorted(entries, key=lambda e: (e[0].lower(), e[0])):
            ch = name[0].lower() if name else "?"
            if ch not in by_letter:
                by_letter[ch] = []
                letters.append(ch)
            by_letter[ch].append((name, url, scope))
        index_with_content[i] = "".join(sorted(set(letters)))
        for j, ch in enumerate(sorted(set(letters))):
            rows = []
            for name, url, scope in by_letter[ch]:
                ident = re.sub(r"[^A-Za-z0-9_]", "_", name.lower()) + "_0"
                rows.append(f"  ['{ident}',['{name}',['../{url}',1,'{scope}']]]")
            write_output_file(os.path.join(out, f"{kind}_{j}.js"),
                              "var searchData=\n[\n" + ",\n".join(rows) + "\n];\n")
        section_data[i] = (kind, label)
    content_lines = ",\n".join(f'  {i}: "{index_with_content[i]}"' for i in range(len(sections)))
    name_lines = ",\n".join(f'  {i}: "{sections[i][0]}"' for i in range(len(sections)))
    label_lines = ",\n".join(f'  {i}: "{sections[i][1]}"' for i in range(len(sections)))
    write_output_file(os.path.join(out, "searchdata.js"),
                      "var indexSectionsWithContent =\n{\n" + content_lines + "\n};\n\n"
                      "var indexSectionNames =\n{\n" + name_lines + "\n};\n\n"
                      "var indexSectionLabels =\n{\n" + label_lines + "\n};\n")


def _crawl(gen):
    urls = set()
    for f in gen.pages_written:
