    for u in sorted(urls | {"doxygen_crawl" + gen.ext}):
        lines.append(f'<a href="{html_escape(u)}"/>')
    lines += ["</body>", "</html>", ""]
    write_output_file(os.path.join(gen.out, "doxygen_crawl" + gen.ext), "\n".join(lines))


