def _latex_process_template(text, cfg, variables, conditions):
    if "\n" in text:
        text = text.split("\n", 1)[1]
    out = []
    stack = []
    marker_re = re.compile(r"%%(BEGIN|END)\s+(!?)([A-Z0-9_]+)")

    def active():
        return all(stack)

    for raw in text.splitlines(keepends=True):
        has_nl = raw.endswith("\n")
        line = raw[:-1] if has_nl else raw
        pieces = []
        pos = 0
        has_marker = False
        for m in marker_re.finditer(line):
            has_marker = True
            if active():
                pieces.append(line[pos:m.start()])
            if m.group(1) == "BEGIN":
                v = conditions.get(m.group(3), False)
                if m.group(2) == "!":
                    v = not v
                stack.append(v)
            else:
                if stack:
                    stack.pop()
            pos = m.end()
        if active():
            pieces.append(line[pos:])
        rendered = "".join(pieces)
        if rendered.strip() == "":
            continue
        out.append(rendered)
        if has_nl:
            out.append("\n")
    result = "".join(out)
    result = result.replace("$latexdocumentpre", "")
    for key in sorted(variables, key=len, reverse=True):
        result = re.sub(r"(?m)^([ \t]*)\$" + re.escape(key) + r"[ \t]*\r?\n",
                        (variables[key] if variables[key] else ""), result)
        result = result.replace("$" + key, variables[key])
    return result


