        ref_inputs.append(("Namespace Index", "namespaces"))
    class_inputs = []
    for c in classes:
        put(c.id + ".tex", _latex_compound(gen, c))
        class_inputs.append(c.id)
    ns_inputs = []
    for ns in namespaces:
        put(ns.id + ".tex", _latex_compound(gen, ns))
        ns_inputs.append(ns.id)
    file_inputs = []
    for f in files_doc:
