    else:
        header_text = resources.get_text("latex/latex_header.tex")
    footer_text = resources.get_text("latex/latex_footer.tex")
    footer_name = cfg.get_string("LATEX_FOOTER")
    if footer_name:
        try:
            with open(footer_name, "r", encoding="utf-8", errors="surrogateescape") as fh:
                footer_text = fh.read()
        except OSError:
            pass

    batch = cfg.get_enum("LATEX_BATCHMODE")
    batch_cmd = {"YES": "\\batchmode", "BATCH": "\\batchmode", "NON_STOP": "\\nonstopmode", "SCROLL": "\\scrollmode", "ERROR_STOP": "\\errorstopmode"}.get(batch, "")
    if cfg.get_enum("TIMESTAMP") == "DATE":
        dt = cssgen.format_timestamp("DATE")
    elif cfg.get_enum("TIMESTAMP") != "NO":
        dt = cssgen.format_timestamp("DATETIME")
    else:
        dt = ""
    if cfg.get_enum("TIMESTAMP") == "NO":
        generatedby = "Generated by"
    else:
        generatedby = "Generated by"
    extra_packages = ""
    for pkg in cfg.get_list("EXTRA_PACKAGES"):
        extra_packages += "\\usepackage{" + pkg + "}\n"
    bib = cfg.get_string("LATEX_BIB_STYLE") or "plainnat"
    bibfiles = ",".join(os.path.splitext(os.path.basename(x))[0] for x in cfg.get_list("CITE_BIB_FILES"))
    variables = {
        "latex_batchmode": ("  " + batch_cmd + "\n") if batch_cmd else "",
        "extralatexstylesheet": "".join("\\usepackage{" + os.path.splitext(os.path.basename(x))[0] + "}\n" for x in cfg.get_list("LATEX_EXTRA_STYLESHEET")),
        "languagesupport": "",
        "latexfontenc": "T1",
        "latexfont": "",
        "latexemojidirectory": cfg.get_string("LATEX_EMOJI_DIRECTORY") or ".",
        "papertype": cfg.get_enum("PAPER_TYPE") + "paper",
        "generatedby": generatedby,
        "makeindex": "  \\makeindex\n",
        "extralatexpackages": extra_packages,
        "latexspecialformulachars": _SPECIAL_FORMULA + "\n" if cfg.get_bool("USE_PDFLATEX") else "",
        "formulamacrofile": cfg.get_string("FORMULA_MACROFILE"),
        "projectname": latex_escape(_project_name(cfg)),
        "projectbrief": latex_escape(cfg.get_string("PROJECT_BRIEF")),
        "projectnumber": latex_escape(cfg.get_string("PROJECT_NUMBER")),
        "title": latex_escape(_project_name(cfg)),
        "doxygenversion": "1.17.0",
        "datetime": dt,
        "latexdocumentpre": "",
        "latexdocumentpost": "",
        "latexbibstyle": bib,
        "latexbibfiles": bibfiles,
        "latexcitereference": "Bibliography",
    }
    conditions = {
        "COMPACT_LATEX": cfg.get_bool("COMPACT_LATEX"),
        "PDF_HYPERLINKS": cfg.get_bool("PDF_HYPERLINKS"),
        "USE_PDFLATEX": cfg.get_bool("USE_PDFLATEX"),
        "LATEX_FONTENC": False,
        "FORMULA_MACROFILE": bool(cfg.get_string("FORMULA_MACROFILE")),
        "PROJECT_NUMBER": bool(cfg.get_string("PROJECT_NUMBER")),
        "TIMESTAMP": cfg.get_enum("TIMESTAMP") != "NO",
        "CITATIONS_PRESENT": bool(cfg.get_list("CITE_BIB_FILES")),
    }
    header = _latex_process_template(header_text, cfg, variables, conditions)
    footer = _latex_process_template(footer_text, cfg, variables, conditions)
    refman = header + "%--- Begin generated contents ---\n" + "".join(chapters) + footer
    put("refman.tex", refman)


def _latex_annotated(gen, classes):
    out = ["\\doxysection{Class List}\n"]
    out.append("Here are the classes, structs, unions and interfaces with brief descriptions:\\+\\begin{DoxyCompactList}\n")
    for c in sorted(classes, key=lambda x: x.qualified.lower()):
        out.append(f"\\item\\contentsline{{section}}{{\\doxymbox{{\\hyperlink{{{c.id}}}{{{latex_word(c.qualified)}}}}} \\\\*{latex_escape(blocks_to_text(c.doc.brief).strip())} }}{{\\pageref{{{c.id}}}}}{{}}\n")
    out.append("\\end{DoxyCompactList}\n")
    return "".join(out)


def _latex_files(gen, files):
    out = ["\\doxysection{File List}\n"]
    out.append("Here is a list of all documented files with brief descriptions:\\+\\begin{DoxyCompactList}\n")
    for f in sorted(files, key=lambda x: x.name.lower()):
        out.append(f"\\item\\contentsline{{section}}{{\\doxymbox{{\\hyperlink{{{f.id}}}{{{latex_word(f.name)}}}}} \\\\*{latex_escape(blocks_to_text(f.doc.brief).strip())} }}{{\\pageref{{{f.id}}}}}{{}}\n")
    out.append("\\end{DoxyCompactList}\n")
    return "".join(out)


def _latex_namespaces_list(gen, namespaces):
    out = ["\\doxysection{Namespace List}\n"]
    out.append("Here is a list of all documented namespaces with brief descriptions:\\+\\begin{DoxyCompactList}\n")
    for ns in namespaces:
        out.append(f"\\item\\contentsline{{section}}{{\\doxymbox{{\\hyperlink{{{ns.id}}}{{{latex_word(ns.qualified)}}}}} \\\\*{latex_escape(blocks_to_text(ns.doc.brief).strip())} }}{{\\pageref{{{ns.id}}}}}{{}}\n")
    out.append("\\end{DoxyCompactList}\n")
    return "".join(out)


def _latex_page_doc(gen, p):
    out = []
    title = p.page_title or p.name
    out.append("\\doxysection{" + latex_escape(title) + "}\n")
    out.append(f"\\label{{{p.id}}}\n")
    out.append(latex_blocks(p.doc.brief + p.doc.detailed, gen.ctx))
    return "".join(out)


def _latex_compound(gen, c):
    title_map = {
        "file": f"{c.name} File Reference",
        "class": f"{c.qualified} Class Reference",
        "struct": f"{c.qualified} Struct Reference",
        "union": f"{c.qualified} Union Reference",
        "interface": f"{c.qualified} Interface Reference",
        "namespace": f"{c.qualified} Namespace Reference",
    }
    title = title_map.get(c.kind, c.qualified)
    out = []
    out.append("\\doxysection{" + latex_word(title) + "}\n")
    out.append(f"\\hypertarget{{{c.id}}}{{}}")
    label_name = c.name if c.kind == "file" else c.qualified
    out.append(f"\\label{{{c.id}}}\\index{{{latex_escape(label_name)}@{{{latex_escape(label_name)}}}}}\n\n\n")
    # Summary (brief then detailed are repeated in detail section)
    summary = latex_blocks(c.doc.brief, gen.ctx)
    if summary.strip():
        out.append(summary.rstrip() + "  \n")
    if c.kind in ("class", "struct", "union", "interface") and c.inc_file and gen.b("SHOW_HEADERFILE") and c.documented():
        out.append(f"\n\n{{\\ttfamily \\+#include $<$ {latex_escape(c.inc_file)} $>$}}\n")
        out[-1] = out[-1].replace("$<$ ", "$<$").replace(" $>$", "$>$")
        out.append("\n")
    secs = _sections_for(gen, c)
    for key, anchor, stitle, doc_anchor, doc_title, members in secs:
        out.append(f"\\doxysubsubsection*{{{stitle}}}\n")
        out.append("\\begin{DoxyCompactItemize}\n")
        for m in members:
            out.append(_latex_decl(gen, c, m))
        out.append("\\end{DoxyCompactItemize}\n")
    detailed = gen._detailed_blocks(c)
    if detailed:
        out.append("\n\\doxysubsection{Detailed Description}\n")
        out.append(latex_blocks(detailed, gen.ctx))
    for doc_title, members in _detailed_members(gen, secs):
        anchor_id = doc_anchor_for(doc_title)
        out.append(f"\n\\label{{{anchor_id}}}\n")
        out.append(f"\\Hypertarget{{{c.id}_{anchor_id}}}\n")
        out.append(f"\\doxysubsection{{{doc_title}}}\n")
        for m in members:
            out.append(_latex_member_detail(gen, c, m))
    return "".join(out)


def doc_anchor_for(title):
    return {
        "Function Documentation": "doc-func-members",
        "Member Function Documentation": "doc-func-members",
        "Variable Documentation": "doc-var-members",
        "Member Data Documentation": "doc-variable-members",
        "Enumeration Type Documentation": "doc-enum-members",
        "Typedef Documentation": "doc-typedef-members",
        "Macro Definition Documentation": "doc-define-members",
    }.get(title, "doc-members")


def _latex_decl(gen, compound, m):
    if isinstance(m, Compound):
        brief = blocks_to_text(m.doc.brief).strip()
        return (f"\\item {m.kind} \\doxymbox{{\\hyperlink{{{m.id}}}{{{latex_word(m.qualified)}}}}}\n"
                + (f"\\begin{{DoxyCompactList}}\\small\\item\\em {latex_escape(brief)} \\end{{DoxyCompactList}}" if brief and gen.b("BRIEF_MEMBER_DESC") else ""))
    has_detail = gen.has_detail(m) or (m.kind == "enum" and any(ev.doc.has_doc and not ev.doc.empty() for ev in m.enumvalues))
    anchor = c_anchor(compound, m)
    out = ["\\item \n"]
    if not has_detail:
        out.append(f"\\Hypertarget{{{anchor}}}\\label{{{anchor}}} \n")
    if m.kind == "define":
        params = ""
        if m.params:
            params = "(" + ", ".join(p.get("declname") or "" for p in m.params) + ")"
        init = f"\\hspace{{0.3cm}}{{{latex_escape(m.initializer or '')}}}" if m.initializer else ""
        decl = f"#define {m.name}{params}{init}"
        out.append(latex_escape(decl) + "\n")
    elif m.kind == "enum":
        kval = "enum class " if m.strong else "enum "
        vals = []
        for ev in m.enumvalues:
            if ev.doc.has_doc and not ev.doc.empty():
                vals.append(f"\\doxymbox{{\\hyperlink{{{anchor}}}{{_enum_anchor_latex(m, ev)}}}}")
                # The above is intentionally simplified below.
                vals[-1] = f"\\doxymbox{{\\hyperlink{{{anchor}a{_md5(ev.name)}}}{{{latex_escape(ev.name)}}}}}"
            else:
                vals.append(latex_escape(ev.name))
        name_q = m.qualified if compound.kind == "file" else m.name
        linkname = f"\\doxymbox{{\\hyperlink{{{anchor}}}{{{latex_word(name_q)}}}}}" if has_detail else f"{{\\bfseries {latex_escape(name_q)}}}"
        out.append(latex_escape(kval) + linkname + " \\{ " + ", ".join(vals) + " \\}\n")
    else:
        name_q = m.name
        if compound.kind == "file" and m.parent is not None and m.parent.kind == "namespace":
            name_q = m.parent.qualified + "::" + m.name
        if has_detail:
            name_html = f"\\doxymbox{{\\hyperlink{{{anchor}}}{{{latex_escape(name_q)}}}}}"
        else:
            name_html = f"{{\\bfseries {latex_escape(name_q)}}}"
        prefix = ""
        if m.kind == "typedef":
            prefix = latex_escape("typedef " + (m.type or "")) + " "
        elif m.type:
            prefix = latex_escape(m.type) + " "
        args = latex_escape(" " + m.argsstring if m.argsstring else "")
        init = ""
        out.append(prefix + name_html + args + init + "\n")
    brief = blocks_to_text(m.doc.brief).strip() if hasattr(m, "doc") else ""
    if brief and gen.b("BRIEF_MEMBER_DESC"):
        out.append(f"\\begin{{DoxyCompactList}}\\small\\item\\em {latex_escape(brief)} \\end{{DoxyCompactList}}")
    return "".join(out)


def _md5(text):
    import hashlib

    return hashlib.md5(text.encode()).hexdigest()


def c_anchor(compound, m):
    return _latex_anchor(compound, m)


def _latex_anchor(compound, m):
    base = compound.id
    return f"{base}_{_anchor(m)}"


def _enum_anchor_latex(m, ev):
    return _md5(ev.name)


def _latex_member_detail(gen, compound, m):
    anchor = _latex_anchor(compound, m)
    out = []
    if m.kind == "function":
        title = m.name + "()"
    else:
        title = m.name
    scope = compound.qualified if compound.kind != "file" else compound.name
    out.append(f"\\Hypertarget{{{anchor}}}\\index{{{latex_escape(scope)}@{{{latex_escape(scope)}}}!{latex_escape(m.name)}@{{{latex_escape(m.name)}}}}}\n")
    out.append(f"\\index{{{latex_escape(m.name)}@{{{latex_escape(m.name)}}}!{latex_escape(scope)}@{{{latex_escape(scope)}}}}}\n")
    out.append(f"\\doxysubsubsection{{\\texorpdfstring{{{latex_escape(title)}}}{{{latex_escape(title)}}}}}\n")
    # Prototype
    out.append("{\\footnotesize\\ttfamily \\label{" + anchor + "} \n")
    if m.kind == "function":
        proto = (f"{m.type} " if m.type else "")
        if compound.kind in ("class", "struct"):
            proto += compound.qualified + "::"
        proto += m.name + " "
        out.append(latex_escape(proto))
        if m.params:
            out.append("(\\begin{DoxyParamCaption}")
            parts = []
            for p in m.params:
                nm = p.get("declname") or p.get("defname") or ""
                parts.append("\\item[{" + latex_escape(p.get("type", "")) + "}]{" + latex_escape(nm) + "}{")
            out.append(", }".join(parts))
            out.append("}\\end{DoxyParamCaption})")
            if m.const:
                out.append(" const")
        else:
            out.append(latex_escape(m.argsstring or ""))
        out.append("}\n\n")
    elif m.kind == "enum":
        kval = "enum class " if m.strong else "enum "
        q = m.qualified
        out.append(latex_escape(kval) + f"\\doxymbox{{\\hyperlink{{{anchor}}}{{{latex_word(q)}}}}}" + ("{[}strong{]}" if m.strong else "") + "}\n\n")
    else:
        decl = m.definition or ((m.type + " ") if m.type else "") + m.qualified
        out.append(latex_escape(decl) + "}\n\n")
    blocks = []
    if gen.b("REPEAT_BRIEF") and m.doc.brief:
        blocks.extend(m.doc.brief)
    blocks.extend(m.doc.detailed)
    if blocks:
        out.append("\n" + latex_blocks(blocks, gen.ctx))
    if m.kind == "enum" and any(ev.doc.has_doc and not ev.doc.empty() for ev in m.enumvalues):
        out.append("\\begin{DoxyEnumFields}[2]{Enumerator}\n")
        for ev in m.enumvalues:
            if ev.doc.has_doc and not ev.doc.empty():
                out.append(f"\\raisebox{{\\heightof{{T}}[0pt][0pt]}} {{\\Hypertarget{{{anchor}a{_md5(ev.name)}}}\\label{{{anchor}a{_md5(ev.name)}}}{latex_escape(ev.name)}}} & " + latex_blocks(ev.doc.brief + ev.doc.detailed, gen.ctx).strip() + "\\\\\n")
        out.append("\\end{DoxyEnumFields}\n")
    return "".join(out)


def _latex_source(gen, f):
    out = [f"\\doxysection{{{latex_word(f.name)}}}\n"]
    out.append(f"\\hypertarget{{{f.id}_source}}{{}}")
    out.append(f"\\label{{{f.id}_source}}\\index{{{latex_escape(f.name)}@{{{latex_escape(f.name)}}}}}\n")
    out.append("\\begin{DoxyCode}{0}\n")
    for lineno, code in _code_lines(f.source or "", strip_comments=gen.b("STRIP_CODE_COMMENTS")):
        out.append(code + "\n")
    out.append("\\end{DoxyCode}\n")
    return "".join(out)


