# DocBook


def generate_docbook(project, cfg, out_base, messenger, warner):
    facade = _Facade(project, cfg, warner.warn)
    gen = facade.gen
    ctx = gen.ctx
    out_dir = os.path.join(out_base, cfg.get_string("DOCBOOK_OUTPUT") or "docbook")
    os.makedirs(out_dir, exist_ok=True)

    def compound_doc(c):
        kind = c.kind
        title = {
            "file": f"{c.name} File Reference",
            "class": f"{c.qualified} Class Reference",
            "struct": f"{c.qualified} Struct Reference",
            "union": f"{c.qualified} Union Reference",
            "interface": f"{c.qualified} Interface Reference",
            "namespace": f"{c.qualified} Namespace Reference",
        }.get(kind, c.qualified)
        o = []
        o.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
        o.append(f'<section xmlns="http://docbook.org/ns/docbook" version="5.0" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="_{xml_escape_attr(c.id)}" xml:lang="en-US">\n')
        o.append(f"<title>{xml_escape(title)}</title>\n")
        indexname = c.name if kind == "file" else c.qualified
        o.append(f"<indexterm><primary>{xml_escape(indexname)}</primary></indexterm>\n")
        if c.doc.brief:
            o.append("<para>\n" + docbook_blocks(c.doc.brief, ctx) + " \n</para>\n")
        if kind in ("class", "struct") and c.inc_file and c.documented() and cfg.get_bool("SHOW_HEADERFILE"):
            o.append(f'<para><computeroutput>#include&lt;{xml_escape(c.inc_file)}&gt;</computeroutput></para>\n')
        secs = _sections_for(gen, c)
        for key, anchor_s, stitle, doc_anchor, doc_title, members in secs:
            o.append("<simplesect>\n")
            o.append(f"    <title>{xml_escape(stitle)}    </title>\n")
            o.append("        <itemizedlist>\n")
            for m in members:
                o.append(_db_decl(gen, c, m, ctx))
            o.append("        </itemizedlist>\n</simplesect>\n")
        detailed = gen._detailed_blocks(c)
        if detailed:
            o.append("<section>\n<title>Detailed Description</title>\n")
            o.append(docbook_blocks(detailed, ctx))
            o.append("</section>\n")
        for doc_title, members in _detailed_members(gen, secs):
            o.append("<section>\n")
            o.append(f"<title>{xml_escape(doc_title)}</title>\n")
            for m in members:
                o.append(_db_member_detail(gen, c, m, ctx))
            o.append("</section>\n")
        o.append("</section>\n")
        return "".join(o)

    inputs = []
    all_comps = []
    for f in project.files:
        if gen.file_documented(f) and f.language != "Markdown":
            all_comps.append(f)
    for c in project.compounds:
        if gen.compound_visible(c):
            all_comps.append(c)
    for c in all_comps:
        write_output_file(os.path.join(out_dir, c.id + ".xml"), compound_doc(c))
        inputs.append(c.id + ".xml")
    for f in project.files:
        if gen.file_documented(f):
            write_output_file(os.path.join(out_dir, f.id + "_source.xml"), _db_source(gen, f, ctx))
            inputs.append(f.id + "_source.xml")
    # index/annotated trivial chapters.
    if gen._classes:
        write_output_file(os.path.join(out_dir, "annotated.xml"), _db_index(gen, "Class List", [c.qualified for c in gen._classes]))
        inputs.append("annotated.xml")
    chapters = []
    if gen._classes:
        chapters.append("annotated.xml")
    chapters.extend(inputs)
    idx = ["<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n"]
    idx.append(f'<book xmlns="http://docbook.org/ns/docbook" version="5.0" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="_{xml_escape_attr(_project_name(cfg))}" xml:lang="en-US">\n')
    idx.append(f"<info><title>{xml_escape(_project_name(cfg))}</title></info>\n")
    seen = []
    for ch in chapters:
        if ch in seen:
            continue
        seen.append(ch)
        idx.append("<chapter>\n")
        idx.append(f'    <xi:include href="{ch}" xmlns:xi="http://www.w3.org/2001/XInclude"/>\n')
        idx.append("</chapter>\n")
    idx.append("<index/>\n</book>\n")
    write_output_file(os.path.join(out_dir, "index.xml"), "".join(idx))


def _db_index(gen, title, names):
    o = ["<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n"]
    o.append('<section xmlns="http://docbook.org/ns/docbook" version="5.0" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="_annotated" xml:lang="en-US">\n')
    o.append(f"<title>{xml_escape(title)}</title>\n<itemizedlist>\n")
    for n in names:
        o.append(f"<listitem><para>{xml_escape(n)}</para></listitem>\n")
    o.append("</itemizedlist>\n</section>\n")
    return "".join(o)


def _db_decl(gen, compound, m, ctx):
    if isinstance(m, Compound):
        return f'<listitem><para>{m.kind} <link linkend="_{xml_escape_attr(m.id)}">{xml_escape(m.qualified)}</link></para>\n</listitem>\n'
    anchor = "_" + m.id
    has_detail = gen.has_detail(m)
    name = m.qualified if (m.parent is not None and m.parent.kind == "namespace") else m.name
    if m.kind == "define":
        decl = f'<anchor xml:id="{xml_escape_attr(anchor)}"/>#define <emphasis role="strong">{xml_escape(m.name)}</emphasis>'
        if m.initializer:
            decl += "&#160;&#160;&#160;" + xml_escape(m.initializer)
    elif m.kind == "enum":
        kval = "enum class " if m.strong else "enum "
        vals = []
        for ev in m.enumvalues:
            if ev.doc.has_doc and not ev.doc.empty():
                vals.append(f'<link linkend="_{xml_escape_attr(_enumvalue_id(m, ev))}">{xml_escape(ev.name)}</link>')
            else:
                vals.append(f'<emphasis role="strong">{xml_escape(ev.name)}</emphasis>')
        link = f'<link linkend="_{xml_escape_attr(m.id)}">{xml_escape(name)}</link>' if has_detail else xml_escape(name)
        decl = kval + link + " { " + "\n, ".join(vals) + "\n }"
    elif m.kind == "typedef":
        decl = f'<anchor xml:id="{xml_escape_attr(anchor)}"/>typedef {xml_escape(m.type)} <emphasis role="strong">{xml_escape(name)}</emphasis>'
    elif m.kind == "function":
        if has_detail:
            nm = f'<link linkend="_{xml_escape_attr(m.id)}">{xml_escape(m.name)}</link>'
        else:
            nm = f'<emphasis role="strong">{xml_escape(m.name)}</emphasis>'
        decl = (xml_escape(m.type) + " " if m.type else "") + nm + " " + xml_escape(m.argsstring or "")
        if not has_detail:
            decl = f'<anchor xml:id="{xml_escape_attr(anchor)}"/>' + decl
    else:
        nm = f'<emphasis role="strong">{xml_escape(name)}</emphasis>'
        decl = (xml_escape(m.type) + " " if m.type else "") + nm
        decl = f'<anchor xml:id="{xml_escape_attr(anchor)}"/>' + decl
    out = f"<listitem><para>{decl}</para>\n"
    brief = blocks_to_text(m.doc.brief).strip() if hasattr(m, "doc") else ""
    if brief and gen.b("BRIEF_MEMBER_DESC"):
        out += docbook_blocks(m.doc.brief, ctx)
    out += "</listitem>\n"
    return out


def _db_member_detail(gen, compound, m, ctx):
    title = m.name + ("()" if m.kind == "function" else "")
    scope = compound.name if compound.kind == "file" else compound.qualified
    out = []
    out.append(f'<anchor xml:id="_{xml_escape_attr(m.id)}"/><section>\n')
    out.append(f"    <title>{xml_escape(title)}</title>\n")
    out.append(f"<indexterm><primary>{xml_escape(m.name)}</primary><secondary>{xml_escape(scope)}</secondary></indexterm>\n")
    out.append(f"<indexterm><primary>{xml_escape(scope)}</primary><secondary>{xml_escape(m.name)}</secondary></indexterm>\n")
    if m.kind == "function":
        decl = (f"{m.type} " if m.type else "") + m.name + " " + (m.argsstring or "")
        out.append(f"<para><computeroutput>{xml_escape(decl.strip())}</computeroutput></para>")
    elif m.kind == "enum":
        q = m.qualified
        out.append(f'<para><computeroutput>{"enum class " if m.strong else "enum "}<link linkend="_{xml_escape_attr(m.id)}">{xml_escape(q)}</link>' + ("<computeroutput>[strong]</computeroutput>" if m.strong else "") + "</computeroutput></para>")
    blocks = []
    if gen.b("REPEAT_BRIEF") and m.doc.brief:
        blocks.extend(m.doc.brief)
    blocks.extend(m.doc.detailed)
    out.append("<para>\n" if blocks else "")
    out.append(docbook_blocks(blocks, ctx))
    out.append("</para>\n" if blocks else "")
    if m.kind == "enum" and any(ev.doc.has_doc and not ev.doc.empty() for ev in m.enumvalues):
        out.append('<informaltable frame="all">\n<title>Enumerator</title>\n    <tgroup cols="2" align="left" colsep="1" rowsep="1">\n      <colspec colname=\'c1\'/>\n      <colspec colname=\'c2\'/>\n<tbody>\n')
        for ev in m.enumvalues:
            if ev.doc.has_doc and not ev.doc.empty():
                out.append(f"<row><entry><indexterm><primary>{xml_escape(ev.name)}</primary><secondary>{xml_escape(scope)}</secondary></indexterm>\n<indexterm><primary>{xml_escape(scope)}</primary><secondary>{xml_escape(ev.name)}</secondary></indexterm>\n<anchor xml:id=\"_{xml_escape_attr(_enumvalue_id(m, ev))}\"/>{xml_escape(ev.name)}</entry><entry>" + docbook_blocks(ev.doc.brief + ev.doc.detailed, ctx) + "</entry></row>\n")
        out.append("</tbody>\n</tgroup>\n</informaltable>\n")
    out.append("</section>\n")
    return "".join(out)


def _db_source(gen, f, ctx):
    lines = _code_lines(f.source or "", strip_comments=gen.b("STRIP_CODE_COMMENTS"))
    body = []
    for lineno, code in lines:
        body.append(f"{lineno} " + xml_escape(code).replace(" ", "&#32;") + "\n")
    return (
        "<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n"
        f'<section xmlns="http://docbook.org/ns/docbook" version="5.0" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="_{xml_escape_attr(f.id)}_source" xml:lang="en-US">\n'
        f"<title>{xml_escape(f.name)}</title>\n"
        "Go to the documentation of this file."
        '<programlisting linenumbering="unnumbered">' + "".join(body) + "</programlisting></section>\n"
    )


