"""Rendering doc blocks to man / LaTeX / DocBook / plain text."""

import re

from .names import xml_escape, xml_escape_attr

_SIMPLESECT_TITLES = {
    "return": "Returns", "note": "Note", "warning": "Warning",
    "attention": "Attention", "author": "Author", "date": "Date",
    "version": "Version", "since": "Since", "pre": "Precondition",
    "post": "Postcondition", "invariant": "Invariant",
    "remark": "Remarks", "see": "See also", "todo": "Todo",
    "test": "Test", "bug": "Bug", "deprecated": "Deprecated",
}


def man_escape(s):
    return s.replace("\\", "\\e").replace("-", "\\-").replace(".", "\\&.")


def _man_inline(nodes, ctx=None):
    out = []
    for n in nodes:
        t = n[0]
        if t == "text":
            out.append(man_escape(n[1]))
        elif t == "code":
            out.append(man_escape(n[1]))
        elif t == "bold":
            out.append("\\fB" + _man_inline(n[1]) + "\\fP")
        elif t == "emph":
            out.append("\\fI" + _man_inline(n[1]) + "\\fP")
        elif t == "ref":
            out.append(_man_inline(n[2] or [("text", n[1])]))
        elif t == "link":
            out.append(_man_inline(n[2]))
        elif t == "break":
            out.append("\n.br\n")
    return "".join(out)


def man_blocks(blocks, ctx=None):
    out = []
    for b in blocks:
        if b[0] == "para":
            out.append(_man_inline(b[1]).strip() + " \n")
        elif b[0] == "simplesect":
            title = _SIMPLESECT_TITLES.get(b[1], b[1].capitalize())
            out.append(f".PP\n\\fB{title}\\fP\n.RS 4\n")
            out.append(man_blocks(b[2], ctx))
            out.append(".RE\n")
        elif b[0] == "paramlist":
            title = {"param": "Parameters", "retval": "Return values", "templateparam": "Template Parameters"}.get(b[1], "Parameters")
            out.append(f".PP\n\\fB{title}\\fP\n.RS 4\n")
            for names, desc in b[2]:
                nm = ", ".join(str(x[0] if isinstance(x, tuple) else x) for x in names)
                out.append(f"\\fI{man_escape(nm)}\\fP " + man_blocks(desc, ctx).strip() + " \n.br\n")
            out.append(".RE\n")
        elif b[0] in ("codeblock", "verbatim", "verbatimpara"):
            out.append(man_escape(b[1]) + "\n")
        elif b[0] == "list":
            for item in b[2]:
                out.append(".IP \\(bu 2\n" + man_blocks(item, ctx))
        elif b[0] == "sect":
            title = _man_inline(b[3] or [])
            if title:
                out.append(f'.SS "{title.strip()}"\n')
            out.append(man_blocks(b[4], ctx))
        elif b[0] == "heading":
            out.append(f'.SS "{_man_inline(b[3]).strip()}"\n')
        elif b[0] == "only":
            if b[1] is None or "man" in b[1]:
                out.append(man_blocks(b[2], ctx))
    return "".join(out)


