def _latex_process_template(text, cfg, variables, conditions):
    if "\n" in text:
        text = text.split("\n", 1)[1]
    out = []
    stack = []
    marker_re = re.compile(r"%%(BEGIN|END)\s+(!?)([A-Z0-9_]+)")

    def active():
        return all(stack)

    for raw in text.splitlines(keepends=True):
        has_nl = raw.endswith("\n")
        line = raw[:-1] if has_nl else raw
        pieces = []
        pos = 0
        has_marker = False
        for m in marker_re.finditer(line):
            has_marker = True
