def _perl_escape(s):
    return str(s).replace("\\", "\\\\").replace("'", "\\'")


def _perl_value(v, indent=0):
    pad = " " * indent
    if isinstance(v, dict):
        if not v:
            return "{}"
        parts = []
        for k, val in v.items():
            parts.append(" " * (indent + 2) + f"{k} => " + _perl_value(val, indent + 2))
        return "{\n" + ",\n".join(parts) + "\n" + pad + "}"
    if isinstance(v, list):
        if not v:
            return "[\n" + pad + "]"
        parts = [" " * (indent + 2) + _perl_value(x, indent + 2) for x in v]
        return "[\n" + ",\n".join(parts) + "\n" + pad + "]"
    return "'" + _perl_escape(v) + "'"


def _perl_doc(blocks):
    out = []
    for b in blocks:
        if b[0] == "para":
            text = blocks_to_text([b]).strip("\n")
            out.append({"type": "parbreak"})
            out.append({"type": "text", "content": text + " "})
        elif b[0] == "paramlist":
            params = []
            for names, desc in b[2]:
                params.append({
                    "parameters": [{"name": str(n[0] if isinstance(n, tuple) else n)} for n in names],
                    "doc": _perl_doc_simple(desc),
                })
            out.append({"params": params})
        elif b[0] == "simplesect":
            out.append({b[1]: [{"type": "text", "content": blocks_to_text(b[2]).strip() + " "}]})
        elif b[0] in ("verbatim", "verbatimpara"):
            out.append({"type": "text", "content": b[1]})
        else:
            out.append({"type": "text", "content": blocks_to_text([b])})
    return {"doc": out} if out else {}


def _perl_doc_simple(blocks):
    out = []
    text = blocks_to_text(blocks).strip()
    if text:
        out.append({"type": "text", "content": text + " "})
    return out


def _perl_member(m):
    d = {}
    d["kind"] = m.kind
    d["name"] = m.name
    if m.kind == "function":
        d["virtualness"] = m.virt
    d["protection"] = m.prot
    d["static"] = "yes" if m.static else "no"
    d["brief"] = _perl_doc(m.doc.brief)
    d["detailed"] = _perl_doc(m.doc.detailed)
    if m.type:
        d["type"] = m.type
    if m.kind == "function":
        d["const"] = "yes" if m.const else "no"
        d["volatile"] = "yes" if m.volatile else "no"
        d["parameters"] = [
            {("declaration_name" if (p.get("declname") or p.get("defname")) else "type"): (p.get("declname") or p.get("defname") or p.get("type", "")), "type": p.get("type", "")} if (p.get("declname") or p.get("defname")) else {"type": p.get("type", "")}
            for p in m.params
        ]
        # Match the observed key order/shape for simple cases.
        fixed = []
        for p in m.params:
            pp = {}
            if p.get("declname") or p.get("defname"):
                pp["declaration_name"] = p.get("declname") or p.get("defname")
            pp["type"] = p.get("type", "")
            fixed.append(pp)
        # For C functions with named params the reference puts only type
        # in source for unnamed, and declaration_name/type for named but
        # with declaration_name first in the simple example.  Keep ours.
        d["parameters"] = fixed
    if m.initializer is not None:
        d["initializer"] = m.initializer
    return d


def generate_perlmod(project, cfg, out_base, config_name):
    facade = _Facade(project, cfg, lambda t: None)
    gen = facade.gen
    out_dir = os.path.join(out_base, "perlmod")
    os.makedirs(out_dir, exist_ok=True)
    if not cfg.get_bool("PERLMOD_PRETTY"):
        pass
    docs = {"classes": [], "concepts": [], "modules": [], "namespaces": [], "files": [], "groups": [], "pages": []}
    for c in project.compounds:
        if c.kind in ("class", "struct", "union", "interface") and gen.compound_visible(c):
            entry = {"name": c.qualified, "brief": _perl_doc(c.doc.brief), "detailed": _perl_doc(c.doc.detailed)}
            # Group members by section-ish kind.
            for kind_name, kind in (("functions", "function"), ("variables", "variable"), ("typedefs", "typedef"), ("enums", "enum")):
                ms = [m for m in c.members if m.kind == kind]
                if ms:
                    entry[kind_name] = {"members": [_perl_member(m) for m in ms]}
            docs["classes"].append(entry)
        elif c.kind == "namespace" and gen.compound_visible(c):
            entry = {"name": c.qualified, "brief": _perl_doc(c.doc.brief), "detailed": _perl_doc(c.doc.detailed)}
            docs["namespaces"].append(entry)
    for f in project.files:
        if not gen.file_documented(f):
            continue
        entry = {"name": f.name, "includes": [], "included_by": []}
        for kind_name, kind in (("functions", "function"), ("variables", "variable"), ("typedefs", "typedef"), ("enums", "enum"), ("defines", "define")):
            ms = [m for m in f.members if m.kind == kind]
            if ms:
                entry[kind_name] = {"members": [_perl_member(m) for m in ms]}
        entry["brief"] = _perl_doc(f.doc.brief)
        entry["detailed"] = _perl_doc(f.doc.detailed)
        docs["files"].append(entry)
    prefix = cfg.get_string("PERLMOD_MAKEVAR_PREFIX")
    varname = f"${prefix}doxydocs" if prefix else "$doxydocs"
    content = f"{varname}=\n" + _perl_value(docs, 0) + ";\n1;\n"
    write_output_file(os.path.join(out_dir, "DoxyDocs.pm"), content)
    write_output_file(os.path.join(out_dir, "DoxyStructure.pm"), resources.get_bytes("perlmod/DoxyStructure.pm"))
    cwd = os.getcwd()
    perlmod_abs = os.path.abspath(out_dir)
    doxyfile_abs = os.path.abspath(config_name if config_name != "-" else "Doxyfile")
    make = (
        ".PHONY: default clean\ndefault: clean\n\n"
        f"include {perlmod_abs}/doxyrules.make\n\nclean: clean-perlmod\n"
    )
    write_output_file(os.path.join(out_dir, "Makefile"), make)
    rules = (
        f"DOXY_EXEC_PATH = {cwd}\n"
        f"DOXYFILE = {doxyfile_abs}\n"
        f"DOXYDOCS_PM = {perlmod_abs}/DoxyDocs.pm\n"
        f"DOXYSTRUCTURE_PM = {perlmod_abs}/DoxyStructure.pm\n"
        f"DOXYRULES = {perlmod_abs}/doxyrules.make\n\n"
        ".PHONY: clean-perlmod\nclean-perlmod::\n\trm -f $(DOXYSTRUCTURE_PM) \\\n\t$(DOXYDOCS_PM)\n\n"
        "$(DOXYRULES) \\\n$(DOXYMAKEFILE) \\\n$(DOXYSTRUCTURE_PM) \\\n$(DOXYDOCS_PM): \\\n\t$(DOXYFILE)\n\tcd $(DOXY_EXEC_PATH) ; doxygen \"$<\"\n"
    )
    write_output_file(os.path.join(out_dir, "doxyrules.make"), rules)


def _rtf_escape(s):
    out = []
    for ch in s:
        if ch in "\\{}":
            out.append("\\" + ch)
        elif ord(ch) > 127:
            out.append(f"\\u{ord(ch)}?")
        else:
            out.append(ch)
    return "".join(out)


def generate_rtf(project, cfg, out_base, messenger, warner):
    facade = _Facade(project, cfg, warner.warn)
    gen = facade.gen
    out_dir = os.path.join(out_base, cfg.get_string("RTF_OUTPUT") or "rtf")
    os.makedirs(out_dir, exist_ok=True)
    parts = []
    parts.append("{\\rtf1\\ansi\\ansicpg1252\\deff0\n")
    parts.append("{\\fonttbl{\\f0\\froman\\fcharset0 Times New Roman;}{\\f1\\fswiss\\fcharset0 Arial;}}\n")
    parts.append(f"{{\\info{{\\title {_rtf_escape(_project_name(cfg))}}}}}\n")
    for f in project.files:
        if not gen.file_documented(f):
            continue
        parts.append(f"\\sect\\pard\\plain\\s1\\sb240\\sa60\\keepn\\widctlpar\\adjustright\\b\\f1\\fs36\\kerning36\\cgrid {{\\b {_rtf_escape(f.name)} File Reference}}\\par\n")
        parts.append(_rtf_escape(blocks_to_text(gen._detailed_blocks(f))) + "\\par\n")
        for m in f.members:
            if m.documented():
                parts.append(f"\\pard\\plain\\s2\\sb240\\sa60\\keepn {{\\b {_rtf_escape(m.name)}}}\\par\n")
                parts.append(_rtf_escape(blocks_to_text(m.doc.brief + m.doc.detailed)) + "\\par\n")
    for c in project.compounds:
        if c.kind in ("class", "struct") and gen.compound_visible(c):
            parts.append(f"\\sect\\pard\\plain\\s1 {{\\b {_rtf_escape(c.qualified)} Class Reference}}\\par\n")
            parts.append(_rtf_escape(blocks_to_text(gen._detailed_blocks(c))) + "\\par\n")
            for m in c.members:
                if m.documented():
                    parts.append(f"\\pard\\plain\\s2 {{\\b {_rtf_escape(m.name)}}}\\par\n")
                    parts.append(_rtf_escape(blocks_to_text(m.doc.brief + m.doc.detailed)) + "\\par\n")
    parts.append("}\n")
    write_output_file(os.path.join(out_dir, "refman.rtf"), "".join(parts))


