def generate_sqlite(project, cfg, out_base):
    facade = _Facade(project, cfg, lambda t: None)
    gen = facade.gen
    out_dir = os.path.join(out_base, cfg.get_string("SQLITE3_OUTPUT") or "sqlite3")
    os.makedirs(out_dir, exist_ok=True)
    dbpath = os.path.join(out_dir, "doxygen_sqlite3.db")
    if cfg.get_bool("SQLITE3_RECREATE_DB") and os.path.exists(dbpath):
        os.remove(dbpath)
    schema = _sqlite_schema()
    if os.path.exists(dbpath):
        os.remove(dbpath)
    conn = sqlite3.connect(dbpath)
    try:
        conn.executescript(schema)
        # Fill the main tables best-effort based on column names.
        _sqlite_fill(conn, project, cfg, gen)
        conn.commit()
    finally:
        conn.close()


def _sqlite_schema():
    global _SQLITE_SCHEMA
    if _SQLITE_SCHEMA is None:
        _SQLITE_SCHEMA = resources.get_text("sqlite_schema.sql")
    return _SQLITE_SCHEMA


def _table_columns(conn, table):
    try:
        return [r[1] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()]
    except sqlite3.Error:
        return []


def _insert_named(conn, table, values):
    cols = _table_columns(conn, table)
    use = [c for c in values if c in cols]
    if not use:
        return None
    sql = f"INSERT INTO {table} (" + ",".join(use) + ") VALUES (" + ",".join("?" for _ in use) + ")"
    try:
        cur = conn.execute(sql, [values[c] for c in use])
        return cur.lastrowid
    except sqlite3.Error:
        return None


def _sqlite_fill(conn, project, cfg, gen):
    # meta table (observed in the generated db): rows for doxygen version.
    _insert_named(conn, "meta", {"doxygen_version": "1.17.0", "schema_version": "1.0.0", "generated_at": "", "generated_on": "", "project_name": _project_name(cfg)})
    # path/name tables if present.
    path_ids = {}
    name_ids = {}
    refid_ids = {}

    def path_id(path):
        if path in path_ids:
            return path_ids[path]
        rid = _insert_named(conn, "path", {"path": path})
        path_ids[path] = rid or (len(path_ids) + 1)
        return path_ids[path]

    def name_id(name):
        if name in name_ids:
            return name_ids[name]
        rid = _insert_named(conn, "name", {"name": name})
        name_ids[name] = rid or (len(name_ids) + 1)
        return name_ids[name]

    def refid_id(refid):
        if refid in refid_ids:
            return refid_ids[refid]
        rid = _insert_named(conn, "refid", {"refid": refid})
        refid_ids[refid] = rid or (len(refid_ids) + 1)
        return refid_ids[refid]

    for f in project.files:
        path_id(os.path.dirname(f.abs_path or "") or ".")
        _insert_named(conn, "file", {
            "name": f.name,
            "path": f.abs_path or f.name,
            "refid": f.id,
        })
    compound_ids = {}
    for c in project.compounds + project.files:
        values = {
            "name": c.qualified if c.kind != "file" else c.name,
            "kind": c.kind,
            "refid": c.id,
            "rowid": None,
        }
        rid = _insert_named(conn, "compounddef", values)
        compound_ids[id(c)] = rid
    member_sqlids = {}
    for m in project.all_members:
        values = {
            "name": m.name,
            "kind": m.kind,
            "refid": m.id,
            "type": m.type,
            "argsstring": m.argsstring,
            "scope_rowid": compound_ids.get(id(m.parent)) if m.parent is not None else None,
            "definition": m.definition,
            "brief": blocks_to_text(m.doc.brief).strip(),
            "detailed": blocks_to_text(m.doc.detailed).strip(),
        }
        rid = _insert_named(conn, "memberdef", values)
        member_sqlids[id(m)] = rid
        for p in m.params:
            _insert_named(conn, "param", {
                "memberdef_rowid": rid,
                "type": p.get("type", ""),
                "declname": p.get("declname") or p.get("defname") or "",
                "defval": p.get("defval") or "",
            })


