            out.append(_man_inline(n[2] or [("text", n[1])]))
        elif t == "link":
            out.append(_man_inline(n[2]))
        elif t == "break":
            out.append("\n.br\n")
    return "".join(out)


def man_blocks(blocks, ctx=None):
    out = []
    for b in blocks:
        if b[0] == "para":
            out.append(_man_inline(b[1]).strip() + " \n")
        elif b[0] == "simplesect":
            title = _SIMPLESECT_TITLES.get(b[1], b[1].capitalize())
            out.append(f".PP\n\\fB{title}\\fP\n.RS 4\n")
            out.append(man_blocks(b[2], ctx))
            out.append(".RE\n")
        elif b[0] == "paramlist":
            title = {"param": "Parameters", "retval": "Return values", "templateparam": "Template Parameters"}.get(b[1], "Parameters")
            out.append(f".PP\n\\fB{title}\\fP\n.RS 4\n")
            for names, desc in b[2]:
                nm = ", ".join(str(x[0] if isinstance(x, tuple) else x) for x in names)
                out.append(f"\\fI{man_escape(nm)}\\fP " + man_blocks(desc, ctx).strip() + " \n.br\n")
            out.append(".RE\n")
        elif b[0] in ("codeblock", "verbatim", "verbatimpara"):
            out.append(man_escape(b[1]) + "\n")
        elif b[0] == "list":
            for item in b[2]:
                out.append(".IP \\(bu 2\n" + man_blocks(item, ctx))
        elif b[0] == "sect":
            title = _man_inline(b[3] or [])
            if title:
                out.append(f'.SS "{title.strip()}"\n')
            out.append(man_blocks(b[4], ctx))
        elif b[0] == "heading":
            out.append(f'.SS "{_man_inline(b[3]).strip()}"\n')
        elif b[0] == "only":
            if b[1] is None or "man" in b[1]:
                out.append(man_blocks(b[2], ctx))
    return "".join(out)


# ---------------------------------------------------------------------------
# LaTeX

_LATEX_MAP = {
    "\\": "\\textbackslash{}", "&": "\\&", "%": "\\%", "$": "\\$",
    "#": "\\#", "_": "\\_", "{": "\\{", "}": "\\}",
    "~": "\\textasciitilde{}", "^": "\\textasciicircum{}",
    "<": "$<$", ">": "$>$", "|": "$|$",
}


def latex_escape(s):
    return "".join(_LATEX_MAP.get(c, c) for c in s)


def latex_word(s):
    """Escape and insert \\+ discretionary breaks, as in name/title
    contexts of the reference output."""
    esc = latex_escape(s)
    # Insert \+ after '.', after '::', and before an uppercase letter
    # following a lowercase/digit, or following ':'.
    out = []
    prev = ""
    for i, ch in enumerate(esc):
        if i and ch.isupper() and (prev.islower() or prev.isdigit()):
            out.append("\\+")
        out.append(ch)
        if ch == ".":
            out.append("\\+")
        prev = ch
    res = "".join(out)
    res = res.replace("::", "::\\+")
    return res


def _latex_inline(nodes, ctx=None):
    out = []
    for n in nodes:
        t = n[0]
        if t == "text":
            txt = n[1]
            # Autolink-like linking is skipped in favour of plain text in
            # this first implementation except explicit refs below.
            out.append(latex_escape(txt))
        elif t == "code":
            out.append("\\texttt{" + latex_escape(n[1]) + "}")
        elif t == "bold":
            out.append("\\textbf{" + _latex_inline(n[1]) + "}")
        elif t == "emph":
            out.append("\\textit{" + _latex_inline(n[1]) + "}")
        elif t == "ref":
            target = n[1]
            disp = _latex_inline(n[2]) if len(n) > 2 and n[2] else latex_escape(target)
            ent = ctx.resolve(target) if ctx is not None else None
            if ent is not None:
                out.append("\\doxymbox{\\hyperlink{" + getattr(ent, "id", target) + "}{" + disp + "}}")
            else:
                out.append(disp)
        elif t == "link":
            out.append("\\href{" + latex_escape(n[1]) + "}{" + _latex_inline(n[2]) + "}")
        elif t == "break":
            out.append(" \\\\\n")
    return "".join(out)


def latex_blocks(blocks, ctx=None):
    out = []
    for b in blocks:
        if b[0] == "para":
            out.append(_latex_inline(b[1], ctx).strip() + " \n")
        elif b[0] == "simplesect":
            kind = b[1]
            env = {"return": "DoxyReturn", "note": "DoxyNote", "warning": "DoxyWarning",
                   "attention": "DoxyAttention", "pre": "DoxyPre", "post": "DoxyPost",
                   "invariant": "DoxyInvariant", "remark": "DoxyRemark",
                   "todo": "DoxyTodo", "test": "DoxyTest", "bug": "DoxyBug",
                   "deprecated": "DoxyDeprecated"}.get(kind)
            inner = latex_blocks(b[2], ctx)
            if env:
                out.append(f"\\begin{{{env}}}{{{_SIMPLESECT_TITLES.get(kind, kind.capitalize())}}}\n{inner}\\end{{{env}}}\n")
            else:
                out.append(inner)
        elif b[0] == "paramlist":
            env = "DoxyParams" if b[1] == "param" else "DoxyRetVals" if b[1] == "retval" else "DoxyTemplParams"
            rows = []
            for names, desc in b[2]:
                nm = ", ".join(str(x[0] if isinstance(x, tuple) else x) for x in names)
                rows.append("{\\em " + latex_escape(nm) + "} & " + latex_blocks(desc, ctx).strip() + " \\\\\n\\hline\n")
            out.append(f"\\begin{{{env}}}{{Parameters}}\n" + "".join(rows) + f"\\end{{{env}}}\n")
        elif b[0] in ("codeblock", "verbatim"):
            out.append("\\begin{DoxyCode}{" + (b[2] if len(b) > 2 else "") + "}\n")
            out.append(b[1] + "\n")
            out.append("\\end{DoxyCode}\n")
        elif b[0] == "verbatimpara":
            out.append(latex_escape(b[1]) + "\n")
        elif b[0] == "list":
            env = "DoxyEnumerate" if b[1] else "DoxyItemize"
            out.append(f"\\begin{{{env}}}\n")
            for item in b[2]:
                out.append("\\item " + latex_blocks(item, ctx))
            out.append(f"\\end{{{env}}}\n")
        elif b[0] == "sect":
            out.append("\\doxysubsection{" + _latex_inline(b[3] or [], ctx) + "}\n")
            out.append(latex_blocks(b[4], ctx))
        elif b[0] == "only":
            if b[1] is None or "latex" in b[1]:
                out.append(latex_blocks(b[2], ctx))
    return "".join(out)


# ---------------------------------------------------------------------------
# DocBook


def _db_inline(nodes, ctx=None):
    out = []
    for n in nodes:
        t = n[0]
        if t == "text":
            out.append(xml_escape(n[1]))
        elif t == "code":
            out.append("<computeroutput>" + xml_escape(n[1]) + "</computeroutput>")
        elif t == "bold":
            out.append('<emphasis role="strong">' + _db_inline(n[1]) + "</emphasis>")
        elif t == "emph":
            out.append("<emphasis>" + _db_inline(n[1]) + "</emphasis>")
        elif t == "ref":
            target = n[1]
            disp = _db_inline(n[2]) if len(n) > 2 and n[2] else xml_escape(target)
            ent = ctx.resolve(target) if ctx is not None else None
            if ent is not None:
                out.append(f'<link linkend="_{xml_escape_attr(getattr(ent, "id", target))}">{disp}</link>')
            else:
                out.append(disp)
        elif t == "link":
            out.append(f'<link linkend="{xml_escape_attr(n[1])}">{_db_inline(n[2])}</link>')
        elif t == "break":
            out.append("\n")
    return "".join(out)


def docbook_blocks(blocks, ctx=None):
    out = []
    for b in blocks:
        if b[0] == "para":
            out.append("<para>" + _db_inline(b[1], ctx) + "</para>\n")
        elif b[0] == "simplesect":
            title = _SIMPLESECT_TITLES.get(b[1], b[1].capitalize())
            inner = docbook_blocks(b[2], ctx)
            out.append("<para>\n                <formalpara><title>" + title + "</title>\n\n" + inner + "</formalpara>\n</para>\n")
        elif b[0] == "paramlist":
            title = {"param": "Parameters", "retval": "Return values", "templateparam": "Template Parameters"}.get(b[1], "Parameters")
            out.append("<para>\n                <formalpara>\n                    <title>\n" + title + "</title>\n                    <para>\n")
            out.append('                    <table frame="all">\n                        <tgroup cols="2" align="left" colsep="1" rowsep="1">\n                        <colspec colwidth="1*"/>\n                        <colspec colwidth="4*"/>\n                        <tbody>\n')
            for names, desc in b[2]:
                nm = ", ".join(str(x[0] if isinstance(x, tuple) else x) for x in names)
                out.append("                            <row>\n<entry>" + xml_escape(nm) + "</entry><entry>\n" + docbook_blocks(desc, ctx) + "</entry>\n                            </row>\n")
            out.append("                        </tbody>\n                        </tgroup>\n                    </table>\n                    </para>\n                </formalpara>\n                </para>\n")
        elif b[0] in ("codeblock", "verbatim"):
            out.append("<para><programlisting>" + xml_escape(b[1]) + "</programlisting></para>\n")
        elif b[0] == "verbatimpara":
            out.append("<para>" + xml_escape(b[1]) + "</para>\n")
        elif b[0] == "list":
            listtag = "orderedlist" if b[1] else "itemizedlist"
            out.append(f"<para><{listtag}>\n")
            for item in b[2]:
                out.append("<listitem>" + docbook_blocks(item, ctx).strip() + "</listitem>\n")
            out.append(f"</{listtag}>\n</para>\n")
        elif b[0] == "sect":
            out.append("<section>\n<title>" + _db_inline(b[3] or [], ctx) + "</title>\n")
            out.append(docbook_blocks(b[4], ctx))
            out.append("</section>\n")
        elif b[0] == "only":
            if b[1] is None or "docbook" in b[1]:
                out.append(docbook_blocks(b[2], ctx))
    return "".join(out)
