                lines.append(f"      {pfx}-prot = {m.prot};\n")
                if m.type:
                    lines.append(f"      {pfx}-type = {_def_text(m.type)}\n")
                lines.append(f"      {pfx}-name = '{m.name}';\n")
                for prm in m.params:
                    lines.append(f"      {pfx}-param = {{\n")
                    lines.append(f"        {pfx}-param-type = {_def_text(prm.get('type',''))}\n")
                    if prm.get("declname") or prm.get("defname"):
                        lines.append(f"        {pfx}-param-declname = '{prm.get('declname') or prm.get('defname')}';\n")
                    lines.append(f"      }}; /*        {pfx}-param--param */\n")
                absf = f.abs_path or f.name
                lines.append(f"      {pfx}-desc-file = '{absf}';\n")
                lines.append(f"      {pfx}-desc-line = '{m.location.line}';\n")
                brief = blocks_to_text(m.doc.brief).strip()
                lines.append(f"      {pfx}-briefdesc =    {_def_text(brief)}\n")
                # Raw documentation is reconstructed as command text (best effort).
                raw_docs = _raw_doc_text(m)
                lines.append(f"      {pfx}-documentation = {_def_text(raw_docs)}\n")
                lines.append(f"    }}; /* {group}-member */\n")
            if raw_kind is not None:
                lines.append("    };\n")
        lines.append(f"  file-full-name  = '{f.abs_path or f.name}';\n")
        lines.append("  file-first-line = '1';\n")
        lines.append(f"  file-briefdesc  = {_def_text(blocks_to_text(f.doc.brief).strip())}\n")
        raw_f = "\n\n" if f.doc.detailed == [] else blocks_to_text(f.doc.detailed).strip()
        lines.append(f"  file-documentation = {_def_text(raw_f)}\n")
        lines.append("}; /* file */\n")
    write_output_file(os.path.join(out_dir, "doxygen.def"), "".join(lines))


def _raw_doc_text(m):
    parts = []
    for blk in m.doc.detailed:
        if blk[0] == "paramlist" and blk[1] == "param":
            for names, desc in blk[2]:
                nm = str(names[0][0]) if names else ""
                parts.append(f"@param {nm} " + blocks_to_text(desc).strip())
        elif blk[0] == "simplesect":
            cmd = blk[1]
            parts.append(f"@{cmd} " + blocks_to_text(blk[2]).strip())
    return "\n".join(parts)


