def _latex_member_detail(gen, compound, m):
    anchor = _latex_anchor(compound, m)
    out = []
    title = m.name + ("()" if m.kind == "function" else "")
    scope = compound.qualified if compound.kind != "file" else compound.name
    out.append(f"\\Hypertarget{{{anchor}}}\\index{{{latex_escape(scope)}@{{{latex_escape(scope)}}}!{latex_escape(m.name)}@{{{latex_escape(m.name)}}}}}\n")
    out.append(f"\\index{{{latex_escape(m.name)}@{{{latex_escape(m.name)}}}!{latex_escape(scope)}@{{{latex_escape(scope)}}}}}\n")
    out.append(f"\\doxysubsubsection{{\\texorpdfstring{{{latex_escape(title)}}}{{{latex_escape(title)}}}}}\n")
    out.append("{\\footnotesize\\ttfamily \\label{" + anchor + "} \n")
    if m.kind == "function":
        proto = (f"{m.type} " if m.type else "")
        if compound.kind in ("class", "struct"):
            proto += compound.qualified + "::"
        proto += m.name + " "
        out.append(latex_escape(proto))
        if m.params:
            out.append("(\\begin{DoxyParamCaption}")
            parts = []
            for p in m.params:
                nm = p.get("declname") or p.get("defname") or ""
                parts.append("\\item[{" + latex_escape(p.get("type", "")) + "}]{" + latex_escape(nm) + "}{")
            out.append(", }".join(parts))
            out.append("}\\end{DoxyParamCaption})")
            if m.const:
                out.append(" const")
        else:
            out.append(latex_escape(m.argsstring or ""))
        out.append("}\n\n")
    elif m.kind == "enum":
        kval = "enum class " if m.strong else "enum "
        out.append(latex_escape(kval) + f"\\doxymbox{{\\hyperlink{{{anchor}}}{{{latex_word(m.qualified)}}}}}" + ("{[}strong{]}" if m.strong else "") + "}\n\n")
    else:
        decl = m.definition or ((m.type + " ") if m.type else "") + m.qualified
        out.append(latex_escape(decl) + "}\n\n")
    blocks = []
    if gen.b("REPEAT_BRIEF") and m.doc.brief:
        blocks.extend(m.doc.brief)
    blocks.extend(m.doc.detailed)
    if blocks:
        out.append("\n" + latex_blocks(blocks, gen.ctx))
    if m.kind == "enum" and any(ev.doc.has_doc and not ev.doc.empty() for ev in m.enumvalues):
        out.append("\\begin{DoxyEnumFields}[2]{Enumerator}\n")
        for ev in m.enumvalues:
            if ev.doc.has_doc and not ev.doc.empty():
                out.append(f"\\raisebox{{\\heightof{{T}}[0pt][0pt]}} {{\\Hypertarget{{{anchor}a{_md5(ev.name)}}}\\label{{{anchor}a{_md5(ev.name)}}}{latex_escape(ev.name)}}} & " + latex_blocks(ev.doc.brief + ev.doc.detailed, gen.ctx).strip() + "\\\\\n")
        out.append("\\end{DoxyEnumFields}\n")
    return "".join(out)


def _latex_source(gen, f):
    out = [f"\\doxysection{{{latex_word(f.name)}}}\n"]
    out.append(f"\\hypertarget{{{f.id}_source}}{{}}")
    out.append(f"\\label{{{f.id}_source}}\\doxymbox{{\\hyperlink{{{f.id}}}{{Go to the documentation of this file.}}}}\n")
    out.append("\\begin{DoxyCode}{0}\n")
    for lineno, code in _code_lines(f.source or "", strip_comments=gen.b("STRIP_CODE_COMMENTS")):
        out.append(code + "\n")
    out.append("\\end{DoxyCode}\n")
    return "".join(out)


