                out.append(f"\\raisebox{{\\heightof{{T}}[0pt][0pt]}} {{\\Hypertarget{{{anchor}a{_md5(ev.name)}}}\\label{{{anchor}a{_md5(ev.name)}}}{latex_escape(ev.name)}}} & " + latex_blocks(ev.doc.brief + ev.doc.detailed, gen.ctx).strip() + "\\\\\n")
        out.append("\\end{DoxyEnumFields}\n")
    return "".join(out)


def _latex_source(gen, f):
    out = [f"\\doxysection{{{latex_word(f.name)}}}\n"]
    out.append(f"\\hypertarget{{{f.id}_source}}{{}}")
    out.append(f"\\label{{{f.id}_source}}\\doxymbox{{\\hyperlink{{{f.id}}}{{Go to the documentation of this file.}}}}\n")
    out.append("\\begin{DoxyCode}{0}\n")
    for lineno, code in _code_lines(f.source or "", strip_comments=gen.b("STRIP_CODE_COMMENTS")):
        out.append(code + "\n")
    out.append("\\end{DoxyCode}\n")
    return "".join(out)


# --------------------------------------------------------------------------
# DocBook


def generate_docbook(project, cfg, out_base, messenger, warner):
    facade = _Facade(project, cfg, warner.warn)
    gen = facade.gen
    ctx = gen.ctx
    out_dir = os.path.join(out_base, cfg.get_string("DOCBOOK_OUTPUT") or "docbook")
    os.makedirs(out_dir, exist_ok=True)

    def compound_doc(c):
        kind = c.kind
        title = {
            "file": f"{c.name} File Reference",
            "class": f"{c.qualified} Class Reference",
            "struct": f"{c.qualified} Struct Reference",
            "union": f"{c.qualified} Union Reference",
            "interface": f"{c.qualified} Interface Reference",
            "namespace": f"{c.qualified} Namespace Reference",
        }.get(kind, c.qualified)
        o = []
        o.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
        o.append(f'<section xmlns="http://docbook.org/ns/docbook" version="5.0" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="_{xml_escape_attr(c.id)}" xml:lang="en-US">\n')
        o.append(f"<title>{xml_escape(title)}</title>\n")
        indexname = c.name if kind == "file" else c.qualified
        o.append(f"<indexterm><primary>{xml_escape(indexname)}</primary></indexterm>\n")
        if c.doc.brief:
            o.append("<para>\n\n" + docbook_blocks(c.doc.brief, ctx) + " \n</para>\n")
        if kind in ("class", "struct") and c.inc_file and c.documented() and cfg.get_bool("SHOW_HEADERFILE"):
            o.append(f"<para>\n<computeroutput>#include&lt;{xml_escape(c.inc_file)}&gt;</computeroutput></para>\n")
        secs = _sections_for(gen, c)
        for key, anchor_s, stitle, doc_anchor, doc_title, members in secs:
            o.append("<simplesect>\n")
            o.append(f"    <title>{xml_escape(stitle)}    </title>\n")
            o.append("        <itemizedlist>\n")
            for m in members:
                o.append(_db_decl(gen, c, m, ctx))
            o.append("        </itemizedlist>\n</simplesect>\n")
        detailed = gen._detailed_blocks(c)
        if detailed:
            o.append("<section>\n<title>Detailed Description</title>\n")
            o.append(docbook_blocks(detailed, ctx))
            o.append("</section>\n")
        for doc_title, members in _detailed_members(gen, secs):
            o.append("<section>\n")
            o.append(f"<title>{xml_escape(doc_title)}</title>\n")
            for m in members:
                o.append(_db_member_detail(gen, c, m, ctx))
            o.append("</section>\n")
        o.append("</section>\n")
        return "".join(o)

    all_comps = []
    for f in project.files:
        if gen.file_documented(f) and f.language != "Markdown":
            all_comps.append(f)
    for c in project.compounds:
        if gen.compound_visible(c):
            all_comps.append(c)
    for c in all_comps:
        write_output_file(os.path.join(out_dir, c.id + ".xml"), compound_doc(c))
    for f in project.files:
        if gen.file_documented(f):
            write_output_file(os.path.join(out_dir, f.id + "_source.xml"), _db_source(gen, f, ctx))
    if gen._classes:
        write_output_file(os.path.join(out_dir, "annotated.xml"), _db_annotated(gen, ctx))
    classes_inputs = [c.id + ".xml" for c in all_comps if c.kind in ("class", "struct", "union", "interface")]
    ns_inputs = [c.id + ".xml" for c in all_comps if c.kind == "namespace"]
    chapters = []
    if classes_inputs:
        chapters.append(("Class Documentation", classes_inputs))
    if ns_inputs:
        chapters.append(("Namespace Documentation", ns_inputs))
    file_chapter_inputs = []
    for f in project.files:
        if gen.file_documented(f) and f.language != "Markdown":
            file_chapter_inputs.append(f.id + ".xml")
            file_chapter_inputs.append(f.id + "_source.xml")
    if file_chapter_inputs:
        chapters.append(("File Documentation", file_chapter_inputs))
    idx = ["<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n"]
    idx.append('<book xmlns="http://docbook.org/ns/docbook" version="5.0" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="_index" xml:lang="en-US">\n')
    idx.append("    <info>\n")
    idx.append(f"    <title>{xml_escape(_project_name(cfg))}</title>\n")
    idx.append("    </info>\n")
    seen_ch = set()
    for title_ch, incs in chapters:
        idx.append("<chapter>\n")
        idx.append(f"    <title>{xml_escape(title_ch)}</title>\n")
        for ch in incs:
            if ch in seen_ch:
                continue
            seen_ch.add(ch)
            idx.append(f'    <xi:include href="{ch}" xmlns:xi="http://www.w3.org/2001/XInclude"/>\n')
        idx.append("</chapter>\n")
    idx.append("<index/>\n</book>\n")
    write_output_file(os.path.join(out_dir, "index.xml"), "".join(idx))


