def _latex_source(gen, f):
    out = [f"\\doxysection{{{latex_word(f.name)}}}\n"]
    out.append(f"\\hypertarget{{{f.id}_source}}{{}}")
    out.append(f"\\label{{{f.id}_source}}\\doxymbox{{\\hyperlink{{{f.id}}}{{Go to the documentation of this file.}}}}\n")
