"friends":"/** @file t.h */\n/** @brief C */\nclass C { /** @brief helper */ friend void helper(C &c); friend class Other; };\n",
"inbody":"/** @file t.h */\n/** @brief f */\nint f() { /** in body text */ return 1; }\n",
}
